INSERT INTO `bh_admins` VALUES (1, 'spr', '$argon2id$v=19$m=65536,t=4,p=1$Vy93TjVJUXloTExsMkpNag$uq50emrpl1C0b3jttbeXpjfqPzHzAbUVzYOZwxcZv94', 'admin', '2026-11-21 14:33:31', NULL, '2026-11-22 10:15:35');
INSERT INTO `bh_concepts` VALUES (78, 'unclosed-brackets', 'Unclosed brackets', 'Every opening bracket needs a matching closing one.', '## What it is\n\nBrackets - `(`, `[`, `{` - always come in matching pairs. Python keeps reading until it finds the close.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: \'(\' was never closed\n```\n\n## How to spot it\n\nCount opening and closing brackets on the line Python points to - they should match.\n\n## How to fix it\n\nAdd the missing closing bracket in the right place.\n\n## Try it\n\n```python run\nprint(\"Hello\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (79, 'strings-quotes', 'Strings and quotes', 'A string needs matching quote marks at both ends.', '## What it is\n\nA string literal starts and ends with the same kind of quote mark, `\"` or `\'`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: unterminated string literal\n```\n\n## How to spot it\n\nCount quote marks in pairs, the same way you\'d count brackets.\n\n## How to fix it\n\nAdd the missing closing quote mark.\n\n## Try it\n\n```python run\ngreeting = \"Hello, world!\"\nprint(greeting)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (80, 'block-syntax', 'Colons and blocks', 'Every block header (if, for, while, def, class...) ends in a colon.', '## What it is\n\nAny line that starts an indented block - `if`, `elif`, `else`, `for`, `while`, `def`, `class`, `try`, `except` - must end with a colon `:`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: expected \':\'\n```\n\nPython points at the end of the line that\'s missing it.\n\n## How to spot it\n\nScan every line that should open a block. Does it end in `:`?\n\n## How to fix it\n\nAdd the colon at the end of the header line.\n\n## Try it\n\n```python run\nfor i in range(3):\n    print(i)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (81, 'indentation', 'Indentation', 'Python uses indentation, not brackets, to show block structure.', '## What it is\n\nAfter a colon-ended line, the body must be indented one level in, consistently.\n\n## What it looks like when it goes wrong\n\n```\nIndentationError: expected an indented block\nIndentationError: unexpected indent\nTabError: inconsistent use of tabs and spaces in indentation\n```\n\n## How to spot it\n\nCompare a line\'s indentation to its neighbours - are they using the same character (spaces, not tabs) and the same amount?\n\n## How to fix it\n\nRe-indent consistently, using spaces throughout.\n\n## Try it\n\n```python run\ndef double(n):\n    return n * 2\n\nprint(double(5))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (82, 'case-sensitivity', 'Case sensitivity', 'Print, print and PRINT are three different names to Python.', '## What it is\n\nPython treats names with different capitalisation as completely different names.\n\n## What it looks like when it goes wrong\n\n```\nNameError: name \'Print\' is not defined\n```\n\n## How to spot it\n\nIf a `NameError` names something that looks like a familiar built-in or keyword, check its capitalisation.\n\n## How to fix it\n\nMatch the exact case Python expects - built-ins and keywords are lowercase.\n\n## Try it\n\n```python run\nprint(\"case matters\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (83, 'assignment-vs-comparison', 'Assignment vs comparison', '= stores a value; == asks if two values are equal.', '## What it is\n\n`=` assigns a value to a name. `==` compares two values and gives back `True` or `False`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax. Maybe you meant \'==\' instead of \'=\'?\n```\n\n## How to spot it\n\nLook inside any `if` or `while` condition for a single `=`.\n\n## How to fix it\n\nChange it to `==` if you\'re comparing, not assigning.\n\n## Try it\n\n```python run\nx = 5\nif x == 5:\n    print(\"five\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (84, 'keywords', 'Python\'s keywords', 'Keywords are fixed, exact words - elif, not elseif.', '## What it is\n\nPython has a fixed set of reserved words (`if`, `elif`, `else`, `for`, `in`, `and`, `or`, `not`, and more) that must be spelled exactly.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nIf you\'ve used another language before, double-check Python\'s exact spelling rather than assuming it matches.\n\n## How to fix it\n\nUse Python\'s real keyword (e.g. `elif`, not `elseif`).\n\n## Try it\n\n```python run\nscore = 72\nif score >= 50:\n    print(\"Pass\")\nelif score >= 0:\n    print(\"Fail\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (85, 'bracket-types', 'Bracket types', '(), [] and {} each mean something different.', '## What it is\n\n`()` calls a function or groups an expression. `[]` indexes into a sequence or builds a list. `{}` builds a set or dictionary.\n\n## What it looks like when it goes wrong\n\n```\nTypeError: \'builtin_function_or_method\' object is not subscriptable\n```\n\n## How to spot it\n\nAsk: am I calling something, or indexing into something? That decides which bracket.\n\n## How to fix it\n\nUse `()` to call a function or method, `[]` to index.\n\n## Try it\n\n```python run\nword = \"hello\"\nprint(word.upper())\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (86, 'function-syntax', 'Function definition syntax', 'def name(params): is the required shape.', '## What it is\n\nA function definition always follows the shape `def name(parameters):`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nCheck every `def` line has all four pieces: `def`, a name, parentheses, and a colon.\n\n## How to fix it\n\nAdd whichever piece is missing.\n\n## Try it\n\n```python run\ndef square(n):\n    return n * n\n\nprint(square(4))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (87, 'names-and-scope', 'Names and scope', 'A name only exists once it\'s been created, exactly as spelled.', '## What it is\n\nPython only recognises a name once something has assigned it - and assigning to a name anywhere inside a function makes Python treat it as local for the whole function.\n\n## What it looks like when it goes wrong\n\n```\nNameError: name \'x\' is not defined\nUnboundLocalError: cannot access local variable \'x\' where it is not associated with a value\n```\n\n## How to spot it\n\nCompare the name letter-by-letter against where it\'s created, and check whether it\'s assigned anywhere else in the same function.\n\n## How to fix it\n\nFix the typo, or add `global name` if the function genuinely needs to update a module-level variable.\n\n## Try it\n\n```python run\ncount = 0\n\ndef increment():\n    global count\n    count += 1\n    return count\n\nprint(increment())\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (88, 'types-and-conversion', 'Types and conversion', 'Values have types, and some operations need matching types.', '## What it is\n\nEvery value has a type (`str`, `int`, `float`...). Some operators behave differently - or refuse to work at all - depending on the types involved.\n\n## What it looks like when it goes wrong\n\n```\nTypeError: can only concatenate str (not \"int\") to str\nValueError: invalid literal for int() with base 10: \'3.5\'\n```\n\n## How to spot it\n\nCheck the types of the values either side of an operator, especially `+`.\n\n## How to fix it\n\nConvert explicitly with `str()`, `int()`, or `float()` as needed.\n\n## Try it\n\n```python run\nage = 17\nprint(\"Age: \" + str(age))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (89, 'indexing', 'Indexing', 'A list of length n has valid indexes 0 through n - 1.', '## What it is\n\nList and string positions are counted from `0`. The last valid index is `len(x) - 1`.\n\n## What it looks like when it goes wrong\n\n```\nIndexError: list index out of range\n```\n\n## How to spot it\n\nCheck the index against the list\'s actual length, especially at the start and end.\n\n## How to fix it\n\nUse `len(x) - 1` for the last item, and guard against empty sequences.\n\n## Try it\n\n```python run\nitems = [10, 20, 30]\nprint(items[len(items) - 1])\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (90, 'dictionaries', 'Dictionaries', 'dict[key] crashes if the key is missing; .get() does not.', '## What it is\n\nA dictionary looks up values by key. `d[key]` crashes if the key isn\'t present; `d.get(key, default)` doesn\'t.\n\n## What it looks like when it goes wrong\n\n```\nKeyError: \'colour\'\n```\n\n## How to spot it\n\nCheck whether the key being looked up is guaranteed to exist.\n\n## How to fix it\n\nUse `.get(key, default)` when the key might be missing.\n\n## Try it\n\n```python run\ncolours = {\"apple\": \"red\"}\nprint(colours.get(\"banana\", \"unknown\"))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (91, 'zero-division-and-guards', 'Dividing by zero (and guarding against it)', 'Check a count isn\'t zero before you divide by it.', '## What it is\n\nDividing (or using `%`) by zero always crashes in Python.\n\n## What it looks like when it goes wrong\n\n```\nZeroDivisionError: division by zero\n```\n\n## How to spot it\n\nLook at what\'s on the right of `/` or `%` - could it ever be zero? An empty list\'s length is the classic case.\n\n## How to fix it\n\nAdd a guard: check the value before dividing.\n\n## Try it\n\n```python run\nscores = []\nif len(scores) == 0:\n    print(\"No scores yet\")\nelse:\n    print(sum(scores) / len(scores))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (92, 'input-validation', 'Validating input', 'Text from input() or elsewhere might not be in the shape you expect.', '## What it is\n\nAny value that comes from outside your code - `input()`, a file, a user - might not be in the format your code assumes.\n\n## What it looks like when it goes wrong\n\n```\nValueError: invalid literal for int() with base 10: \'abc\'\n```\n\n## How to spot it\n\nAsk: what happens if this value isn\'t what I expect?\n\n## How to fix it\n\nConvert carefully (e.g. via `float()` before `int()`), and consider checking the value before using it.\n\n## Try it\n\n```python run\ntext = \"42\"\nprint(int(text) * 2)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (93, 'return-values', 'Return values', 'A function without a return gives back None.', '## What it is\n\nA function only gives back a value if it hits a `return` statement. Otherwise it implicitly returns `None`.\n\n## What it looks like when it goes wrong\n\nNo error - just `None` where you expected a real value, or a crash later when something tries to use that `None`.\n\n## How to spot it\n\nIf a function\'s result always seems to be `None`, check every path through it for a `return`.\n\n## How to fix it\n\nAdd the missing `return`.\n\n## Try it\n\n```python run\ndef add(a, b):\n    return a + b\n\nprint(add(2, 3))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (94, 'function-calls', 'Function calls and arguments', 'A call must supply exactly the arguments the definition expects.', '## What it is\n\nA function\'s parameter list is a contract - every call must match it (unless defaults are used).\n\n## What it looks like when it goes wrong\n\n```\nTypeError: greet() missing 1 required positional argument: \'last_name\'\n```\n\n## How to spot it\n\nCompare the `def` line to every place the function is called or tested.\n\n## How to fix it\n\nAdd or remove parameters so the definition matches how it\'s actually used.\n\n## Try it\n\n```python run\ndef greet(first_name, last_name):\n    return \"Hello, \" + first_name + \" \" + last_name\n\nprint(greet(\"Ada\", \"Lovelace\"))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (95, 'off-by-one', 'Off-by-one errors', 'Loops and ranges that stop one step too early or too late.', '## What it is\n\nA loop, range or boundary check that\'s out by exactly one - the most common logic bug in programming.\n\n## What it looks like when it goes wrong\n\nNo error at all - just a result that\'s slightly wrong, often missing the first or last item.\n\n## How to spot it\n\nTest with the smallest possible input by hand and check the first and last values a loop actually touches.\n\n## How to fix it\n\nAdjust the range, comparison operator, or starting value so the boundary is handled correctly.\n\n## Try it\n\n```python run\nfor i in range(1, 5):\n    print(i)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (96, 'range-function', 'How range() works', 'range(a, b) includes a but stops before b.', '## What it is\n\n`range(a, b)` produces `a, a+1, ..., b-1` - it always stops one short of `b`.\n\n## What it looks like when it goes wrong\n\nA loop that should include the last number doesn\'t.\n\n## How to spot it\n\nPrint `list(range(a, b))` for small numbers and check what\'s actually in it.\n\n## How to fix it\n\nUse `range(a, b + 1)` when you need `b` included.\n\n## Try it\n\n```python run\nprint(list(range(1, 5)))\nprint(list(range(1, 6)))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (97, 'integer-vs-float-division', 'Integer vs float division', '/ gives the exact result; // rounds down and discards the remainder.', '## What it is\n\n`/` always gives the exact, possibly-fractional result. `//` rounds down to a whole number.\n\n## What it looks like when it goes wrong\n\nNo error - just a result missing its fractional part.\n\n## How to spot it\n\nTest with numbers that don\'t divide evenly.\n\n## How to fix it\n\nUse `/` when you need the exact value, `//` only when you deliberately want to discard the remainder.\n\n## Try it\n\n```python run\nprint(7 / 2)\nprint(7 // 2)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (98, 'operator-precedence', 'Operator precedence', 'Multiplication and division happen before addition and subtraction.', '## What it is\n\nPython follows the normal maths order of operations unless brackets say otherwise.\n\n## What it looks like when it goes wrong\n\nNo error - just a calculation that doesn\'t match what you meant.\n\n## How to spot it\n\nWork through the calculation by hand, following the actual order Python would use.\n\n## How to fix it\n\nAdd brackets to make the intended order explicit.\n\n## Try it\n\n```python run\na, b = 4, 6\nprint((a + b) / 2)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (99, 'boolean-logic', 'and, or, and boolean logic', 'and needs both sides true; or needs just one.', '## What it is\n\n`and` is true only if both sides are true. `or` is true if either side is true.\n\n## What it looks like when it goes wrong\n\nA validator accepts things it shouldn\'t (or rejects things it shouldn\'t).\n\n## How to spot it\n\nCheck every `or` in a validator - would `and` be more correct?\n\n## How to fix it\n\nSwap `or` for `and` (or vice versa) to match the intended rule.\n\n## Try it\n\n```python run\nname = \"ada\"\nprint(3 <= len(name) <= 20)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (100, 'loops-and-return', 'Loops and return', 'return exits the function immediately, from wherever it is.', '## What it is\n\n`return` ends the function right away. Placed inside a loop by mistake, it can end a search after just one item.\n\n## What it looks like when it goes wrong\n\nA search stops too early, missing items later in the loop.\n\n## How to spot it\n\nCheck a `return`\'s indentation - is it inside the loop, or after it?\n\n## How to fix it\n\nMove the `return` to the correct indentation level.\n\n## Try it\n\n```python run\ndef find_first_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n    return None\n\nprint(find_first_even([1, 3, 4, 5]))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (101, 'accumulators', 'Accumulators', 'An accumulator needs resetting at the start of each new thing it sums.', '## What it is\n\nAn accumulator variable builds up a running total. It needs to start fresh whenever a new total should begin.\n\n## What it looks like when it goes wrong\n\nTotals creep upward, adding onto the previous one instead of starting over.\n\n## How to spot it\n\nCheck where the accumulator is reset to its starting value - outside the loop, or inside it?\n\n## How to fix it\n\nMove the reset inside the loop that should restart it each time.\n\n## Try it\n\n```python run\nfor lst in [[1, 2], [3, 4]]:\n    total = 0\n    for n in lst:\n        total += n\n    print(total)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (102, 'loop-termination', 'Loop termination', 'Every while loop needs something that moves its condition towards false.', '## What it is\n\nA `while` loop keeps running until its condition becomes false - something inside it must actually change that condition.\n\n## What it looks like when it goes wrong\n\nThe run is stopped for taking too long - a classic infinite loop.\n\n## How to spot it\n\nFind the line that updates the condition\'s variable. If there isn\'t one, that\'s the bug.\n\n## How to fix it\n\nAdd the missing update (like `n -= 1`).\n\n## Try it\n\n```python run\nn = 3\nwhile n > 0:\n    print(n)\n    n -= 1\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (103, 'shadowing-builtins', 'Shadowing built-ins', 'Naming a variable sum or list hides the built-in function of the same name.', '## What it is\n\nPython lets you name a variable the same as a built-in function, but doing so hides the built-in for the rest of that scope.\n\n## What it looks like when it goes wrong\n\n```\nTypeError: \'int\' object is not callable\n```\n\n## How to spot it\n\nIf a `TypeError` says something isn\'t callable, check if a variable has shadowed a built-in name.\n\n## How to fix it\n\nRename the variable to something that isn\'t a built-in function name.\n\n## Try it\n\n```python run\nnumbers = [1, 2, 3]\nprint(sum(numbers))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (104, 'mutating-while-iterating', 'Mutating while iterating', 'Changing a list or dict while looping over it can skip items or crash.', '## What it is\n\nAdding or removing items from a collection while iterating over it directly can cause skipped items (lists) or a crash (dicts).\n\n## What it looks like when it goes wrong\n\n```\nRuntimeError: dictionary changed size during iteration\n```\n\nOr, for lists: items are silently skipped with no error at all.\n\n## How to spot it\n\nCheck whether the loop you\'re modifying is the same collection you\'re looping over.\n\n## How to fix it\n\nBuild a new collection (e.g. with a list comprehension) or loop over a copy (`list(d.keys())`).\n\n## Try it\n\n```python run\nnums = [1, -2, -3, 4]\nprint([n for n in nums if n >= 0])\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (105, 'string-methods', 'String methods and case', 'Character comparisons are case-sensitive.', '## What it is\n\n`\'A\' == \'a\'` is `False` - comparisons are case-sensitive unless you normalise case yourself.\n\n## What it looks like when it goes wrong\n\nNo error - just uppercase (or lowercase) input silently not matching.\n\n## How to spot it\n\nTest with a mix of uppercase and lowercase input.\n\n## How to fix it\n\nUse `.lower()` or `.upper()` on both sides before comparing.\n\n## Try it\n\n```python run\nprint(\"A\".lower() in \"aeiou\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (106, 'mutable-defaults', 'Mutable default arguments', 'A default list or dict is created once, not fresh on every call.', '## What it is\n\nA default argument value is evaluated exactly once, when `def` runs - not fresh on every call.\n\n## What it looks like when it goes wrong\n\nA list (or dict) \"remembers\" items from previous calls that didn\'t supply their own.\n\n## How to spot it\n\nCheck any default value that\'s a list, dict, or other mutable object.\n\n## How to fix it\n\nDefault to `None`, and create the real empty value inside the function body.\n\n## Try it\n\n```python run\ndef add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nprint(add_item(\"apple\"))\nprint(add_item(\"banana\"))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (107, 'aliasing-and-copying', 'Aliasing and copying', 'Assigning a list to a new name does not copy it.', '## What it is\n\n`b = a` makes `b` another name for the exact same list object - not a copy.\n\n## What it looks like when it goes wrong\n\nChanging one variable unexpectedly changes another.\n\n## How to spot it\n\nAsk: do I need a genuinely separate list, or just another name for the same one?\n\n## How to fix it\n\nUse `.copy()`, `list(...)`, or a comprehension to create an independent list.\n\n## Try it\n\n```python run\noriginal = [1, 2, 3]\ncopy = original.copy()\ncopy[0] = 99\nprint(original)\nprint(copy)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (108, 'recursion', 'Recursion and base cases', 'Every recursive function needs a condition where it stops calling itself.', '## What it is\n\nA recursive function calls itself with a smaller version of the problem, until a base case stops the chain.\n\n## What it looks like when it goes wrong\n\n```\nRecursionError: maximum recursion depth exceeded\n```\n\n## How to spot it\n\nCheck for a condition that returns without calling itself again.\n\n## How to fix it\n\nAdd the missing base case.\n\n## Try it\n\n```python run\ndef count_down(n):\n    if n <= 0:\n        print(\"Done!\")\n        return\n    print(n)\n    count_down(n - 1)\n\ncount_down(3)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (109, 'binary-search', 'Binary search bounds', 'The search range must shrink every pass, or it can loop forever.', '## What it is\n\nBinary search repeatedly halves a sorted range until it finds the target or the range is empty.\n\n## What it looks like when it goes wrong\n\nThe search never finishes when the target isn\'t present - the range stops shrinking.\n\n## How to spot it\n\nTrace through a search for a missing value by hand, checking the bounds actually move each pass.\n\n## How to fix it\n\nMove bounds past `mid` (`mid + 1` / `mid - 1`), not onto it.\n\n## Try it\n\n```python run\ndef binary_search(items, target):\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nprint(binary_search([1, 3, 5, 7], 5))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (110, 'closures', 'Closures and late binding', 'A lambda looks up a loop variable when called, not when created.', '## What it is\n\nFunctions created inside a loop share the same loop variable - they don\'t each get a frozen copy of its value at creation time.\n\n## What it looks like when it goes wrong\n\nEvery function created in the loop seems to return the same (final) value.\n\n## How to spot it\n\nCheck whether a value used inside a lambda or nested function comes from an enclosing loop variable.\n\n## How to fix it\n\nCapture the current value with a default argument: `lambda x=x: ...`.\n\n## Try it\n\n```python run\nmakers = [lambda i=i: i for i in range(3)]\nprint([m() for m in makers])\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (111, 'iterators-and-generators', 'Iterators and generators', 'A generator can only be stepped through once.', '## What it is\n\nA generator expression produces values lazily and doesn\'t remember them - once consumed, it\'s exhausted.\n\n## What it looks like when it goes wrong\n\nListing the same generator a second time gives an empty result.\n\n## How to spot it\n\nCheck whether something that needs reading more than once is a generator or a list.\n\n## How to fix it\n\nUse a list comprehension `[...]` instead of a generator expression `(...)` if you need to iterate more than once.\n\n## Try it\n\n```python run\nevens = [n for n in range(10) if n % 2 == 0]\nprint(list(evens))\nprint(list(evens))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (112, 'floating-point', 'Floating-point precision', 'Most decimal fractions cannot be represented exactly in binary.', '## What it is\n\n`float` values are stored in binary, and most decimal fractions (like 0.1) can\'t be represented exactly - leading to tiny rounding errors.\n\n## What it looks like when it goes wrong\n\n`0.1 + 0.2 == 0.3` is `False` - an exact-equality check between floats silently fails.\n\n## How to spot it\n\nAny `==` comparison between floats is suspect.\n\n## How to fix it\n\nUse `math.isclose(a, b)` instead of `==`.\n\n## Try it\n\n```python run\nimport math\nprint(0.1 + 0.2 == 0.3)\nprint(math.isclose(0.1 + 0.2, 0.3))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (113, 'sorting', 'Sorting', 'sorted() defaults to ascending order.', '## What it is\n\n`sorted()` arranges items smallest-to-largest by default, using `key` to decide what to compare.\n\n## What it looks like when it goes wrong\n\nTaking the \"top\" items after sorting actually gives the lowest ones.\n\n## How to spot it\n\nCheck whether `reverse=True` is needed for what you actually want.\n\n## How to fix it\n\nAdd `reverse=True` for descending order.\n\n## Try it\n\n```python run\nscores = [10, 30, 20]\nprint(sorted(scores, reverse=True))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (114, 'exception-handling', 'Exception handling', 'A bare except: hides every error, including genuine bugs.', '## What it is\n\n`try`/`except` lets you handle specific, expected errors gracefully - but a bare `except:` catches everything, including mistakes you never intended to handle.\n\n## What it looks like when it goes wrong\n\nA function silently returns the wrong thing (often `None`) instead of crashing where the real mistake is.\n\n## How to spot it\n\nLook for bare `except:` clauses, especially around code that otherwise looks correct.\n\n## How to fix it\n\nCatch only the specific exception types you expect.\n\n## Try it\n\n```python run\ntry:\n    result = 10 / 0\nexcept ZeroDivisionError:\n    print(\"Can\'t divide by zero\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (115, 'identity-vs-equality', 'is vs ==', '== compares values; is compares identity (the exact same object).', '## What it is\n\n`==` asks \"do these have the same value?\". `is` asks \"are these the exact same object in memory?\".\n\n## What it looks like when it goes wrong\n\nTwo lists (or other objects) with identical contents compare as not equal when checked with `is`.\n\n## How to spot it\n\nCheck whether `is` is being used where a value comparison (`==`) was actually meant.\n\n## How to fix it\n\nUse `==` for value comparisons; reserve `is` for `None` checks or genuine identity checks.\n\n## Try it\n\n```python run\na = [1, 2, 3]\nb = [1, 2, 3]\nprint(a == b)\nprint(a is b)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (116, 'reading-tracebacks', 'Reading tracebacks', 'Start at the last line and work up - that names the error and shows where it happened.', '## What it is\n\nA traceback is Python\'s full error report: the exception type and message at the bottom, and the chain of calls that led there above it, in the order Python followed them.\n\n## What it looks like when it goes wrong\n\n```\nTraceback (most recent call last):\n  File \"<student>\", line 2, in <module>\n    print(divide(10, 0))\n  File \"<student>\", line 1, in divide\n    return a / b\nZeroDivisionError: division by zero\n```\n\n## How to spot it\n\nStart at the very last line - that names the exception and the message. Then look at the line just above it, which shows where in your code it actually happened. Lines further up show how execution got there (useful for recursion or nested calls), but the bottom two lines are where to look first.\n\n## How to fix it\n\nUse the exception type and message to work out what went wrong, then fix the line the traceback points to - not just the first line of the program.\n\n## Try it\n\n```python run\ndef divide(a, b):\n    return a / b\n\nprint(divide(10, 0))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (117, 'fstring-syntax', 'f-string syntax', 'An f-string embeds values with {expression} - the braces need to match, and the quotes still need to match too.', '## What it is\n\nAn f-string (`f\"...\"`) lets you embed a value directly inside text using curly braces: `f\"Hello, {name}\"`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: f-string: expecting \'}\'\n```\n\n## How to spot it\n\nCheck two things separately: do the outer quote marks match, and does every `{` inside have its own `}`?\n\n## How to fix it\n\nAdd the missing brace or quote mark.\n\n## Try it\n\n```python run\nname = \"Ada\"\nprint(f\"Hello, {name}\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (118, 'dict-literal-syntax', 'Dictionary literal syntax', 'A dictionary pairs key and value with a colon, {key: value}, not an equals sign.', '## What it is\n\nA dictionary literal lists `key: value` pairs inside `{}`, separated by commas.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nLook for an `=` where a `:` should be inside a `{}` literal.\n\n## How to fix it\n\nChange each `=` to `:`.\n\n## Try it\n\n```python run\nprices = {\"apple\": 1, \"pear\": 2}\nprint(prices[\"apple\"])\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (119, 'for-loop-syntax', 'for loop syntax', 'A for loop always reads \"for item in iterable:\" - every word is required.', '## What it is\n\nA `for` loop has one fixed shape: `for`, a name for the current item, `in`, the thing being looped over, then a colon.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nRead the `for` line out loud as \"for ... in ...:\" and check every word is actually there.\n\n## How to fix it\n\nAdd whichever piece is missing - usually the `in`.\n\n## Try it\n\n```python run\nfor i in range(3):\n    print(i)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (120, 'except-syntax', 'except syntax', 'Name a caught exception with `except Error as name:`, not a comma.', '## What it is\n\nTo catch an exception and give it a name, Python 3 uses `except SomeError as name:`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nLook for a comma inside an `except` line where `as` should be - that\'s old Python 2 syntax.\n\n## How to fix it\n\nChange the comma to `as`.\n\n## Try it\n\n```python run\ntry:\n    int(\"abc\")\nexcept ValueError as e:\n    print(\"That wasn\'t a number\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (121, 'identifier-rules', 'Valid variable names', 'A name can use letters, digits and underscores, but cannot start with a digit or contain a hyphen.', '## What it is\n\nA Python name (variable, function, etc.) must start with a letter or underscore, and can only contain letters, digits and underscores after that.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid decimal literal\nSyntaxError: cannot assign to expression here\n```\n\n## How to spot it\n\nCheck the name for a leading digit or a hyphen - both are invalid.\n\n## How to fix it\n\nUse an underscore instead of a hyphen, and start the name with a letter, spelling out any leading number in words if needed.\n\n## Try it\n\n```python run\nsecond_place = \"Silver\"\nprint(second_place)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (122, 'control-flow-context', 'return and break need the right context', '`return` only works inside a function; `break` and `continue` only work inside a loop.', '## What it is\n\n`return` sends a value back from a function call, so it only makes sense while Python is inside a function. `break`/`continue` only make sense inside a loop, for the same reason.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: \'return\' outside function\nSyntaxError: \'break\' outside loop\n```\n\n## How to spot it\n\nCheck the indentation of the `return`/`break`/`continue` line - is it actually inside the `def`/`for`/`while` block it\'s meant to belong to?\n\n## How to fix it\n\nIndent it so it sits inside the right block, or remove it if it was left over by mistake.\n\n## Try it\n\n```python run\ndef greet(name):\n    print(\"Hello, \" + name)\n    return \"done\"\n\ngreet(\"Ada\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (123, 'global-statement', 'The global statement', '`global name` only declares which variable you mean - the assignment itself needs its own line.', '## What it is\n\nInside a function, `global name` tells Python that `name` refers to the module-level variable, not a new local one. It is purely a declaration.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nLook for `=` on the same line as `global` - that\'s not allowed.\n\n## How to fix it\n\nSplit it into two lines: the `global` declaration, then the assignment.\n\n## Try it\n\n```python run\ncounter = 0\n\ndef increment():\n    global counter\n    counter = counter + 1\n\nincrement()\nprint(counter)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (124, 'old-style-print', 'print is a function', 'print(...) needs parentheses - print \"text\" is an old Python 2 statement form.', '## What it is\n\nIn current Python, `print` is an ordinary function, so calling it needs parentheses: `print(\"text\")`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: Missing parentheses in call to \'print\'. Did you mean print(...)?\n```\n\n## How to spot it\n\nLook for `print` directly followed by text with no parentheses - a sign of an old Python 2 example.\n\n## How to fix it\n\nWrap the text in parentheses.\n\n## Try it\n\n```python run\nprint(\"Game over\")\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (125, 'lambda-syntax', 'lambda syntax', 'A lambda reads as \"lambda parameters: expression\" - the colon is required.', '## What it is\n\nA `lambda` is a small, unnamed function written on one line: `lambda parameters: expression`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nCheck for a missing colon between the parameters and the expression.\n\n## How to fix it\n\nAdd the colon.\n\n## Try it\n\n```python run\nsquare = lambda x: x * x\nprint(square(4))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (126, 'line-continuation', 'Splitting an expression across lines', 'An expression that spans multiple lines needs brackets (preferred) or a trailing backslash.', '## What it is\n\nPython normally ends a statement at the end of a line. To let one expression span several lines, wrap it in brackets - or end each line with a backslash `\\` if you really can\'t use brackets.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nLook for a line that ends mid-expression (e.g. with a trailing `+`) with nothing telling Python to keep reading.\n\n## How to fix it\n\nWrap the whole expression in parentheses.\n\n## Try it\n\n```python run\ntotal = (1 + 2 +\n         3 + 4)\nprint(total)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (127, 'absolute-value', 'Absolute value', 'abs() strips the sign off a number, giving its distance from zero regardless of direction.', '## What it is\n\n`abs(x)` returns the magnitude of `x` - its distance from zero, always positive (or zero).\n\n## What it looks like when it goes wrong\n\nA \"difference\" or \"distance\" calculation returns a negative number whenever the arguments are given in one particular order.\n\n## How to spot it\n\nCall the function both ways round (`f(a, b)` and `f(b, a)`) - if the sign flips but the brief says it shouldn\'t, this is the bug.\n\n## How to fix it\n\nWrap the subtraction in `abs(...)`.\n\n## Try it\n\n```python run\nprint(abs(5 - 10))\nprint(abs(10 - 5))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (128, 'any-vs-all', 'Any pass vs all pass', '\"at least one\" (any) and \"every single one\" (all) need opposite loop logic.', '## What it is\n\nChecking whether *any* item in a collection matches a condition is a different question from checking whether *all* of them do - and the loop shape for each is a mirror image of the other.\n\n## What it looks like when it goes wrong\n\nA function meant to check \"do all of these pass?\" returns `True` as soon as it finds a single passing item, ignoring the rest.\n\n## How to spot it\n\nTest with a collection where most items pass but one clearly fails - a correct \"all\" check should notice the failure.\n\n## How to fix it\n\nTo check *all*: look for a single failure and return `False` immediately; only return `True` after the whole loop finishes. To check *any*: look for a single success and return `True` immediately; only return `False` after the whole loop finishes.\n\n## Try it\n\n```python run\ndef all_positive(numbers):\n    for n in numbers:\n        if n <= 0:\n            return False\n    return True\n\nprint(all_positive([1, 2, 3]))\nprint(all_positive([1, -2, 3]))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (129, 'conditional-branches', 'Matching conditions to the right branch', 'A condition can be correct while the values returned from its branches are accidentally swapped.', '## What it is\n\nAn `if`/`else` has two parts that both have to be right together: the condition, and which value each branch returns.\n\n## What it looks like when it goes wrong\n\nThe code runs with no error, but consistently returns the opposite of the expected answer.\n\n## How to spot it\n\nTest a clearly one-sided case (obviously \"hot\", obviously a \"win\", and so on) and check the result against what you expected, not just that *a* result came back.\n\n## How to fix it\n\nSwap the values (or the comparison) back so the condition and its result actually agree.\n\n## Try it\n\n```python run\ndef classify(n):\n    if n > 0:\n        return \"positive\"\n    else:\n        return \"non-positive\"\n\nprint(classify(5))\nprint(classify(-5))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (130, 'rounding', 'Rounding vs truncating', 'int() always truncates towards zero; round() finds the nearest whole number.', '## What it is\n\n`int(x)` removes everything after the decimal point, always moving towards zero. `round(x)` finds the nearest whole number instead.\n\n## What it looks like when it goes wrong\n\nA value that should round up (like 1.9 or 2.5) instead comes out rounded down.\n\n## How to spot it\n\nTest a value very close to the next whole number (like `1.99`) - truncating and rounding only disagree near the boundary.\n\n## How to fix it\n\nUse `round()` instead of `int()` when you want the nearest whole number, not just the integer part.\n\n## Try it\n\n```python run\nprint(int(1.99))\nprint(round(1.99))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (131, 'division-direction', 'Which number goes on top', 'Division is not symmetric - a/b and b/a give different answers, so ratios need the right number as the numerator.', '## What it is\n\nUnlike addition or multiplication, division cares about order: `a / b` and `b / a` are generally different values.\n\n## What it looks like when it goes wrong\n\nA percentage or ratio comes out wildly wrong - often much bigger than 100%, or inverted.\n\n## How to spot it\n\nSay the formula out loud in plain English first (\"correct answers over total questions\") and check the code\'s numerator and denominator match that.\n\n## How to fix it\n\nSwap the numerator and denominator.\n\n## Try it\n\n```python run\ncorrect = 1\ntotal = 4\nprint(correct / total * 100)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (132, 'methods-that-return-none', 'Methods that return None', 'In-place list methods like .sort(), .append() and .reverse() return None - never reassign their result.', '## What it is\n\n`.sort()`, `.append()`, `.reverse()`, `.extend()`, `.insert()` and `.remove()` all change a list in place and give back `None` - the change *is* the result, there\'s nothing new to hand back.\n\n## What it looks like when it goes wrong\n\nA variable that should be a list turns out to be `None` after calling one of these methods.\n\n## How to spot it\n\nCheck for a pattern like `x = x.append(...)` or `x = x.sort()` - reassigning the result of an in-place method.\n\n## How to fix it\n\nCall the method on its own line, without reassigning it, then use the original variable afterwards.\n\n## Try it\n\n```python run\nnumbers = [3, 1, 2]\nnumbers.sort()\nprint(numbers)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (133, 'zip-and-enumerate', 'zip() and enumerate()', 'zip() stops at the shortest list; enumerate() counts from 0 unless told otherwise.', '## What it is\n\n`zip(a, b)` pairs up items from two sequences; `enumerate(items)` pairs each item with its position, counting from `0` by default.\n\n## What it looks like when it goes wrong\n\n`zip()` silently drops extra items from the longer list; `enumerate()` labels the first item `0` instead of `1`.\n\n## How to spot it\n\nTest with lists of different lengths (for `zip`), or check the very first number in the output (for `enumerate`).\n\n## How to fix it\n\nUse `itertools.zip_longest()` if the lists might differ in length; pass `start=1` to `enumerate()` for human-friendly numbering.\n\n## Try it\n\n```python run\nfor i, item in enumerate([\"a\", \"b\"], start=1):\n    print(i, item)\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (134, 'bool-is-int', 'True and False are numbers too', 'bool is a subtype of int in Python - True equals 1 and hashes the same way.', '## What it is\n\nPython\'s `bool` type is a subclass of `int` - `True` is `1` and `False` is `0` for every purpose: equality, hashing, and arithmetic.\n\n## What it looks like when it goes wrong\n\nA `set` or `dict` that is supposed to tell `True` and `1` apart silently merges them into one entry.\n\n## How to spot it\n\nTest with a collection containing both `1` and `True` (or `0` and `False`) together.\n\n## How to fix it\n\nTrack the type alongside the value, e.g. with `(type(x), x)` pairs, if telling them apart matters.\n\n## Try it\n\n```python run\nprint(True == 1)\nprint({1, True})\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (135, 'key-functions', 'key= for sorted(), min() and max()', 'Without a key function, sorting and min/max compare values directly - which is not always what you want.', '## What it is\n\n`sorted()`, `min()` and `max()` all accept a `key` argument: a function that extracts the thing to actually compare, instead of comparing the raw values.\n\n## What it looks like when it goes wrong\n\nSorting text puts capitals in a strange order; finding the \"shortest\" or \"highest-scoring\" item compares the wrong property entirely.\n\n## How to spot it\n\nCheck whether the comparison you actually want (by length, by a specific field, ignoring case) is the same as comparing the raw values directly.\n\n## How to fix it\n\nAdd `key=...` - e.g. `key=len`, `key=str.lower`, or `key=lambda x: x[1]`.\n\n## Try it\n\n```python run\nwords = [\"Banana\", \"apple\", \"Cherry\"]\nprint(sorted(words, key=str.lower))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (136, 'loop-variable-scope', 'Variables assigned inside a loop or if', 'A variable only exists once it has actually been assigned - a conditional assignment might never run.', '## What it is\n\nA variable assigned inside a loop or `if` block is not limited to that block - but it only exists from the moment that assignment actually runs.\n\n## What it looks like when it goes wrong\n\nA variable meant to hold a fallback/default value is used after a loop, but was never actually given that fallback before the loop started.\n\n## How to spot it\n\nTest the case where the loop\'s condition never triggers the assignment at all (an empty list, or no matching item).\n\n## How to fix it\n\nInitialise the variable with its fallback value before the loop begins.\n\n## Try it\n\n```python run\ndef last_even(numbers, default):\n    result = default\n    for n in numbers:\n        if n % 2 == 0:\n            result = n\n    return result\n\nprint(last_even([1, 3, 5], -1))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (137, 'none-vs-falsy', '\"No value\" vs \"a falsy value\"', 'None, 0, \"\" and [] are all falsy, but only None actually means \"nothing here\".', '## What it is\n\n`if not x:` treats `None`, `0`, `0.0`, `\"\"` and `[]` all the same way (all \"falsy\") - but they don\'t all mean the same thing.\n\n## What it looks like when it goes wrong\n\nA genuinely valid value of `0` (or an empty string) gets treated as if it were missing entirely.\n\n## How to spot it\n\nTest with the real value `0` (or `\"\"`) specifically, not just `None`.\n\n## How to fix it\n\nCheck `x is None` when you specifically mean \"no value was given\", rather than the general `if not x:`.\n\n## Try it\n\n```python run\ndef describe(score):\n    if score is None:\n        return \"no score\"\n    return f\"scored {score}\"\n\nprint(describe(0))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_concepts` VALUES (138, 'wrong-operator', 'The wrong arithmetic operator', 'Using `+` where a formula needs `*` (or vice versa) still runs and still gives a number - just the wrong one.', '## What it is\n\nA formula built from more than one arithmetic operator (`+`, `-`, `*`, `/`) can have the right variables in the right places, but the wrong operator joining them.\n\n## What it looks like when it goes wrong\n\nThe code runs without any error and returns a plausible-looking number - it is only wrong once you check it against the actual maths.\n\n## How to spot it\n\nWork the formula out by hand for one simple example, and compare that to what the code actually computes.\n\n## How to fix it\n\nCompare each operator in the code against the real-world formula it is meant to implement, one at a time.\n\n## Try it\n\n```python run\ndef rectangle_area(width, height):\n    return width + height\n\nprint(rectangle_area(4, 5))\n```', '2026-11-22 20:26:13');
INSERT INTO `bh_hints` VALUES (331, 111, 1, 'This code won\'t even run yet - look at the error message before you think about logic at all.');
INSERT INTO `bh_hints` VALUES (332, 111, 2, 'Look closely at the `def` line. Every line that opens a block needs something specific at the end.');
INSERT INTO `bh_hints` VALUES (333, 111, 3, 'Add a colon `:` at the end of the `def is_even(n)` line.');
INSERT INTO `bh_hints` VALUES (334, 112, 1, 'This won\'t run at all - read the error message, it tells you exactly what Python was still waiting for.');
INSERT INTO `bh_hints` VALUES (335, 112, 2, 'Count the opening and closing parentheses on the `print` line.');
INSERT INTO `bh_hints` VALUES (336, 112, 3, 'Add the missing `)` at the end of the `print(...)` line.');
INSERT INTO `bh_hints` VALUES (337, 113, 1, 'Read the error carefully - it names the exact kind of punctuation problem this is.');
INSERT INTO `bh_hints` VALUES (338, 113, 2, 'Look at the quote marks around the text. Do they come in a matching pair?');
INSERT INTO `bh_hints` VALUES (339, 113, 3, 'Add the missing closing `\"` right after \"Level complete!\".');
INSERT INTO `bh_hints` VALUES (340, 114, 1, 'This is an `IndentationError` - Python expected something it didn\'t find. Read exactly what it says.');
INSERT INTO `bh_hints` VALUES (341, 114, 2, 'Compare the `return` line to the `def` line above it. Where does Python expect the body of a function to sit?');
INSERT INTO `bh_hints` VALUES (342, 114, 3, 'Indent the `return` line by 4 spaces so it sits inside the function.');
INSERT INTO `bh_hints` VALUES (343, 115, 1, 'Read the error type carefully - it names a specific mix-up in how the whitespace is written, not just \"wrong amount\".');
INSERT INTO `bh_hints` VALUES (344, 115, 2, 'Line 3 is indented differently to its neighbours, even though it looks about right on screen.');
INSERT INTO `bh_hints` VALUES (345, 115, 3, 'Replace the tab character at the start of line 3 with spaces, matching the rest of the file.');
INSERT INTO `bh_hints` VALUES (346, 116, 1, 'This crashes with a `NameError` - Python has no idea what this name refers to.');
INSERT INTO `bh_hints` VALUES (347, 116, 2, 'There\'s a built-in function that does exactly this. Check its spelling very carefully, letter by letter.');
INSERT INTO `bh_hints` VALUES (348, 116, 3, 'Change `Print` to `print` (lowercase).');
INSERT INTO `bh_hints` VALUES (349, 117, 1, 'This is a syntax error about assignment - something is being used in a place Python only allows a comparison.');
INSERT INTO `bh_hints` VALUES (350, 117, 2, 'Look inside the `if` condition. There are two different symbols that both involve equals signs - which one compares values?');
INSERT INTO `bh_hints` VALUES (351, 117, 3, 'Change `=` to `==` inside the `if` condition.');
INSERT INTO `bh_hints` VALUES (352, 118, 1, 'This won\'t run - Python doesn\'t recognise one of the keywords used here.');
INSERT INTO `bh_hints` VALUES (353, 118, 2, 'Python\'s \"else if\" keyword is a single word, and it isn\'t spelled the way some other languages spell it.');
INSERT INTO `bh_hints` VALUES (354, 118, 3, 'Change `elseif` to `elif`.');
INSERT INTO `bh_hints` VALUES (355, 119, 1, 'This crashes with a `TypeError` about something not being subscriptable - a clue about which bracket is wrong.');
INSERT INTO `bh_hints` VALUES (356, 119, 2, 'Calling a method (like `.upper`) and indexing into something use different brackets. Which one is this?');
INSERT INTO `bh_hints` VALUES (357, 119, 3, 'Change `word.upper[]` to `word.upper()`.');
INSERT INTO `bh_hints` VALUES (358, 120, 1, 'This is a syntax error on the `def` line itself.');
INSERT INTO `bh_hints` VALUES (359, 120, 2, 'Every function definition needs its parameters wrapped in a specific kind of bracket.');
INSERT INTO `bh_hints` VALUES (360, 120, 3, 'Wrap `n` in parentheses: `def square(n):`.');
INSERT INTO `bh_hints` VALUES (361, 121, 1, 'This won\'t run at all - read exactly what Python says it expected.');
INSERT INTO `bh_hints` VALUES (362, 121, 2, 'Every block header - including `if` - needs the same piece of punctuation at the end.');
INSERT INTO `bh_hints` VALUES (363, 121, 3, 'Add a colon `:` after `if age >= 18`.');
INSERT INTO `bh_hints` VALUES (364, 122, 1, 'This won\'t run - Python tells you exactly which piece of punctuation it was still waiting for.');
INSERT INTO `bh_hints` VALUES (365, 122, 2, 'The `for` line is missing the same thing every block header needs.');
INSERT INTO `bh_hints` VALUES (366, 122, 3, 'Add a colon `:` after `range(5)`.');
INSERT INTO `bh_hints` VALUES (367, 123, 1, 'This won\'t run - the error names a specific piece of punctuation Python expected.');
INSERT INTO `bh_hints` VALUES (368, 123, 2, 'Compare the `while` line to a working `for` or `if` line - what do they all end with?');
INSERT INTO `bh_hints` VALUES (369, 123, 3, 'Add a colon `:` after `n > 0`.');
INSERT INTO `bh_hints` VALUES (370, 124, 1, 'This won\'t run - the error names exactly what\'s missing.');
INSERT INTO `bh_hints` VALUES (371, 124, 2, '`class` headers follow the same rule as `def` and `if` headers.');
INSERT INTO `bh_hints` VALUES (372, 124, 3, 'Add a colon `:` after `class Dog`.');
INSERT INTO `bh_hints` VALUES (373, 125, 1, 'This won\'t run at all - look at the block headers, not the logic.');
INSERT INTO `bh_hints` VALUES (374, 125, 2, '`except` is a block header just like `try` above it.');
INSERT INTO `bh_hints` VALUES (375, 125, 3, 'Add a colon `:` after `except ZeroDivisionError`.');
INSERT INTO `bh_hints` VALUES (376, 126, 1, 'This won\'t run - Python is still waiting for something by the time the file ends.');
INSERT INTO `bh_hints` VALUES (377, 126, 2, 'Count the square brackets on line 1.');
INSERT INTO `bh_hints` VALUES (378, 126, 3, 'Add the missing `]` after `30`.');
INSERT INTO `bh_hints` VALUES (379, 127, 1, 'This won\'t run - Python runs out of file still expecting one more character.');
INSERT INTO `bh_hints` VALUES (380, 127, 2, 'Count the curly braces on line 1.');
INSERT INTO `bh_hints` VALUES (381, 127, 3, 'Add the missing `}` after `2`.');
INSERT INTO `bh_hints` VALUES (382, 128, 1, 'The error names two specific bracket characters that disagree with each other.');
INSERT INTO `bh_hints` VALUES (383, 128, 2, 'This was opened with a round bracket. What does it close with?');
INSERT INTO `bh_hints` VALUES (384, 128, 3, 'Change the closing `]` to `)`.');
INSERT INTO `bh_hints` VALUES (385, 129, 1, 'This won\'t run - Python is still inside a string by the time the file ends.');
INSERT INTO `bh_hints` VALUES (386, 129, 2, 'A triple-quoted string needs its own matching triple quote to close, same as a single-quoted one.');
INSERT INTO `bh_hints` VALUES (387, 129, 3, 'Add `\"\"\"` at the end of \"to the game\".');
INSERT INTO `bh_hints` VALUES (388, 130, 1, 'This won\'t run - the error is about an f-string specifically.');
INSERT INTO `bh_hints` VALUES (389, 130, 2, 'Inside an f-string, `{` and `}` need to come in a matching pair around the variable name.');
INSERT INTO `bh_hints` VALUES (390, 130, 3, 'Add the missing `}` after `name`.');
INSERT INTO `bh_hints` VALUES (391, 131, 1, 'This is a syntax error about assignment, in a place Python only allows a comparison.');
INSERT INTO `bh_hints` VALUES (392, 131, 2, 'A `while` condition needs to ask a question, not store a value.');
INSERT INTO `bh_hints` VALUES (393, 131, 3, 'Change `=` to `==` in the `while` line.');
INSERT INTO `bh_hints` VALUES (394, 132, 1, 'This won\'t run - the error is specifically about the order of the parameters.');
INSERT INTO `bh_hints` VALUES (395, 132, 2, 'Once a parameter has a default value, every parameter after it must have one too.');
INSERT INTO `bh_hints` VALUES (396, 132, 3, 'Swap the order: put `name` first, `greeting=\"Hello\"` second.');
INSERT INTO `bh_hints` VALUES (397, 133, 1, 'This won\'t run at all - look closely at how each key links to its value.');
INSERT INTO `bh_hints` VALUES (398, 133, 2, 'A dictionary pairs a key with a value using a specific piece of punctuation, not an equals sign.');
INSERT INTO `bh_hints` VALUES (399, 133, 3, 'Change both `=` to `:` inside the `{}`.');
INSERT INTO `bh_hints` VALUES (400, 134, 1, 'This won\'t run - the word you\'re using as a variable name already means something else to Python.');
INSERT INTO `bh_hints` VALUES (401, 134, 2, '`class` is reserved for defining classes - it can\'t also be a variable name.');
INSERT INTO `bh_hints` VALUES (402, 134, 3, 'Rename the variable, e.g. `class_name`.');
INSERT INTO `bh_hints` VALUES (403, 135, 1, 'This is an `IndentationError` - the `else:` line itself is fine, look at what comes after it.');
INSERT INTO `bh_hints` VALUES (404, 135, 2, 'The line under `else:` needs to be indented one level further in, just like the line under `if`.');
INSERT INTO `bh_hints` VALUES (405, 135, 3, 'Indent `result = \"non-positive\"` to match the line under `if`.');
INSERT INTO `bh_hints` VALUES (406, 136, 1, 'This won\'t run - a `for` loop has an exact required shape.');
INSERT INTO `bh_hints` VALUES (407, 136, 2, 'A `for` loop reads as \"for (name) in (something)\" - one small word is missing here.');
INSERT INTO `bh_hints` VALUES (408, 136, 3, 'Add `in` between `i` and `range(5)`.');
INSERT INTO `bh_hints` VALUES (409, 137, 1, 'This won\'t run - the way of naming the caught error is written in an older style Python 3 doesn\'t use.');
INSERT INTO `bh_hints` VALUES (410, 137, 2, 'Modern Python links an exception to a name with a specific keyword, not a comma.');
INSERT INTO `bh_hints` VALUES (411, 137, 3, 'Change `except ValueError, e:` to `except ValueError as e:`.');
INSERT INTO `bh_hints` VALUES (412, 138, 1, 'This won\'t run - Python is still inside the string when the line ends.');
INSERT INTO `bh_hints` VALUES (413, 138, 2, 'A backslash right before the closing quote escapes the quote itself, instead of ending the string.');
INSERT INTO `bh_hints` VALUES (414, 138, 3, 'Use a raw string instead: `r\"C:\\Users\\notes\"` (no trailing backslash needed).');
INSERT INTO `bh_hints` VALUES (415, 139, 1, 'This won\'t run - the error names the exact keyword that\'s in the wrong place.');
INSERT INTO `bh_hints` VALUES (416, 139, 2, '`return` only makes sense inside a function. Check the indentation of this one.');
INSERT INTO `bh_hints` VALUES (417, 139, 3, 'Indent `return \"done\"` so it sits inside `greet`.');
INSERT INTO `bh_hints` VALUES (418, 140, 1, 'This won\'t run - the error names the exact keyword that\'s misplaced.');
INSERT INTO `bh_hints` VALUES (419, 140, 2, '`break` only makes sense inside a loop. Check this one\'s indentation against the `for` line.');
INSERT INTO `bh_hints` VALUES (420, 140, 3, 'Delete the stray `break` line - it was never inside the loop to begin with.');
INSERT INTO `bh_hints` VALUES (421, 141, 1, 'This won\'t run - Python reads a punctuation mark here as an operator, not part of a name.');
INSERT INTO `bh_hints` VALUES (422, 141, 2, 'A hyphen means subtraction to Python. Variable names use a different character to join words.');
INSERT INTO `bh_hints` VALUES (423, 141, 3, 'Change the hyphen to an underscore: `student_count`.');
INSERT INTO `bh_hints` VALUES (424, 142, 1, 'This won\'t run - the error is about an invalid number, even though you were trying to write a name.');
INSERT INTO `bh_hints` VALUES (425, 142, 2, 'A variable name is not allowed to start with a digit.');
INSERT INTO `bh_hints` VALUES (426, 142, 3, 'Spell out the number instead: `second_place`.');
INSERT INTO `bh_hints` VALUES (427, 143, 1, 'The error names a bracket that has nothing left to match it.');
INSERT INTO `bh_hints` VALUES (428, 143, 2, 'Count the opening and closing round brackets on line 1.');
INSERT INTO `bh_hints` VALUES (429, 143, 3, 'Remove the extra `)`.');
INSERT INTO `bh_hints` VALUES (430, 144, 1, 'This won\'t run - a `lambda` has a required shape, same idea as a block header.');
INSERT INTO `bh_hints` VALUES (431, 144, 2, 'A lambda reads as \"lambda (parameters): (expression)\" - something is missing between them.');
INSERT INTO `bh_hints` VALUES (432, 144, 3, 'Add a colon `:` between `x` and `x * x`.');
INSERT INTO `bh_hints` VALUES (433, 145, 1, 'This won\'t run - the first line ends expecting more, and never gets it.');
INSERT INTO `bh_hints` VALUES (434, 145, 2, 'An expression split across lines needs to either be wrapped in brackets, or use a line-continuation backslash.');
INSERT INTO `bh_hints` VALUES (435, 145, 3, 'Wrap the whole expression in parentheses: `total = (1 + 2 +` then `3 + 4)`.');
INSERT INTO `bh_hints` VALUES (436, 146, 1, 'This won\'t run - `global` only ever does one job, and this line asks it to do two.');
INSERT INTO `bh_hints` VALUES (437, 146, 2, '`global` just declares which name you mean. The actual assignment needs its own line.');
INSERT INTO `bh_hints` VALUES (438, 146, 3, 'Split it into two lines: `global counter` then `counter = counter + 1`.');
INSERT INTO `bh_hints` VALUES (439, 147, 1, 'This won\'t run - the error even suggests the fix directly.');
INSERT INTO `bh_hints` VALUES (440, 147, 2, 'In current Python, `print` is a function - every function call needs parentheses.');
INSERT INTO `bh_hints` VALUES (441, 147, 3, 'Wrap the text in parentheses: `print(\"Game over\")`.');
INSERT INTO `bh_hints` VALUES (442, 148, 1, 'This won\'t run - check every block header in this function, not just the first `if`.');
INSERT INTO `bh_hints` VALUES (443, 148, 2, '`elif` needs exactly the same trailing punctuation as `if`.');
INSERT INTO `bh_hints` VALUES (444, 148, 3, 'Add a colon `:` after `score >= 80`.');
INSERT INTO `bh_hints` VALUES (445, 149, 1, 'This won\'t run - the string itself never closes, separately from the `{}` inside it.');
INSERT INTO `bh_hints` VALUES (446, 149, 2, 'The `{name}` part is fine. Look at the quote marks around the whole f-string.');
INSERT INTO `bh_hints` VALUES (447, 149, 3, 'Add the missing closing `\"` at the end of the f-string.');
INSERT INTO `bh_hints` VALUES (448, 150, 1, 'This won\'t run - the string never actually closes.');
INSERT INTO `bh_hints` VALUES (449, 150, 2, 'It was opened with `\'\'\'`. The `\"\"\"` further down is a different kind of triple quote entirely - Python just reads it as more text.');
INSERT INTO `bh_hints` VALUES (450, 150, 3, 'Change the closing `\"\"\"` to `\'\'\'`, matching how the string opened.');
INSERT INTO `bh_hints` VALUES (451, 151, 1, 'The code runs and then crashes - that\'s a `NameError`. Read the traceback\'s last line first.');
INSERT INTO `bh_hints` VALUES (452, 151, 2, 'Look at the variable used inside the message. Compare its spelling to the function\'s parameter.');
INSERT INTO `bh_hints` VALUES (453, 151, 3, '`nmae` should be `name` - fix the typo so it matches the parameter exactly.');
INSERT INTO `bh_hints` VALUES (454, 152, 1, 'This crashes with a `TypeError` about joining two things together.');
INSERT INTO `bh_hints` VALUES (455, 152, 2, '`age` is a number, but `+` between a string and a number is not allowed directly.');
INSERT INTO `bh_hints` VALUES (456, 152, 3, 'Wrap `age` in `str(...)` before joining it to the string.');
INSERT INTO `bh_hints` VALUES (457, 153, 1, 'This crashes with an `IndexError` - the position asked for is out of range.');
INSERT INTO `bh_hints` VALUES (458, 153, 2, 'If a list has 3 items, what are its valid index positions? Does `len(items)` itself point at a real item?');
INSERT INTO `bh_hints` VALUES (459, 153, 3, 'Use `items[len(items) - 1]` instead of `items[len(items)]`.');
INSERT INTO `bh_hints` VALUES (460, 154, 1, 'This crashes with a `KeyError` - the dictionary was asked for something it doesn\'t have.');
INSERT INTO `bh_hints` VALUES (461, 154, 2, 'There\'s a dictionary method that returns a default value instead of crashing when a key is missing.');
INSERT INTO `bh_hints` VALUES (462, 154, 3, 'Use `colours.get(fruit, \"unknown\")` instead of `colours[fruit]`.');
INSERT INTO `bh_hints` VALUES (463, 155, 1, 'This crashes with a `ZeroDivisionError` on at least one test - which input might make `len(nums)` zero?');
INSERT INTO `bh_hints` VALUES (464, 155, 2, 'Check for an empty list before dividing, and decide what the function should return in that case.');
INSERT INTO `bh_hints` VALUES (465, 155, 3, 'Add `if len(nums) == 0: return 0` before the division.');
INSERT INTO `bh_hints` VALUES (466, 156, 1, 'This crashes with a `ValueError` on at least one test - the text given isn\'t in the exact shape `int()` accepts.');
INSERT INTO `bh_hints` VALUES (467, 156, 2, '`int()` can convert whole-number text directly, but not text with a decimal point. What can read a decimal point first?');
INSERT INTO `bh_hints` VALUES (468, 156, 3, 'Convert via `float(text)` first, then wrap that in `int(...)`.');
INSERT INTO `bh_hints` VALUES (469, 157, 1, 'The code runs without errors, but the result is always `None` - that\'s a strong clue about what\'s missing.');
INSERT INTO `bh_hints` VALUES (470, 157, 2, 'A function only gives back a value if it explicitly says to.');
INSERT INTO `bh_hints` VALUES (471, 157, 3, 'Add `return total` as the last line of the function.');
INSERT INTO `bh_hints` VALUES (472, 158, 1, 'This crashes with an `UnboundLocalError` - a variable is used before it has a value, inside this function specifically.');
INSERT INTO `bh_hints` VALUES (473, 158, 2, 'Assigning to a name anywhere inside a function makes Python treat it as local for the *whole* function, even on lines before the assignment. Is `count` meant to be local here?');
INSERT INTO `bh_hints` VALUES (474, 158, 3, 'Add `global count` as the first line inside `increment`.');
INSERT INTO `bh_hints` VALUES (475, 159, 1, 'This crashes with a `TypeError` about joining a string and a number.');
INSERT INTO `bh_hints` VALUES (476, 159, 2, '`price_text` looks like a number but is still text - what does `\"4\" * 3` actually produce?');
INSERT INTO `bh_hints` VALUES (477, 159, 3, 'Convert `price_text` with `int(...)` before using it in the calculation.');
INSERT INTO `bh_hints` VALUES (478, 160, 1, 'This crashes with a `TypeError` about the number of arguments given versus expected.');
INSERT INTO `bh_hints` VALUES (479, 160, 2, 'Compare the function\'s `def` line to what the brief says it should accept.');
INSERT INTO `bh_hints` VALUES (480, 160, 3, 'Add the missing `last_name` parameter and use it in the greeting.');
INSERT INTO `bh_hints` VALUES (481, 161, 1, 'Read the error from the bottom - it names the exact method name it looked for and couldn\'t find.');
INSERT INTO `bh_hints` VALUES (482, 161, 2, 'Strings have a method for uppercasing, but it isn\'t spelled the way this reads.');
INSERT INTO `bh_hints` VALUES (483, 161, 3, 'Change `.uppercase()` to `.upper()`.');
INSERT INTO `bh_hints` VALUES (484, 162, 1, 'The crash is in `greeting`, but the real mistake is one function earlier, in `get_name`.');
INSERT INTO `bh_hints` VALUES (485, 162, 2, '`get_name` has no `return` for the case where there\'s no name - which means it silently returns `None` instead.');
INSERT INTO `bh_hints` VALUES (486, 162, 3, 'Add `return \"unknown\"` at the end of `get_name`.');
INSERT INTO `bh_hints` VALUES (487, 163, 1, 'The error says something isn\'t callable - that\'s a strong clue about which bracket is wrong.');
INSERT INTO `bh_hints` VALUES (488, 163, 2, '`totals` is a list. Calling it like a function with `()` isn\'t the same as indexing into it.');
INSERT INTO `bh_hints` VALUES (489, 163, 3, 'Change `totals(0)` to `totals[0]`.');
INSERT INTO `bh_hints` VALUES (490, 164, 1, 'The error says a number is \"not iterable\" - `for` only works on things you can step through.');
INSERT INTO `bh_hints` VALUES (491, 164, 2, 'You can loop over the characters of a string, but not the digits of a number directly.');
INSERT INTO `bh_hints` VALUES (492, 164, 3, 'Convert `n` to a string first: `for digit in str(n):`.');
INSERT INTO `bh_hints` VALUES (493, 165, 1, 'The error says a number is \"not subscriptable\" - indexing with `[]` only works on sequences.');
INSERT INTO `bh_hints` VALUES (494, 165, 2, 'To get at individual digits, convert the number to a string first, then convert the result back.');
INSERT INTO `bh_hints` VALUES (495, 165, 3, 'Use `int(str(n)[-1])`.');
INSERT INTO `bh_hints` VALUES (496, 166, 1, 'Negative indexes count from the end - but they can still go out of range.');
INSERT INTO `bh_hints` VALUES (497, 166, 2, 'What happens when the list is too short to have a \"second to last\" item?');
INSERT INTO `bh_hints` VALUES (498, 166, 3, 'Check `len(scores) < 2` first, and return `None` in that case.');
INSERT INTO `bh_hints` VALUES (499, 167, 1, 'This crashes with a `KeyError` - the exact same idea as indexing a missing dictionary key.');
INSERT INTO `bh_hints` VALUES (500, 167, 2, '`.pop()` on a dictionary needs the key to actually be there, unless you check first.');
INSERT INTO `bh_hints` VALUES (501, 167, 3, 'Check `if item in cart:` before calling `.pop(item)`.');
INSERT INTO `bh_hints` VALUES (502, 168, 1, 'This crashes with an `IndexError` - the same family as indexing past the end of a list.');
INSERT INTO `bh_hints` VALUES (503, 168, 2, 'There is nothing at position 0 of an empty list to remove.');
INSERT INTO `bh_hints` VALUES (504, 168, 3, 'Check `if not queue:` first and return `None` in that case.');
INSERT INTO `bh_hints` VALUES (505, 169, 1, '`len()` only works on things with a length - a plain number does not have one.');
INSERT INTO `bh_hints` VALUES (506, 169, 2, 'Converting the number to a string gives you something `len()` can measure.');
INSERT INTO `bh_hints` VALUES (507, 169, 3, 'Use `len(str(n))`.');
INSERT INTO `bh_hints` VALUES (508, 170, 1, '`int()` needs text that looks like just a number, nothing else.');
INSERT INTO `bh_hints` VALUES (509, 170, 2, 'Splitting the text on spaces gives you the first word on its own.');
INSERT INTO `bh_hints` VALUES (510, 170, 3, 'Use `int(text.split()[0])`.');
INSERT INTO `bh_hints` VALUES (511, 171, 1, '`+` between a list and a number is not allowed - only list-plus-list is.');
INSERT INTO `bh_hints` VALUES (512, 171, 2, 'You want to add `bonus` to every item, not add `bonus` to the list itself.');
INSERT INTO `bh_hints` VALUES (513, 171, 3, 'Use a list comprehension: `[s + bonus for s in scores]`.');
INSERT INTO `bh_hints` VALUES (514, 172, 1, 'Python refuses to say whether a number is bigger than a piece of text - they are not comparable.');
INSERT INTO `bh_hints` VALUES (515, 172, 2, 'Look closely at the `18` on the right of `>=` - is it really a number?');
INSERT INTO `bh_hints` VALUES (516, 172, 3, 'Remove the quote marks: `age >= 18`.');
INSERT INTO `bh_hints` VALUES (517, 173, 1, 'The error names the exact method it looked for - read it character by character.');
INSERT INTO `bh_hints` VALUES (518, 173, 2, 'There\'s a real list method that adds one item to the end, spelled slightly differently to this.');
INSERT INTO `bh_hints` VALUES (519, 173, 3, 'Change `.appned` to `.append`.');
INSERT INTO `bh_hints` VALUES (520, 174, 1, 'When there\'s no negative number, this crashes right at the end of the list - that timing is a clue.');
INSERT INTO `bh_hints` VALUES (521, 174, 2, 'Compare the `while` condition to the valid index range of the list - `len(numbers)` itself is never a valid index.');
INSERT INTO `bh_hints` VALUES (522, 174, 3, 'Change `i <= len(numbers)` to `i < len(numbers)`.');
INSERT INTO `bh_hints` VALUES (523, 175, 1, 'The error is about a local variable being referenced before it has a value.');
INSERT INTO `bh_hints` VALUES (524, 175, 2, 'Because `total` is assigned somewhere inside this function, Python treats it as local for the *whole* function - including the line before it is assigned.');
INSERT INTO `bh_hints` VALUES (525, 175, 3, 'Remove the stray `print(total)` line that comes before `total` is ever assigned.');
INSERT INTO `bh_hints` VALUES (526, 176, 1, 'The error names the function and says how many arguments it actually accepts.');
INSERT INTO `bh_hints` VALUES (527, 176, 2, '`round()` only ever takes a number and (optionally) how many decimal places - nothing more.');
INSERT INTO `bh_hints` VALUES (528, 176, 3, 'Remove the extra `10`: `round(price, 2)`.');
INSERT INTO `bh_hints` VALUES (529, 177, 1, 'This crashes with a `KeyError` whenever the subject was never recorded.');
INSERT INTO `bh_hints` VALUES (530, 177, 2, 'Dictionaries have a lookup method that lets you supply a fallback value instead of crashing.');
INSERT INTO `bh_hints` VALUES (531, 177, 3, 'Use `grades.get(subject, \"Not taken\")`.');
INSERT INTO `bh_hints` VALUES (532, 178, 1, 'The error says a type is \"unhashable\" - dictionary keys have to be a fixed, unchangeable kind of value.');
INSERT INTO `bh_hints` VALUES (533, 178, 2, 'Lists can change after they are created, which is exactly why they cannot be dictionary keys. Is there a similar, unchangeable type?');
INSERT INTO `bh_hints` VALUES (534, 178, 3, 'Convert `stops` to a tuple first: `visited[tuple(stops)] = True`.');
INSERT INTO `bh_hints` VALUES (535, 179, 1, 'The valid indexes of a string run from `0` to one less than its length - not up to the length itself.');
INSERT INTO `bh_hints` VALUES (536, 179, 2, '`word[len(word)]` is always exactly one position past the end.');
INSERT INTO `bh_hints` VALUES (537, 179, 3, 'Subtract 1: `word[len(word) - 1]`.');
INSERT INTO `bh_hints` VALUES (538, 180, 1, 'This crashes specifically when the list has nothing in it.');
INSERT INTO `bh_hints` VALUES (539, 180, 2, 'Dividing by `len(numbers)` is only safe if there is at least one number.');
INSERT INTO `bh_hints` VALUES (540, 180, 3, 'Check `if not numbers:` first and return `0`.');
INSERT INTO `bh_hints` VALUES (541, 181, 1, 'This crashes with a `NameError` - but the name really is defined somewhere in this file.');
INSERT INTO `bh_hints` VALUES (542, 181, 2, 'Python runs a script top to bottom. A function has to be *defined* before the line that calls it actually runs.');
INSERT INTO `bh_hints` VALUES (543, 181, 3, 'Move the `def start_game():` block above the line that calls it.');
INSERT INTO `bh_hints` VALUES (544, 182, 1, 'Strings don\'t have the method this is trying to use.');
INSERT INTO `bh_hints` VALUES (545, 182, 2, '`.sort()` changes a list in place. Strings can\'t be changed in place at all - but there\'s a function that builds a new sorted result instead.');
INSERT INTO `bh_hints` VALUES (546, 182, 3, 'Use `\"\".join(sorted(word))` instead.');
INSERT INTO `bh_hints` VALUES (547, 183, 1, 'This crashes after calling itself an enormous number of times - that specific error has a name.');
INSERT INTO `bh_hints` VALUES (548, 183, 2, 'Every recursive function needs a condition that stops it calling itself again.');
INSERT INTO `bh_hints` VALUES (549, 183, 3, 'Add `if n <= 0: return \"Liftoff!\"` before the recursive call.');
INSERT INTO `bh_hints` VALUES (550, 184, 1, 'This crashes when there are only exactly two items - that timing is a clue.');
INSERT INTO `bh_hints` VALUES (551, 184, 2, '`next()` raises an error once an iterator has nothing left to give. How many times does this call it?');
INSERT INTO `bh_hints` VALUES (552, 184, 3, 'Only call `next(it)` twice, and return `[a, b]`.');
INSERT INTO `bh_hints` VALUES (553, 185, 1, '`%` (modulo) crashes for the same reason `/` does, in the same situation.');
INSERT INTO `bh_hints` VALUES (554, 185, 2, 'What should happen when `group_size` is `0`?');
INSERT INTO `bh_hints` VALUES (555, 185, 3, 'Check `if group_size == 0:` first and return `False`.');
INSERT INTO `bh_hints` VALUES (556, 186, 1, 'This crashes on the very first number it tries to add.');
INSERT INTO `bh_hints` VALUES (557, 186, 2, 'The starting value for an accumulator needs to match the type of thing you are accumulating.');
INSERT INTO `bh_hints` VALUES (558, 186, 3, 'Start `total` at `0`, not `\"\"`.');
INSERT INTO `bh_hints` VALUES (559, 187, 1, '`.keys()` is specifically a dictionary method - check what type `students` actually is.');
INSERT INTO `bh_hints` VALUES (560, 187, 2, '`students` is a list of names, not a dictionary - there is no \"keys\" to ask for.');
INSERT INTO `bh_hints` VALUES (561, 187, 3, 'Build the unique list yourself with a loop, checking `if s not in seen`.');
INSERT INTO `bh_hints` VALUES (562, 188, 1, 'The error names an \"unexpected keyword argument\" - the name used does not match any real parameter.');
INSERT INTO `bh_hints` VALUES (563, 188, 2, 'Compare the keyword used in the call (`prices=`) to the parameter name in the function definition above it.');
INSERT INTO `bh_hints` VALUES (564, 188, 3, 'Change `prices=price` to `price=price`.');
INSERT INTO `bh_hints` VALUES (565, 189, 1, 'This crashes only on names with more than two words - that timing is a clue.');
INSERT INTO `bh_hints` VALUES (566, 189, 2, '`a, b = something` needs `something` to have exactly two items - a three-word name splits into three.');
INSERT INTO `bh_hints` VALUES (567, 189, 3, 'Split into a list first, then take the first and last items with indexing instead of unpacking.');
INSERT INTO `bh_hints` VALUES (568, 190, 1, 'The error names how many values it found versus how many names were waiting for them.');
INSERT INTO `bh_hints` VALUES (569, 190, 2, '`point` only has two values in it, but the unpacking expects three.');
INSERT INTO `bh_hints` VALUES (570, 190, 3, 'Unpack into exactly two names: `x, y = point`.');
INSERT INTO `bh_hints` VALUES (571, 191, 1, 'The code runs without errors, so this is a logic bug. Compare your result for `sum_to(4)` with 10.');
INSERT INTO `bh_hints` VALUES (572, 191, 2, 'Look at the `range()` call. Which numbers does `range(1, n)` actually produce?');
INSERT INTO `bh_hints` VALUES (573, 191, 3, '`range` stops one short of its second value. You need the loop to reach `n` itself.');
INSERT INTO `bh_hints` VALUES (574, 192, 1, 'This runs fine but gives the wrong number - count the posts for a tiny fence by hand (try 1 section) and compare.');
INSERT INTO `bh_hints` VALUES (575, 192, 2, 'A fence with 1 section has posts at both ends - that\'s 2 posts, not 1.');
INSERT INTO `bh_hints` VALUES (576, 192, 3, 'Add 1 to `sections`.');
INSERT INTO `bh_hints` VALUES (577, 193, 1, 'This passes some tests but not others - try an example where the exact average has a fraction in it.');
INSERT INTO `bh_hints` VALUES (578, 193, 2, 'There are two different division operators in Python, and they behave very differently.');
INSERT INTO `bh_hints` VALUES (579, 193, 3, 'Change `//` to `/`.');
INSERT INTO `bh_hints` VALUES (580, 194, 1, 'This runs fine but gives the wrong answer for most inputs - check `average_two(4, 6)` by hand.');
INSERT INTO `bh_hints` VALUES (581, 194, 2, 'Without brackets, which happens first: the division, or the addition?');
INSERT INTO `bh_hints` VALUES (582, 194, 3, 'Wrap `a + b` in brackets so it happens before the division: `(a + b) / 2`.');
INSERT INTO `bh_hints` VALUES (583, 195, 1, 'Try a name that\'s clearly too long or too short - does it get rejected like you\'d expect?');
INSERT INTO `bh_hints` VALUES (584, 195, 2, 'Both conditions need to be true for a name to be valid - is that what `or` checks?');
INSERT INTO `bh_hints` VALUES (585, 195, 3, 'Change `or` to `and`.');
INSERT INTO `bh_hints` VALUES (586, 196, 1, 'This works when the first number happens to be even, but fails otherwise - try a list that starts with an odd number.');
INSERT INTO `bh_hints` VALUES (587, 196, 2, 'Look at the indentation of the final `return None`. Is it meant to run after checking just one number, or after checking all of them?');
INSERT INTO `bh_hints` VALUES (588, 196, 3, 'Move `return None` outside the `for` loop, so it only runs once every number has been checked.');
INSERT INTO `bh_hints` VALUES (589, 197, 1, 'The first result is right but later ones creep upward - the totals seem to be adding onto each other.');
INSERT INTO `bh_hints` VALUES (590, 197, 2, 'Where is `total` set back to 0? Does that happen once, or once per inner list?');
INSERT INTO `bh_hints` VALUES (591, 197, 3, 'Move `total = 0` inside the outer `for` loop, so it resets for every inner list.');
INSERT INTO `bh_hints` VALUES (592, 198, 1, 'This run gets stopped for taking too long - something about the loop condition never changes.');
INSERT INTO `bh_hints` VALUES (593, 198, 2, 'The `while` loop keeps checking `n > 0`. Does anything inside the loop ever change `n`?');
INSERT INTO `bh_hints` VALUES (594, 198, 3, 'Add `n -= 1` inside the loop body.');
INSERT INTO `bh_hints` VALUES (595, 199, 1, 'This gives the wrong answer for some inputs - try comparing \"10\" and \"9\" and see which one it picks.');
INSERT INTO `bh_hints` VALUES (596, 199, 2, 'The arguments are text, not numbers. How does Python compare two pieces of text?');
INSERT INTO `bh_hints` VALUES (597, 199, 3, 'Convert `a` and `b` to numbers with `int(...)` before comparing them.');
INSERT INTO `bh_hints` VALUES (598, 200, 1, 'This crashes with a `TypeError` saying something is \"not callable\".');
INSERT INTO `bh_hints` VALUES (599, 200, 2, 'There\'s a built-in function called `sum`. Is there also a variable called `sum` in this function?');
INSERT INTO `bh_hints` VALUES (600, 200, 3, 'Remove the unused `sum = 0` line so `sum(...)` still refers to the built-in function.');
INSERT INTO `bh_hints` VALUES (601, 201, 1, 'Try a list with two negative numbers next to each other - does it remove both?');
INSERT INTO `bh_hints` VALUES (602, 201, 2, 'Removing an item from a list while you\'re iterating over it shifts everything after it along by one - which can make the loop skip the very next item.');
INSERT INTO `bh_hints` VALUES (603, 201, 3, 'Build a new list with a list comprehension instead of removing items from the original while looping over it.');
INSERT INTO `bh_hints` VALUES (604, 202, 1, 'This works for lowercase text, but try an all-uppercase word.');
INSERT INTO `bh_hints` VALUES (605, 202, 2, '`\"aeiou\"` only contains lowercase letters. What happens when `ch` is uppercase?');
INSERT INTO `bh_hints` VALUES (606, 202, 3, 'Compare `ch.lower()` against `\"aeiou\"` instead of `ch` directly.');
INSERT INTO `bh_hints` VALUES (607, 203, 1, 'Run it on a list where every number is negative, and compare the result to what you expected.');
INSERT INTO `bh_hints` VALUES (608, 203, 2, 'Starting `best` at `0` assumes the answer is never negative - what if every number in the list actually is?');
INSERT INTO `bh_hints` VALUES (609, 203, 3, 'Start `best` at `numbers[0]`, the actual first item, instead of a fixed `0`.');
INSERT INTO `bh_hints` VALUES (610, 204, 1, 'Try calling it with the two arguments swapped around - does the brief say the order should matter?');
INSERT INTO `bh_hints` VALUES (611, 204, 2, '`a - b` can come out negative if `b` is bigger than `a`. There is a built-in function that strips the sign off a number.');
INSERT INTO `bh_hints` VALUES (612, 204, 3, 'Wrap the subtraction in `abs(...)`.');
INSERT INTO `bh_hints` VALUES (613, 205, 1, 'Try a list where just one score fails - does the function notice?');
INSERT INTO `bh_hints` VALUES (614, 205, 2, 'This returns `True` the moment it finds *one* passing score - but the brief wants *every* score to pass.');
INSERT INTO `bh_hints` VALUES (615, 205, 3, 'Check for a *failing* score and return `False` immediately if you find one; only return `True` once the whole loop finishes.');
INSERT INTO `bh_hints` VALUES (616, 206, 1, 'Try a clearly hot temperature and a clearly mild one - do the results come back the right way round?');
INSERT INTO `bh_hints` VALUES (617, 206, 2, 'The condition itself is correct. Look at which word is returned from which branch.');
INSERT INTO `bh_hints` VALUES (618, 206, 3, 'Swap `\"mild\"` and `\"hot\"` between the two branches.');
INSERT INTO `bh_hints` VALUES (619, 207, 1, 'Check the actual value this returns for `\"10\"` and `\"20\"` - is it a number, or something else?');
INSERT INTO `bh_hints` VALUES (620, 207, 2, '`+` on two strings joins them together rather than adding their numeric values.');
INSERT INTO `bh_hints` VALUES (621, 207, 3, 'Convert both to numbers first: `int(score1) + int(score2)`.');
INSERT INTO `bh_hints` VALUES (622, 208, 1, 'Check whether the result actually contains the *highest* scores, or the lowest.');
INSERT INTO `bh_hints` VALUES (623, 208, 2, '`sorted()` arranges smallest-to-largest by default - taking the first 3 of that gives the lowest, not the highest.');
INSERT INTO `bh_hints` VALUES (624, 208, 3, 'Add `reverse=True` so the sort runs largest-to-smallest.');
INSERT INTO `bh_hints` VALUES (625, 209, 1, 'Try `highest_id([\"9\", \"10\", \"2\"])` - \"10\" should win numerically, but does it?');
INSERT INTO `bh_hints` VALUES (626, 209, 2, 'Comparing strings compares them character by character, like a dictionary - `\"9\"` comes after `\"1\"` that way, even though 9 is smaller than 10.');
INSERT INTO `bh_hints` VALUES (627, 209, 3, 'Tell `max()` to compare by numeric value: `max(ids, key=int)`.');
INSERT INTO `bh_hints` VALUES (628, 210, 1, 'Try an amount very close to the next whole dollar, like 199 cents - should that round up or stay down?');
INSERT INTO `bh_hints` VALUES (629, 210, 2, '`int(...)` always cuts off the decimal part - it never rounds up, no matter how close.');
INSERT INTO `bh_hints` VALUES (630, 210, 3, 'Use `round(cents / 100)` instead of `int(cents / 100)`.');
INSERT INTO `bh_hints` VALUES (631, 211, 1, 'Try the exact boundary value, 90, and check the brief again - should \"90 or above\" include 90 itself?');
INSERT INTO `bh_hints` VALUES (632, 211, 2, '`>` excludes the boundary value itself; `>=` includes it.');
INSERT INTO `bh_hints` VALUES (633, 211, 3, 'Change both `>` to `>=`.');
INSERT INTO `bh_hints` VALUES (634, 212, 1, 'Try a name that is spelled right but in different letter-case to how it was stored.');
INSERT INTO `bh_hints` VALUES (635, 212, 2, '`in` compares text exactly, including case - `\"ada\"` and `\"Ada\"` are different strings to Python.');
INSERT INTO `bh_hints` VALUES (636, 212, 3, 'Lower-case both sides before comparing.');
INSERT INTO `bh_hints` VALUES (637, 213, 1, 'Call it with two separately-written lists that contain exactly the same values - does it say they match?');
INSERT INTO `bh_hints` VALUES (638, 213, 2, '`is` checks whether two names refer to the *exact same object in memory* - two separately-built lists with equal contents are still two different objects.');
INSERT INTO `bh_hints` VALUES (639, 213, 3, 'Change `is` to `==`.');
INSERT INTO `bh_hints` VALUES (640, 214, 1, 'Look at what the result actually contains - is every number in it even?');
INSERT INTO `bh_hints` VALUES (641, 214, 2, '`range(start, stop, step)` - the step decides how much it jumps by each time. What step gives only even numbers?');
INSERT INTO `bh_hints` VALUES (642, 214, 3, 'Change the step from `1` to `2`.');
INSERT INTO `bh_hints` VALUES (643, 215, 1, 'Count the characters in the result - is it actually `n` characters long?');
INSERT INTO `bh_hints` VALUES (644, 215, 2, 'A slice `text[0:n]` already stops *before* position `n` - it does not need an extra `-1`.');
INSERT INTO `bh_hints` VALUES (645, 215, 3, 'Change `text[0:n-1]` to `text[0:n]`.');
INSERT INTO `bh_hints` VALUES (646, 216, 1, 'Try a list with a negative number *in the middle*, with more positives after it.');
INSERT INTO `bh_hints` VALUES (647, 216, 2, '`break` stops the whole loop the first time it hits a non-positive number, even if positives still come later.');
INSERT INTO `bh_hints` VALUES (648, 216, 3, 'Remove the `else: break` - just skip non-positive numbers and keep going.');
INSERT INTO `bh_hints` VALUES (649, 217, 1, 'Try `percent_correct(1, 4)` - 1 out of 4 should be 25%. What does this actually give?');
INSERT INTO `bh_hints` VALUES (650, 217, 2, 'A percentage is \"part divided by whole\", not \"whole divided by part\" - which variable is the part here, and which is the whole?');
INSERT INTO `bh_hints` VALUES (651, 217, 3, 'Swap the division: `correct / total * 100`.');
INSERT INTO `bh_hints` VALUES (652, 218, 1, 'Try a level that is neither `\"gold\"` nor `\"silver\"` - what discount does it get?');
INSERT INTO `bh_hints` VALUES (653, 218, 2, 'The final `return` is meant to be the fallback for everything else - check its value against the brief.');
INSERT INTO `bh_hints` VALUES (654, 218, 3, 'Change the final `return 10` to `return 0`.');
INSERT INTO `bh_hints` VALUES (655, 219, 1, 'Try a word with *no* vowels at all, like \"sky\" - what count comes back?');
INSERT INTO `bh_hints` VALUES (656, 219, 2, '`letter == \"a\" or \"e\" or \"i\" or \"o\" or \"u\"` is not asking \"is letter one of these?\" - it is five separate things joined by `or`, and most of them are just non-empty strings, which Python treats as true on their own.');
INSERT INTO `bh_hints` VALUES (657, 219, 3, 'Use `if letter in \"aeiou\":` to check membership properly.');
INSERT INTO `bh_hints` VALUES (658, 220, 1, 'Try a list of only odd numbers - the function is named \"evens\", so what should that return?');
INSERT INTO `bh_hints` VALUES (659, 220, 2, '`n % 2 == 1` is true for odd numbers, not even ones.');
INSERT INTO `bh_hints` VALUES (660, 220, 3, 'Change the condition to `n % 2 == 0`.');
INSERT INTO `bh_hints` VALUES (661, 221, 1, 'The function is called \"cheapest\" - check the result is actually the smallest value, not the largest.');
INSERT INTO `bh_hints` VALUES (662, 221, 2, '`if p > best: best = p` keeps the biggest value it has seen, which finds a maximum, not a minimum.');
INSERT INTO `bh_hints` VALUES (663, 221, 3, 'Change `>` to `<`.');
INSERT INTO `bh_hints` VALUES (664, 222, 1, 'Try a short password that otherwise looks fine - should it pass if it fails just one of the two rules?');
INSERT INTO `bh_hints` VALUES (665, 222, 2, '`or` accepts it if *either* condition is true. The brief wants *both* to be true.');
INSERT INTO `bh_hints` VALUES (666, 222, 3, 'Change `or` to `and`.');
INSERT INTO `bh_hints` VALUES (667, 223, 1, 'Try a tall rider with no adult present - the brief says tall enough alone should be fine.');
INSERT INTO `bh_hints` VALUES (668, 223, 2, '`and` requires both conditions - the brief only needs one of them to be true.');
INSERT INTO `bh_hints` VALUES (669, 223, 3, 'Change `and` to `or`.');
INSERT INTO `bh_hints` VALUES (670, 224, 1, 'Check the actual numbers in the result - are they odd, or even?');
INSERT INTO `bh_hints` VALUES (671, 224, 2, '`n % 2 == 0` is the test for an *even* number.');
INSERT INTO `bh_hints` VALUES (672, 224, 3, 'Change `== 0` to `== 1`.');
INSERT INTO `bh_hints` VALUES (673, 225, 1, 'Check the order of the words in the result against the brief\'s example.');
INSERT INTO `bh_hints` VALUES (674, 225, 2, 'The two parameters are being joined in the opposite order to the one named in the brief.');
INSERT INTO `bh_hints` VALUES (675, 225, 3, 'Swap the order: `first + \" \" + last`.');
INSERT INTO `bh_hints` VALUES (676, 226, 1, 'This never even uses the price - does that match what a \"cost\" should depend on?');
INSERT INTO `bh_hints` VALUES (677, 226, 2, 'The number of items needs to be multiplied by the price of each one.');
INSERT INTO `bh_hints` VALUES (678, 226, 3, 'Return `items * price_per_item`.');
INSERT INTO `bh_hints` VALUES (679, 227, 1, 'Try exactly 5 years - the brief says \"5 years or more\" - does that include exactly 5?');
INSERT INTO `bh_hints` VALUES (680, 227, 2, '`>` excludes the value 5 itself.');
INSERT INTO `bh_hints` VALUES (681, 227, 3, 'Change `>` to `>=`.');
INSERT INTO `bh_hints` VALUES (682, 228, 1, 'Try lists of different lengths - does the \"average\" scale sensibly, or does it look off for short or long lists?');
INSERT INTO `bh_hints` VALUES (683, 228, 2, 'Dividing by a fixed `100` only makes sense if there are always exactly 100 scores.');
INSERT INTO `bh_hints` VALUES (684, 228, 3, 'Divide by `len(scores)` instead of `100`.');
INSERT INTO `bh_hints` VALUES (685, 229, 1, 'Try a score that is clearly a win and check what comes back.');
INSERT INTO `bh_hints` VALUES (686, 229, 2, 'The comparisons for \"Win\" and \"Loss\" use the opposite direction to what their labels suggest.');
INSERT INTO `bh_hints` VALUES (687, 229, 3, 'Swap `<` and `>` between the two branches.');
INSERT INTO `bh_hints` VALUES (688, 230, 1, 'Check the type and exact value of the result - is it a whole number of minutes?');
INSERT INTO `bh_hints` VALUES (689, 230, 2, '`/` gives an exact (possibly fractional) result; \"whole minutes\" wants the result rounded down to a whole number.');
INSERT INTO `bh_hints` VALUES (690, 230, 3, 'Use `//` (integer/floor division) instead of `/`.');
INSERT INTO `bh_hints` VALUES (691, 231, 1, 'Look very closely at the assignment inside the loop - which name does it actually store?');
INSERT INTO `bh_hints` VALUES (692, 231, 2, 'There are two very similarly-named things in scope here: the current word, and the entire list of words.');
INSERT INTO `bh_hints` VALUES (693, 231, 3, 'Change `longest = words` to `longest = w` (the loop variable, not the whole list).');
INSERT INTO `bh_hints` VALUES (694, 232, 1, 'Work out `average_of_two(10, 0)` by hand, then compare it to what the code actually gives.');
INSERT INTO `bh_hints` VALUES (695, 232, 2, 'Python does division before addition unless you tell it otherwise - that is not the order \"average\" needs.');
INSERT INTO `bh_hints` VALUES (696, 232, 3, 'Wrap the addition in brackets: `(a + b) / 2`.');
INSERT INTO `bh_hints` VALUES (697, 233, 1, 'This one crashes with a `RecursionError` - the function keeps calling itself and never stops.');
INSERT INTO `bh_hints` VALUES (698, 233, 2, 'Every recursive function needs a condition where it stops calling itself. Does this one have one?');
INSERT INTO `bh_hints` VALUES (699, 233, 3, 'Add a base case: if `n <= 1`, return `1` directly, before the recursive call.');
INSERT INTO `bh_hints` VALUES (700, 234, 1, 'This runs without errors, but the second line printed isn\'t what you\'d expect from \"start fresh each time\".');
INSERT INTO `bh_hints` VALUES (701, 234, 2, 'A default argument value is created only once, when the function is defined - not fresh on every call. What kind of default value could that cause problems for?');
INSERT INTO `bh_hints` VALUES (702, 234, 3, 'Use `basket=None` as the default, then create a new empty list inside the function if `basket is None`.');
INSERT INTO `bh_hints` VALUES (703, 235, 1, 'This runs fine, but check both printed lines - is the first one what you expected?');
INSERT INTO `bh_hints` VALUES (704, 235, 2, '`doubled = original` doesn\'t make a new list - it makes `doubled` another name for the exact same list.');
INSERT INTO `bh_hints` VALUES (705, 235, 3, 'Use `original.copy()` (or `list(original)`) to make a genuinely separate list.');
INSERT INTO `bh_hints` VALUES (706, 236, 1, 'Only one cell was changed in the code - but look at how many `1`s show up in the output.');
INSERT INTO `bh_hints` VALUES (707, 236, 2, '`[[0] * 3] * 3` repeats the *same inner list* three times, not three independent lists.');
INSERT INTO `bh_hints` VALUES (708, 236, 3, 'Use a list comprehension - `[[0] * 3 for _ in range(3)]` - to create three genuinely separate rows.');
INSERT INTO `bh_hints` VALUES (709, 237, 1, 'At least one test gets stopped for taking too long - the search bounds aren\'t narrowing down the way they should.');
INSERT INTO `bh_hints` VALUES (710, 237, 2, 'When the target is smaller or larger than the middle item, how much does `low` or `high` actually move? Could `mid` ever equal `low` or `high` again on the next pass?');
INSERT INTO `bh_hints` VALUES (711, 237, 3, 'Narrow the bounds past `mid`, not onto it: use `low = mid + 1` and `high = mid - 1`.');
INSERT INTO `bh_hints` VALUES (712, 238, 1, 'All three results come out the same - but they were created with three different values of `i`.');
INSERT INTO `bh_hints` VALUES (713, 238, 2, 'A lambda looks up `i` in its enclosing scope *when it\'s called*, not when it\'s created - and there\'s only one `i` variable, shared by the whole loop.');
INSERT INTO `bh_hints` VALUES (714, 238, 3, 'Give the lambda its own parameter with a default: `lambda i=i: i`, capturing the current value at creation time.');
INSERT INTO `bh_hints` VALUES (715, 239, 1, 'The second line printed is lower than the first - but a *high* score should never go down.');
INSERT INTO `bh_hints` VALUES (716, 239, 2, '`local_high` is a brand new local variable every call - does it actually update `high_score` for next time?');
INSERT INTO `bh_hints` VALUES (717, 239, 3, 'Declare `global high_score` inside the function, and update `high_score` directly instead of a local copy.');
INSERT INTO `bh_hints` VALUES (718, 240, 1, 'The second printed line is empty - but nothing was removed from `evens` on purpose.');
INSERT INTO `bh_hints` VALUES (719, 240, 2, 'A generator expression `(... for ...)` only produces its values once, in one pass. What happens once every value has been read?');
INSERT INTO `bh_hints` VALUES (720, 240, 3, 'Return a list comprehension `[...]` instead of a generator expression `(...)`, so it can be listed more than once.');
INSERT INTO `bh_hints` VALUES (721, 241, 1, 'The first test fails even though `0.7 + 0.2 + 0.1` really does equal 1 on paper.');
INSERT INTO `bh_hints` VALUES (722, 241, 2, 'Computers store decimal fractions like `0.1` approximately, in binary - try printing `0.7 + 0.2 + 0.1` directly and look closely at the result.');
INSERT INTO `bh_hints` VALUES (723, 241, 3, 'Use `math.isclose(a + b + c, 1.0)` instead of `==`.');
INSERT INTO `bh_hints` VALUES (724, 242, 1, 'This crashes with a `RuntimeError` about the dictionary changing size.');
INSERT INTO `bh_hints` VALUES (725, 242, 2, 'Python won\'t let you add or remove keys from a dictionary while you\'re directly looping over it. Can you loop over something else instead - a snapshot of the keys, perhaps?');
INSERT INTO `bh_hints` VALUES (726, 242, 3, 'Loop over `list(stock.keys())` instead of `stock` directly.');
INSERT INTO `bh_hints` VALUES (727, 243, 1, 'This returns the 3 *lowest* scorers instead of the 3 highest.');
INSERT INTO `bh_hints` VALUES (728, 243, 2, '`sorted()` arranges things smallest-to-largest by default. Does taking the first 3 of that give you the top, or the bottom?');
INSERT INTO `bh_hints` VALUES (729, 243, 3, 'Add `reverse=True` to `sorted(...)` so it goes largest-to-smallest.');
INSERT INTO `bh_hints` VALUES (730, 244, 1, 'This never crashes, but it also never seems to return the right answer - it just gives back `None` every time.');
INSERT INTO `bh_hints` VALUES (731, 244, 2, 'A bare `except:` catches *every* kind of error, including ones caused by ordinary typos elsewhere in the same `try` block. Is there a typo hiding in there?');
INSERT INTO `bh_hints` VALUES (732, 244, 3, 'There\'s a spelling mistake (`resutl` vs `result`) causing a `NameError` that the bare `except` is silently swallowing. Fix the typo, and prefer not catching errors you don\'t expect.');
INSERT INTO `bh_hints` VALUES (733, 245, 1, 'Two lists that clearly contain the same values still come back `False` - think about what\'s actually being checked.');
INSERT INTO `bh_hints` VALUES (734, 245, 2, '`is` checks whether two names point at the *exact same object* in memory, not whether their contents match.');
INSERT INTO `bh_hints` VALUES (735, 245, 3, 'Use `==` instead of `is` to compare contents.');
INSERT INTO `bh_hints` VALUES (736, 246, 1, 'Setting just `board[0][0]` seems to change more than one row - trace through what `[[0] * size] * size` actually builds.');
INSERT INTO `bh_hints` VALUES (737, 246, 2, '`[row] * size` repeats the *same* row object `size` times - it does not build `size` independent rows.');
INSERT INTO `bh_hints` VALUES (738, 246, 3, 'Use a list comprehension so each row is built separately: `[[0] * size for _ in range(size)]`.');
INSERT INTO `bh_hints` VALUES (739, 247, 1, 'Only the first player\'s score should have changed - check whether the others stayed empty.');
INSERT INTO `bh_hints` VALUES (740, 247, 2, '`dict.fromkeys(keys, value)` gives every key the exact same `value` object - for a mutable default like `[]`, that means one shared list, not one each.');
INSERT INTO `bh_hints` VALUES (741, 247, 3, 'Use a dict comprehension instead: `{p: [] for p in players}`, which builds a fresh list for every player.');
INSERT INTO `bh_hints` VALUES (742, 248, 1, 'Check the actual type of what this function returns - is it really a list?');
INSERT INTO `bh_hints` VALUES (743, 248, 2, '`.sort()` rearranges the list in place and gives back `None` - it is not meant to be reassigned to anything.');
INSERT INTO `bh_hints` VALUES (744, 248, 3, 'Call `names.sort()` on its own line, then `return names` separately.');
INSERT INTO `bh_hints` VALUES (745, 249, 1, 'Check the type of the return value - should it really be `None`?');
INSERT INTO `bh_hints` VALUES (746, 249, 2, '`.append()`, like `.sort()`, changes the list in place and returns `None`.');
INSERT INTO `bh_hints` VALUES (747, 249, 3, 'Call `items.append(value)` without reassigning it, then return `items` separately.');
INSERT INTO `bh_hints` VALUES (748, 250, 1, 'This is the same family of bug as `.sort()` and `.append()` - check what this method actually hands back.');
INSERT INTO `bh_hints` VALUES (749, 250, 2, '`.reverse()` flips the list in place and returns `None`.');
INSERT INTO `bh_hints` VALUES (750, 250, 3, 'Call `queue.reverse()` on its own line, then return `queue`.');
INSERT INTO `bh_hints` VALUES (751, 251, 1, '`second` was built from a call that only mentioned `\"b\"` - check whether `\"a\"` has snuck in anyway.');
INSERT INTO `bh_hints` VALUES (752, 251, 2, 'The default `log={}` is created once, the moment the function is defined - every call that relies on the default shares that exact same dictionary.');
INSERT INTO `bh_hints` VALUES (753, 251, 3, 'Default to `None`, and create a fresh `{}` inside the function only when no `log` was supplied.');
INSERT INTO `bh_hints` VALUES (754, 252, 1, 'This crashes the first time `counter()` is called - the error is about a local variable with no value yet.');
INSERT INTO `bh_hints` VALUES (755, 252, 2, '`count += 1` assigns to `count`, which makes Python treat it as a new local variable inside `increment` - not the `count` from the outer function.');
INSERT INTO `bh_hints` VALUES (756, 252, 3, 'Add `nonlocal count` as the first line of `increment`, telling Python to use the outer function\'s `count`.');
INSERT INTO `bh_hints` VALUES (757, 253, 1, 'Try it on an empty list first, on its own - what should the sum of nothing be?');
INSERT INTO `bh_hints` VALUES (758, 253, 2, 'The base case return value gets added in at the very end of the recursion, once for every call - a wrong base case throws the whole total off.');
INSERT INTO `bh_hints` VALUES (759, 253, 3, 'Change the base case to `return 0`.');
INSERT INTO `bh_hints` VALUES (760, 254, 1, 'Try it with lists of different lengths - does every name end up with an entry, even without a matching score?');
INSERT INTO `bh_hints` VALUES (761, 254, 2, '`zip()` stops as soon as the *shortest* input runs out - it silently drops whatever is left over in the longer one.');
INSERT INTO `bh_hints` VALUES (762, 254, 3, 'Use `itertools.zip_longest()` instead, which pads the shorter list with `None`.');
INSERT INTO `bh_hints` VALUES (763, 255, 1, 'Check the number attached to the very first item - should a \"1st item\" be labelled `0`?');
INSERT INTO `bh_hints` VALUES (764, 255, 2, '`enumerate()` counts from `0` by default, same as list indexing.');
INSERT INTO `bh_hints` VALUES (765, 255, 3, 'Pass `start=1` to `enumerate()`.');
INSERT INTO `bh_hints` VALUES (766, 256, 1, 'Try a list containing both `1` and `True` together - does the count treat them as one value or two?');
INSERT INTO `bh_hints` VALUES (767, 256, 2, 'In Python, `True == 1` and `hash(True) == hash(1)` - a `set` or `dict` genuinely cannot tell them apart on their own.');
INSERT INTO `bh_hints` VALUES (768, 256, 3, 'Track the *type* alongside the value, e.g. using `(type(x), x)` pairs, not just the value on its own.');
INSERT INTO `bh_hints` VALUES (769, 257, 1, 'Use a name that would sort alphabetically \"first\" but has a low score - does it end up ranked top anyway?');
INSERT INTO `bh_hints` VALUES (770, 257, 2, 'Sorting these pairs without a `key` compares them by their *first* item first (the name), only checking the score as a tie-break.');
INSERT INTO `bh_hints` VALUES (771, 257, 3, 'Add `key=lambda s: s[1]` to sort by the score specifically.');
INSERT INTO `bh_hints` VALUES (772, 258, 1, 'Try adding `0.1` to itself a few times by hand in the Playground and compare it to `0.1 * 3` with `==`.');
INSERT INTO `bh_hints` VALUES (773, 258, 2, 'Repeated floating-point addition can build up a tiny rounding error that an exact `==` never forgives.');
INSERT INTO `bh_hints` VALUES (774, 258, 3, 'Compare with `math.isclose(...)` instead of `==`.');
INSERT INTO `bh_hints` VALUES (775, 259, 1, 'This function changes `new_grid` and then checks `grid` - they are meant to be independent. Are they?');
INSERT INTO `bh_hints` VALUES (776, 259, 2, '`copy.copy()` only makes a shallow copy - it copies the outer list, but the *inner* lists inside it are still shared with the original.');
INSERT INTO `bh_hints` VALUES (777, 259, 3, 'Use `copy.deepcopy()` instead, which copies every level, not just the outer one.');
INSERT INTO `bh_hints` VALUES (778, 260, 1, 'Check the returned text carefully - are the spaces actually gone, and is it really title case?');
INSERT INTO `bh_hints` VALUES (779, 260, 2, 'Strings are immutable in Python - `.strip()` and `.title()` return a *new* string, they never change the original in place.');
INSERT INTO `bh_hints` VALUES (780, 260, 3, 'Reassign the result each time: `name = name.strip()` and `name = name.title()`.');
INSERT INTO `bh_hints` VALUES (781, 261, 1, 'Compare the order of the values returned by `compute_bmi` to the order they get unpacked into.');
INSERT INTO `bh_hints` VALUES (782, 261, 2, '`compute_bmi` returns `(height_m, weight_kg)` - height first - but the caller unpacks it as `weight, height = ...`, the opposite order.');
INSERT INTO `bh_hints` VALUES (783, 261, 3, 'Make `compute_bmi` return `weight_kg, height_m` in the same order the caller expects.');
INSERT INTO `bh_hints` VALUES (784, 262, 1, '`second` was built from `[5, 7]`, which has no even numbers at all - check whether anything from the first call has leaked in anyway.');
INSERT INTO `bh_hints` VALUES (785, 262, 2, '`result=[]` is a mutable default argument, just like the non-recursive version of this bug - it is created once and reused by every top-level call that relies on it.');
INSERT INTO `bh_hints` VALUES (786, 262, 3, 'Default `result` to `None`, and build a fresh `[]` inside the function when it is `None`.');
INSERT INTO `bh_hints` VALUES (787, 263, 1, 'Check the second part of the result - does it actually contain the even numbers?');
INSERT INTO `bh_hints` VALUES (788, 263, 2, 'A generator can only be stepped through once. The `sum(...)` already consumes every value in `evens`, leaving nothing for `list(evens)` afterwards.');
INSERT INTO `bh_hints` VALUES (789, 263, 3, 'Build a list comprehension once, then reuse that list for both the count and the result.');
INSERT INTO `bh_hints` VALUES (790, 264, 1, '`get_sorted` is meant to leave its argument untouched and hand back a sorted copy - check whether `original` really stays the same.');
INSERT INTO `bh_hints` VALUES (791, 264, 2, 'Inside `get_sorted`, `data` is the exact same list object as `original` - sorting `data` in place sorts `original` too.');
INSERT INTO `bh_hints` VALUES (792, 264, 3, 'Make `get_sorted` copy its argument first, before sorting the copy.');
INSERT INTO `bh_hints` VALUES (793, 265, 1, 'Mix capitalised and lowercase words together and sort them - does the order match what a dictionary would give you?');
INSERT INTO `bh_hints` VALUES (794, 265, 2, 'Python compares letters by their underlying code point, where every capital letter sorts before every lowercase one - `sorted()` has no built-in idea of \"ignore case\".');
INSERT INTO `bh_hints` VALUES (795, 265, 3, 'Sort using `key=str.lower` to compare lower-cased versions of each word.');
INSERT INTO `bh_hints` VALUES (796, 266, 1, 'Only `team_a` was appended to - check whether `team_b` really stayed empty.');
INSERT INTO `bh_hints` VALUES (797, 266, 2, '`team_a = team_b = []` does not create two separate empty lists - it creates *one* list and gives it two names.');
INSERT INTO `bh_hints` VALUES (798, 266, 3, 'Create them on separate lines: `team_a = []` then `team_b = []`.');
INSERT INTO `bh_hints` VALUES (799, 267, 1, 'The variable is named `copy_of_list` - check whether it actually behaves like an independent copy.');
INSERT INTO `bh_hints` VALUES (800, 267, 2, '`copy_of_list = original` makes `copy_of_list` just another name for the exact same list - it copies nothing.');
INSERT INTO `bh_hints` VALUES (801, 267, 3, 'Use a full slice, `original[:]`, to actually build a new list with the same contents.');
INSERT INTO `bh_hints` VALUES (802, 268, 1, 'The second call only passes in `[10, 10, 10]` - should anything from the first call still be hanging around?');
INSERT INTO `bh_hints` VALUES (803, 268, 2, '`global running_total` makes every call add onto the *same* module-level variable, rather than starting fresh each time.');
INSERT INTO `bh_hints` VALUES (804, 268, 3, 'Use a local variable (`total = 0` inside the function) instead of a shared global one.');
INSERT INTO `bh_hints` VALUES (805, 269, 1, 'The key in `prices` is written as exactly `0.3` - is the weight you built by adding `0.1` three times actually equal to that, bit for bit?');
INSERT INTO `bh_hints` VALUES (806, 269, 2, 'Dictionary lookup uses exact equality - a weight built from repeated floating-point addition might be something like `0.30000000000000004`, not precisely `0.3`.');
INSERT INTO `bh_hints` VALUES (807, 269, 3, 'Search through the dictionary comparing keys with `math.isclose()` instead of using exact dictionary lookup.');
INSERT INTO `bh_hints` VALUES (808, 270, 1, 'Try a list with no even numbers in it at all - what should come back, and does it?');
INSERT INTO `bh_hints` VALUES (809, 270, 2, '`result` is never given a starting value before the loop - it only exists if the loop actually assigns to it at least once.');
INSERT INTO `bh_hints` VALUES (810, 270, 3, 'Set `result = default` before the loop starts.');
INSERT INTO `bh_hints` VALUES (811, 271, 1, 'This actually crashes - check what kind of thing `for item in inventory:` actually gives you each time round.');
INSERT INTO `bh_hints` VALUES (812, 271, 2, 'Looping directly over a dictionary gives you its *keys* (the item names), not its values (the quantities) - and adding a string to a number crashes.');
INSERT INTO `bh_hints` VALUES (813, 271, 3, 'Loop over `inventory.values()` instead of `inventory` directly.');
INSERT INTO `bh_hints` VALUES (814, 272, 1, 'Work out `factorial(4)` by hand, step by step, following exactly what the recursion does at `n == 0`.');
INSERT INTO `bh_hints` VALUES (815, 272, 2, 'Every recursive call eventually multiplies by whatever the base case returns - what happens when you multiply a chain of numbers by `0` at the very end?');
INSERT INTO `bh_hints` VALUES (816, 272, 3, 'Change the base case to `return 1`, the identity value for multiplication.');
INSERT INTO `bh_hints` VALUES (817, 273, 1, 'The change was made to `backup`, not `records` - check whether `records` really stayed the same.');
INSERT INTO `bh_hints` VALUES (818, 273, 2, '`.copy()` on a dictionary is a *shallow* copy - the list values inside it are still shared with the original dictionary.');
INSERT INTO `bh_hints` VALUES (819, 273, 3, 'Use `copy.deepcopy()` instead of `.copy()` so the list values are independent too.');
INSERT INTO `bh_hints` VALUES (820, 274, 1, 'A score of exactly `0` is a real, recorded score - does this function treat it that way?');
INSERT INTO `bh_hints` VALUES (821, 274, 2, '`not score` is `True` for `None`, but it is *also* `True` for `0` - both count as \"falsy\" in Python, even though only one of them means \"no value\".');
INSERT INTO `bh_hints` VALUES (822, 274, 3, 'Check specifically `if score is None:` instead of the general `if not score:`.');
INSERT INTO `bh_hints` VALUES (823, 275, 1, 'Check the length of the name this actually returns - is it really the shortest one?');
INSERT INTO `bh_hints` VALUES (824, 275, 2, 'Without a `key`, `min()` compares strings alphabetically (by their first differing letter), not by length.');
INSERT INTO `bh_hints` VALUES (825, 275, 3, 'Pass `key=len` so `min()` compares by length instead.');
INSERT INTO `bh_hints` VALUES (826, 276, 1, 'Try scores that land exactly on 50 or 70, and try an empty list - does the brief\'s boundary wording match what the code actually does?');
INSERT INTO `bh_hints` VALUES (827, 276, 2, 'There are two separate problems here: what happens with no scores at all, and what happens exactly on a grade boundary.');
INSERT INTO `bh_hints` VALUES (828, 276, 3, 'Guard against an empty list before dividing, and use `>=` instead of `>` so a score exactly on the boundary gets the higher grade.');
INSERT INTO `bh_hints` VALUES (829, 277, 1, 'Simple shifts work, but try shifting a letter near the end of the alphabet, and try text with spaces or punctuation in it.');
INSERT INTO `bh_hints` VALUES (830, 277, 2, 'There are two separate problems: what happens when the shift goes past \'z\', and what happens to characters that aren\'t letters at all.');
INSERT INTO `bh_hints` VALUES (831, 277, 3, 'Use the alphabet position (`ord(ch) - ord(\'a\')`), apply `% 26` to wrap around, then add `ord(\'a\')` back - and leave non-letters untouched with an `else` branch.');
INSERT INTO `bh_hints` VALUES (832, 278, 1, 'Row and column wins work, but try a board where only a diagonal has three in a row, and try a completely full board with no winner.');
INSERT INTO `bh_hints` VALUES (833, 278, 2, 'How many different ways can three-in-a-row happen on this board? Rows and columns are checked - is that the complete list?');
INSERT INTO `bh_hints` VALUES (834, 278, 3, 'Add checks for both diagonals, and after checking every line, check whether the board is completely full to detect a draw.');
INSERT INTO `bh_hints` VALUES (835, 279, 1, 'Withdraw from one account, then check the *other* account\'s transaction list - should it really have changed?');
INSERT INTO `bh_hints` VALUES (836, 279, 2, '`transactions = []` is defined directly under `class Account:`, not inside `__init__`. What\'s the difference between a class attribute and an instance attribute?');
INSERT INTO `bh_hints` VALUES (837, 279, 3, 'Move `transactions = []` inside `__init__` as `self.transactions = []`, and add a balance check inside `withdraw` before subtracting.');
INSERT INTO `bh_hints` VALUES (838, 280, 1, 'Place one order for 3 apples when there are 10 - how many are left afterwards? Also try ordering something that isn\'t in stock at all.');
INSERT INTO `bh_hints` VALUES (839, 280, 2, 'Look very closely at the two lines that update `stock[item]` - are they actually different from each other?');
INSERT INTO `bh_hints` VALUES (840, 280, 3, 'Remove the duplicate `stock[item] -= qty` line, and add a check to skip (or `continue`) when `item` isn\'t in `stock`.');
INSERT INTO `bh_hints` VALUES (841, 281, 1, 'Try `primes_up_to(2)` specifically - 2 is prime, so should it be included? Also check whether `1` ever shows up in a result list.');
INSERT INTO `bh_hints` VALUES (842, 281, 2, 'The list is sized `n`, and the loop runs `range(2, n)` - does either of those actually reach `n` itself? Also, is `1` ever explicitly marked as not prime?');
INSERT INTO `bh_hints` VALUES (843, 281, 3, 'Size the list `n + 1` and loop up to `n + 1` so `n` itself is included, and explicitly set `is_prime[1] = False` as well as `is_prime[0]`.');
INSERT INTO `bh_hints` VALUES (844, 282, 1, 'Try a list that\'s already partly or fully sorted descending - does the result come out the right *length*?');
INSERT INTO `bh_hints` VALUES (845, 282, 2, 'The main merging loop stops as soon as *either* `left` or `right` runs out - but what about whatever is left over in the other one?');
INSERT INTO `bh_hints` VALUES (846, 282, 3, 'After the `while` loop, add the leftover tail of each half: `merged.extend(left[i:])` and `merged.extend(right[j:])`.');
INSERT INTO `bh_hints` VALUES (847, 283, 1, 'With more than one item, the result only ever has one item in it, no matter how long the input list was.');
INSERT INTO `bh_hints` VALUES (848, 283, 2, 'Inside the loop, `current.next` is changed *before* it\'s used to move `current` forward. What does `current.next` point to by the time that line runs?');
INSERT INTO `bh_hints` VALUES (849, 283, 3, 'Save `current.next` in a temporary variable *before* overwriting it, then use that saved value to advance `current`.');
INSERT INTO `bh_hints` VALUES (850, 284, 1, 'Try text with punctuation stuck to a word, and also try an empty string - one of these crashes, the other just gives a misleading number.');
INSERT INTO `bh_hints` VALUES (851, 284, 2, 'Does `\"world!\"` count as 6 characters long, or 5? And what does `len(words)` equal for an empty string, once split?');
INSERT INTO `bh_hints` VALUES (852, 284, 3, 'Strip punctuation off each word before measuring its length, and return early with zeros when there are no words at all.');
INSERT INTO `bh_hints` VALUES (853, 285, 1, 'Try a simple case by hand: ┬ú30 total with a 10% discount should come to ┬ú27. Does it?');
INSERT INTO `bh_hints` VALUES (854, 285, 2, 'A percentage discount should be the total *multiplied by* the percentage, not the total *minus* the raw percentage number.');
INSERT INTO `bh_hints` VALUES (855, 285, 3, 'Change `discount = total - discount_percent / 100` to `discount = total * (discount_percent / 100)`.');
INSERT INTO `bh_hints` VALUES (856, 286, 1, 'Two separate things are wrong here: check `is_solved` on its own first, then check the order of operations in `play_round`.');
INSERT INTO `bh_hints` VALUES (857, 286, 2, '`is_solved` returns `True` the moment it finds an *unguessed* letter - that is backwards. Separately, `play_round` works out the result *before* recording the new guess.');
INSERT INTO `bh_hints` VALUES (858, 286, 3, 'Swap `is_solved`\'s two return values, and move `guessed_letters.append(new_guess)` to before the other two lines in `play_round`.');
INSERT INTO `bh_hints` VALUES (859, 287, 1, 'This won\'t even run - fix the crash first, then check the game rules themselves are actually correct.');
INSERT INTO `bh_hints` VALUES (860, 287, 2, '`if p1 = p2` needs a comparison, not an assignment. Separately, check the list of winning pairs against the real rules of the game.');
INSERT INTO `bh_hints` VALUES (861, 287, 3, 'Change `=` to `==`, and change `(\"paper\", \"scissors\")` to `(\"paper\", \"rock\")` in the winning pairs.');
INSERT INTO `bh_hints` VALUES (862, 288, 1, 'Dice go from 1 to 6 - check the range used to set up the counts dictionary.');
INSERT INTO `bh_hints` VALUES (863, 288, 2, '`range(1, 6)` stops before `6`, so there is no entry for rolling a `6` at all - and a dictionary with no `6` key will crash when a `6` is rolled.');
INSERT INTO `bh_hints` VALUES (864, 288, 3, 'Change `range(1, 6)` to `range(1, 7)` so every face from 1 to 6 gets an entry.');
INSERT INTO `bh_hints` VALUES (865, 289, 1, 'Try answers that are correct but typed in a different letter-case - do they count?');
INSERT INTO `bh_hints` VALUES (866, 289, 2, 'The brief says the comparison should ignore case, but `==` compares text exactly as written.');
INSERT INTO `bh_hints` VALUES (867, 289, 3, 'Lower-case both sides before comparing: `answers[i].lower() == correct_answers[i].lower()`.');
INSERT INTO `bh_hints` VALUES (868, 290, 1, 'Try a word that only appears once in the whole text - does it show up in the final dictionary at all?');
INSERT INTO `bh_hints` VALUES (869, 290, 2, 'The code only ever *increments* an existing count - there is no branch for the first time a word is seen.');
INSERT INTO `bh_hints` VALUES (870, 290, 3, 'Add an `else: counts[word] = 1` for the first time a word appears.');
INSERT INTO `bh_hints` VALUES (871, 291, 1, 'Check the average itself first - try a student with two different scores and see if the average makes sense at all.');
INSERT INTO `bh_hints` VALUES (872, 291, 2, '`average` only ever *replaces* `total` with the latest score instead of adding to it. Separately, check the boundary for \"50 or above\" in `pass_or_fail`.');
INSERT INTO `bh_hints` VALUES (873, 291, 3, 'Change `total = s` to `total += s`, and change `avg > 50` to `avg >= 50`.');
INSERT INTO `bh_hints` VALUES (874, 292, 1, 'This won\'t run at all - check the block headers before worrying about the conversion formula.');
INSERT INTO `bh_hints` VALUES (875, 292, 2, 'The `for` loop is missing something every block header needs.');
INSERT INTO `bh_hints` VALUES (876, 292, 3, 'Add a colon `:` after `for t in temps`.');
INSERT INTO `bh_hints` VALUES (877, 293, 1, 'Check what this returns when there are two matching books - should it be a list, or just one title?');
INSERT INTO `bh_hints` VALUES (878, 293, 2, 'The function returns `title` (singular, whatever is left over from the loop) instead of `titles` (the list being built). Separately, check whether the author comparison matches on case.');
INSERT INTO `bh_hints` VALUES (879, 293, 3, 'Return `titles`, and lower-case both sides of the author comparison.');
INSERT INTO `bh_hints` VALUES (880, 294, 1, 'The returned playlist order is actually fine - the bug is about what else gets changed as a side effect.');
INSERT INTO `bh_hints` VALUES (881, 294, 2, '`playlist.remove(...)` and `.insert(...)` both mutate the list in place - and `playlist` here is the exact same list object the caller passed in.');
INSERT INTO `bh_hints` VALUES (882, 294, 3, 'Make a copy first - `new_playlist = playlist.copy()` - and mutate that instead of `playlist` directly.');
INSERT INTO `bh_hints` VALUES (883, 295, 1, 'Try two contacts with the same email but different capitalisation - are they treated as duplicates?');
INSERT INTO `bh_hints` VALUES (884, 295, 2, 'Membership checks and list appends here compare the email exactly as written, with no case normalisation.');
INSERT INTO `bh_hints` VALUES (885, 295, 3, 'Lower-case the email both when checking `seen_emails` and when adding to it.');
INSERT INTO `bh_hints` VALUES (886, 296, 1, 'Try a palindrome that mixes upper and lower case, like \"Noon\" - does it get recognised?');
INSERT INTO `bh_hints` VALUES (887, 296, 2, '`clean` removes spaces but never changes the letter case, even though the brief says to ignore case.');
INSERT INTO `bh_hints` VALUES (888, 296, 3, 'Lower-case each character as it is added: `result + ch.lower()`.');
INSERT INTO `bh_hints` VALUES (889, 297, 1, 'This crashes - look at exactly what `len(words - 1)` is trying to do.');
INSERT INTO `bh_hints` VALUES (890, 297, 2, '`words` is a list - you cannot subtract a number from a list. The count should just be the length of the list itself.');
INSERT INTO `bh_hints` VALUES (891, 297, 3, 'Change `len(words - 1)` to `len(words)`.');
INSERT INTO `bh_hints` VALUES (892, 298, 1, 'Try a string with a space or a digit in it - does everything before it survive in the output?');
INSERT INTO `bh_hints` VALUES (893, 298, 2, 'The `else` branch for non-letters uses `=` instead of `+=` - it replaces the whole result instead of adding to it.');
INSERT INTO `bh_hints` VALUES (894, 298, 3, 'Change `result = ch` to `result += ch` in the `else` branch.');
INSERT INTO `bh_hints` VALUES (895, 299, 1, 'Try filling in a placeholder whose value is a number, like `age` here - does it crash?');
INSERT INTO `bh_hints` VALUES (896, 299, 2, '`.replace()` needs both its arguments to be strings - a dictionary value that is a number will not work directly.');
INSERT INTO `bh_hints` VALUES (897, 299, 3, 'Convert the value to a string first: `str(values[key])`.');
INSERT INTO `bh_hints` VALUES (898, 300, 1, 'The sorting algorithm itself works correctly - the bug is about what else gets changed along the way.');
INSERT INTO `bh_hints` VALUES (899, 300, 2, '`result = numbers` does not copy the list - `result` and `numbers` are the same object, so sorting \"result\" in place also rearranges the caller\'s original list.');
INSERT INTO `bh_hints` VALUES (900, 300, 3, 'Use `numbers.copy()` to create an independent list before sorting it.');
INSERT INTO `bh_hints` VALUES (901, 301, 1, 'Search for a value that is found on the third try - does the comparison count come out as 3?');
INSERT INTO `bh_hints` VALUES (902, 301, 2, '`comparisons` is only increased inside the `if items[i] == target:` branch, so items that were checked and did *not* match never get counted.');
INSERT INTO `bh_hints` VALUES (903, 301, 3, 'Move `comparisons = comparisons + 1` so it runs on every loop iteration, before the `if` check.');
INSERT INTO `bh_hints` VALUES (904, 302, 1, 'Push three items, then pop once - which item is actually removed, the top or the bottom?');
INSERT INTO `bh_hints` VALUES (905, 302, 2, 'A stack pops from the *top* (the end of the list), but `.pop(0)` removes from the *front*. Separately, check what happens when popping an empty stack.');
INSERT INTO `bh_hints` VALUES (906, 302, 3, 'Change `stack.pop(0)` to `stack.pop()`, and check `if stack:` before popping.');
INSERT INTO `bh_hints` VALUES (907, 303, 1, 'Try calling this on an empty queue - what happens?');
INSERT INTO `bh_hints` VALUES (908, 303, 2, 'There is nothing at position 0 of an empty list to remove.');
INSERT INTO `bh_hints` VALUES (909, 303, 3, 'Check `if not queue:` first and return `None` in that case.');
INSERT INTO `bh_hints` VALUES (910, 304, 1, 'Work out the LCM formula by hand for `gcd_and_lcm(12, 18)` and compare it to what the code actually computes.');
INSERT INTO `bh_hints` VALUES (911, 304, 2, 'The LCM formula is `a * b // gcd`, but the code uses `a + b` instead of `a * b`.');
INSERT INTO `bh_hints` VALUES (912, 304, 3, 'Change `(a + b) // g` to `a * b // g`.');
INSERT INTO `bh_hints` VALUES (913, 305, 1, 'The Fibonacci sequence is supposed to start `0, 1, 1, 2, 3, ...` - check what the very first number in the result actually is.');
INSERT INTO `bh_hints` VALUES (914, 305, 2, 'The sequence is seeded as `[1, 1]` instead of `[0, 1]` - every value comes out one step further along the real sequence than it should.');
INSERT INTO `bh_hints` VALUES (915, 305, 3, 'Change the starting seed to `[0, 1]`.');
INSERT INTO `bh_hints` VALUES (916, 306, 1, 'Guess a number clearly too high, and check the message that comes back matches.');
INSERT INTO `bh_hints` VALUES (917, 306, 2, 'The two messages are swapped between the branches that detect them.');
INSERT INTO `bh_hints` VALUES (918, 306, 3, 'Swap `\"Too low\"` and `\"Too high\"` between the two branches.');
INSERT INTO `bh_hints` VALUES (919, 307, 1, 'Try a matrix with more than one row that actually differ, like `[[1, 2], [3, 4]]` - does every value end up in the right place?');
INSERT INTO `bh_hints` VALUES (920, 307, 2, '`[[0] * rows] * cols` builds `cols` references to the *same* inner list, not independent rows.');
INSERT INTO `bh_hints` VALUES (921, 307, 3, 'Build the rows with a list comprehension: `[[0] * rows for _ in range(cols)]`.');
INSERT INTO `bh_hints` VALUES (922, 308, 1, 'Check the very last character of the input - does it show up in the result at all?');
INSERT INTO `bh_hints` VALUES (923, 308, 2, 'The current run only ever gets added to `result` when a *different* character is found - the final run never has a \"different character\" after it to trigger that.');
INSERT INTO `bh_hints` VALUES (924, 308, 3, 'After the loop finishes, append the final `[current, count]` pair once more.');
INSERT INTO `bh_hints` VALUES (925, 309, 1, 'Try converting a large cm value into km - does the result actually get smaller, as converting to a bigger unit should?');
INSERT INTO `bh_hints` VALUES (926, 309, 2, '`from_cm` converts cm into metres by *dividing*, but into km by *multiplying* - only one of those directions is correct.');
INSERT INTO `bh_hints` VALUES (927, 309, 3, 'Change `value * 100000` to `value / 100000` in the km branch of `from_cm`.');
INSERT INTO `bh_hints` VALUES (928, 310, 1, 'Each test here calls `calculate` completely fresh, with no history passed in - should any of them see results from a different call?');
INSERT INTO `bh_hints` VALUES (929, 310, 2, '`history=[]` is a mutable default argument - it is created once and shared by every call that does not supply its own.');
INSERT INTO `bh_hints` VALUES (930, 310, 3, 'Default `history` to `None`, and create a fresh `[]` inside the function when needed.');
INSERT INTO `bh_hints` VALUES (931, 311, 1, 'Try a list with two tasks that happen to share the same name - does completing one by name complete both?');
INSERT INTO `bh_hints` VALUES (932, 311, 2, 'Returning immediately inside the loop, the moment one match is found, stops the loop from checking the rest of the list.');
INSERT INTO `bh_hints` VALUES (933, 311, 3, 'Remove the early `return tasks` inside the loop - let it keep checking every task, and return once at the end.');
INSERT INTO `bh_hints` VALUES (934, 312, 1, 'Trigger both validation problems at once - does the result mention both of them?');
INSERT INTO `bh_hints` VALUES (935, 312, 2, 'The age check uses `errors = [...]`, which replaces the entire list - including whatever the username check already added.');
INSERT INTO `bh_hints` VALUES (936, 312, 3, 'Change `errors = [\"Must be 13 or older\"]` to `errors.append(\"Must be 13 or older\")`.');
INSERT INTO `bh_hints` VALUES (937, 313, 1, 'This sorts something, but check exactly what it is sorting by - names, or scores?');
INSERT INTO `bh_hints` VALUES (938, 313, 2, '`names.sort()` with no `key` sorts the names alphabetically, completely ignoring the actual scores.');
INSERT INTO `bh_hints` VALUES (939, 313, 3, 'Sort using `key=lambda name: scores[name], reverse=True` to sort by score, highest first.');
INSERT INTO `bh_hints` VALUES (940, 314, 1, 'Try two words that really are anagrams, like \"listen\" and \"silent\" - do they get recognised?');
INSERT INTO `bh_hints` VALUES (941, 314, 2, 'Comparing the cleaned text directly with `==` checks whether the letters are in the *same order*, not whether they are the same letters rearranged.');
INSERT INTO `bh_hints` VALUES (942, 314, 3, 'Sort the letters of both before comparing: `sorted(a) == sorted(b)`.');
INSERT INTO `bh_hints` VALUES (943, 315, 1, 'Check what exactly gets returned - is it the running balance, or just the amount from the very last transaction?');
INSERT INTO `bh_hints` VALUES (944, 315, 2, '`return amount` returns the loop variable from the last transaction processed, not the actual running `balance`.');
INSERT INTO `bh_hints` VALUES (945, 315, 3, 'Return `balance` instead of `amount`.');
