INSERT INTO `bh_puzzle_bugs` VALUES (125, 111, 1, 1, 1, 'syntax', 80, 'The `def` line has no colon, so Python can\'t tell where the function\'s body is supposed to start.', 'Add `:` after the closing parenthesis: `def is_even(n):`.');
INSERT INTO `bh_puzzle_bugs` VALUES (126, 112, 1, 2, 2, 'syntax', 78, 'The `print(` call is never closed with a matching `)`.', 'Add `)` at the end of the line.');
INSERT INTO `bh_puzzle_bugs` VALUES (127, 113, 1, 1, 1, 'syntax', 79, 'The string is opened with `\"` but never closed, so Python keeps reading past the end of the line looking for the matching quote.', 'Add the missing closing `\"` before the final `)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (128, 114, 1, 2, 2, 'syntax', 81, 'The function body isn\'t indented, so Python doesn\'t recognise it as belonging to `double`.', 'Indent line 2 by 4 spaces.');
INSERT INTO `bh_puzzle_bugs` VALUES (129, 115, 1, 3, 4, 'syntax', 81, 'Line 3 is indented with a tab while line 4 (meant to be at the same level) uses spaces - Python can\'t be sure they line up.', 'Re-indent both lines using spaces only.');
INSERT INTO `bh_puzzle_bugs` VALUES (130, 116, 1, 2, 2, 'runtime', 82, 'Python is case-sensitive, so `Print` is a completely different, undefined name from the built-in `print`.', 'Use lowercase `print`.');
INSERT INTO `bh_puzzle_bugs` VALUES (131, 117, 1, 2, 2, 'syntax', 83, '`=` assigns a value; `==` compares two values. An `if` condition needs a comparison.', 'Change `if x = 5:` to `if x == 5:`.');
INSERT INTO `bh_puzzle_bugs` VALUES (132, 118, 1, 4, 4, 'syntax', 84, '`elseif` isn\'t a Python keyword - Python\'s word for this is `elif`.', 'Change `elseif` to `elif`.');
INSERT INTO `bh_puzzle_bugs` VALUES (133, 119, 1, 2, 2, 'runtime', 85, 'Square brackets `[]` are for indexing; round brackets `()` call a function or method. `.upper` is a method, so it needs `()`.', 'Change `[]` to `()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (134, 120, 1, 1, 1, 'syntax', 86, 'The function\'s parameters need to be inside parentheses - `def square n:` is missing them.', 'Change `def square n:` to `def square(n):`.');
INSERT INTO `bh_puzzle_bugs` VALUES (135, 121, 1, 2, 2, 'syntax', 80, 'The `if` line has no colon at the end.', 'Add `:` after the condition.');
INSERT INTO `bh_puzzle_bugs` VALUES (136, 122, 1, 2, 2, 'syntax', 80, 'The `for` line has no colon.', 'Add `:` at the end of the `for` line.');
INSERT INTO `bh_puzzle_bugs` VALUES (137, 123, 1, 2, 2, 'syntax', 80, 'The `while` line has no colon.', 'Add `:` at the end of the `while` line.');
INSERT INTO `bh_puzzle_bugs` VALUES (138, 124, 1, 1, 1, 'syntax', 80, 'The `class` line has no colon.', 'Add `:` after `class Dog`.');
INSERT INTO `bh_puzzle_bugs` VALUES (139, 125, 1, 4, 4, 'syntax', 80, 'The `except` line has no colon.', 'Add `:` after `ZeroDivisionError`.');
INSERT INTO `bh_puzzle_bugs` VALUES (140, 126, 1, 1, 1, 'syntax', 78, 'The list literal `[10, 20, 30` is never closed.', 'Add `]` after `30`.');
INSERT INTO `bh_puzzle_bugs` VALUES (141, 127, 1, 1, 1, 'syntax', 78, 'The dictionary literal is opened with `{` but never closed.', 'Add `}` after the last entry.');
INSERT INTO `bh_puzzle_bugs` VALUES (142, 128, 1, 1, 1, 'syntax', 85, 'The value opens with `(` but closes with `]` - the two bracket types have to match.', 'Change `]` to `)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (143, 129, 1, 1, 2, 'syntax', 79, 'The triple-quoted string is opened with `\"\"\"` but never closed.', 'Add the closing `\"\"\"` after \"to the game\".');
INSERT INTO `bh_puzzle_bugs` VALUES (144, 130, 1, 2, 2, 'syntax', 117, 'The `{name` inside the f-string is never closed with `}`.', 'Add `}` after `name`.');
INSERT INTO `bh_puzzle_bugs` VALUES (145, 131, 1, 3, 3, 'syntax', 83, 'A single `=` assigns; a `while` condition needs `==` to compare.', 'Change `=` to `==`.');
INSERT INTO `bh_puzzle_bugs` VALUES (146, 132, 1, 1, 1, 'syntax', 86, 'A parameter without a default (`name`) comes after one with a default (`greeting=\"Hello\"`) - Python requires defaults to come last.', 'Reorder the parameters so `name` comes before `greeting=\"Hello\"`.');
INSERT INTO `bh_puzzle_bugs` VALUES (147, 133, 1, 1, 1, 'syntax', 118, 'Dictionary entries pair a key and value with `:`, not `=`.', 'Change `\"apple\" = 1` to `\"apple\": 1` (and the same for `\"pear\"`).');
INSERT INTO `bh_puzzle_bugs` VALUES (148, 134, 1, 1, 2, 'syntax', 84, '`class` is one of Python\'s reserved keywords, so it cannot be used as a variable name.', 'Use a different name, e.g. `class_name`.');
INSERT INTO `bh_puzzle_bugs` VALUES (149, 135, 1, 5, 5, 'syntax', 81, 'The `else:` header is correctly indented, but its body isn\'t indented any further than it.', 'Indent the body line so it sits one level inside `else:`.');
INSERT INTO `bh_puzzle_bugs` VALUES (150, 136, 1, 2, 2, 'syntax', 119, 'A `for` loop needs the shape `for item in iterable:` - the `in` keyword is missing here.', 'Add `in` between `i` and `range(5)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (151, 137, 1, 4, 4, 'syntax', 120, '`except Error, name:` is old Python 2 syntax - Python 3 uses `except Error as name:`.', 'Change the comma to `as`.');
INSERT INTO `bh_puzzle_bugs` VALUES (152, 138, 1, 1, 1, 'syntax', 79, 'The backslash immediately before the closing `\"` escapes that quote mark instead of ending the string, so the string never actually closes.', 'Write it as a raw string, `r\"...\"`, so backslashes are treated literally.');
INSERT INTO `bh_puzzle_bugs` VALUES (153, 139, 1, 3, 3, 'syntax', 122, '`return \"done\"` sits outside `greet` (it isn\'t indented), but `return` is only valid inside a function.', 'Indent that line so it belongs to `greet`.');
INSERT INTO `bh_puzzle_bugs` VALUES (154, 140, 1, 4, 4, 'syntax', 122, '`break` sits outside the `for` loop (same indentation as `for` itself), but `break` is only valid inside a loop.', 'Remove the stray `break` line.');
INSERT INTO `bh_puzzle_bugs` VALUES (155, 141, 1, 1, 2, 'syntax', 121, 'Python reads `student-count` as `student - count` (subtraction), not as one name - hyphens are not allowed in identifiers.', 'Use an underscore instead: `student_count`.');
INSERT INTO `bh_puzzle_bugs` VALUES (156, 142, 1, 1, 2, 'syntax', 121, 'A name cannot start with a digit - Python reads `2nd_place` as starting with the number `2`, which is invalid.', 'Rename it to start with a letter, e.g. `second_place`.');
INSERT INTO `bh_puzzle_bugs` VALUES (157, 143, 1, 1, 1, 'syntax', 78, 'There is one more closing `)` than there are opening `(` on this line.', 'Remove the extra `)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (158, 144, 1, 1, 1, 'syntax', 125, 'A `lambda` needs a colon between its parameters and its expression - `lambda x x * x` is missing it.', 'Add `:` after the parameter: `lambda x: x * x`.');
INSERT INTO `bh_puzzle_bugs` VALUES (159, 145, 1, 1, 2, 'syntax', 126, 'Line 1 ends with `+`, leaving the expression unfinished, and nothing tells Python the next line continues it.', 'Wrap the whole expression in parentheses so it can span multiple lines safely.');
INSERT INTO `bh_puzzle_bugs` VALUES (160, 146, 1, 4, 4, 'syntax', 123, '`global` only declares that a name refers to the module-level variable - it cannot also assign a value on the same line.', 'Write `global counter` on its own line, then assign to it on the next.');
INSERT INTO `bh_puzzle_bugs` VALUES (161, 147, 1, 1, 1, 'syntax', 124, '`print` is a function in current Python, so calling it needs parentheses - this is the old Python 2 statement form.', 'Add parentheses: `print(\"Game over\")`.');
INSERT INTO `bh_puzzle_bugs` VALUES (162, 148, 1, 4, 4, 'syntax', 80, 'The `elif` line has no colon.', 'Add `:` after the condition.');
INSERT INTO `bh_puzzle_bugs` VALUES (163, 149, 1, 2, 2, 'syntax', 117, 'The f-string is opened with `\"` but never closed, even though its `{}` is fine.', 'Add the closing `\"` after `{name}`.');
INSERT INTO `bh_puzzle_bugs` VALUES (164, 150, 1, 1, 2, 'syntax', 79, 'The string opens with `\'\'\'` but the line that was meant to close it uses `\"\"\"` instead - a different quote type, so it doesn\'t match.', 'Change the closing quotes to `\'\'\'`, matching the opening.');
INSERT INTO `bh_puzzle_bugs` VALUES (165, 151, 1, 2, 2, 'runtime', 87, '`nmae` is never defined - it\'s a typo for the parameter `name`, so Python raises a `NameError` the moment this line runs.', 'Change `nmae` to `name`.');
INSERT INTO `bh_puzzle_bugs` VALUES (166, 152, 1, 2, 2, 'runtime', 88, '`+` between a string and an `int` is not allowed - `age` needs converting to a string first.', 'Use `str(age)` instead of `age`.');
INSERT INTO `bh_puzzle_bugs` VALUES (167, 153, 1, 2, 2, 'runtime', 89, 'Valid indexes run from `0` to `len(items) - 1`. `items[len(items)]` is one position past the last real item.', 'Subtract 1: `items[len(items) - 1]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (168, 154, 1, 3, 3, 'runtime', 90, '`colours[fruit]` crashes if `fruit` isn\'t a key already in the dictionary.', 'Use `.get(fruit, \"unknown\")` to supply a default instead of crashing.');
INSERT INTO `bh_puzzle_bugs` VALUES (169, 155, 1, 2, 2, 'runtime', 91, 'If `nums` is empty, `len(nums)` is `0` and the division crashes.', 'Guard against an empty list before dividing.');
INSERT INTO `bh_puzzle_bugs` VALUES (170, 156, 1, 2, 2, 'runtime', 88, '`int(\"3.5\")` crashes - `int()` only accepts text that looks like a whole number.', 'Convert with `int(float(text))` so a decimal point is handled first.');
INSERT INTO `bh_puzzle_bugs` VALUES (171, 157, 1, 2, 2, 'runtime', 93, 'The function computes `total` but never returns it, so it implicitly returns `None`.', 'Add `return total`.');
INSERT INTO `bh_puzzle_bugs` VALUES (172, 158, 1, 4, 4, 'runtime', 87, 'Assigning to `count` inside the function makes Python treat it as a local variable throughout the function - including on the right-hand side, before it\'s been given a local value.', 'Add `global count` before using it.');
INSERT INTO `bh_puzzle_bugs` VALUES (173, 159, 1, 2, 2, 'runtime', 88, '`price_text` is a string, so `price_text * quantity` repeats the text rather than multiplying a number, and adding `5` to that then crashes.', 'Convert with `int(price_text)` first.');
INSERT INTO `bh_puzzle_bugs` VALUES (174, 160, 1, 1, 2, 'runtime', 94, 'The function only accepts one parameter, but the brief (and the tests) need two.', 'Add `last_name` as a second parameter and include it in the returned greeting.');
INSERT INTO `bh_puzzle_bugs` VALUES (175, 161, 1, 2, 2, 'runtime', 105, '`.uppercase()` is not a real string method - the correct one is `.upper()`.', 'Change it to `.upper()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (176, 162, 1, 1, 3, 'runtime', 93, '`get_name` has no `return` statement for the \"no name\" case, so it falls off the end and returns `None` instead - which then crashes when `.upper()` is called on it.', 'Add an explicit `return \"unknown\"` as the fallback.');
INSERT INTO `bh_puzzle_bugs` VALUES (177, 163, 1, 2, 2, 'runtime', 85, 'Round brackets `()` call something; square brackets `[]` index into it. `totals` is a list, so it needs `[]`.', 'Change `totals(0)` to `totals[0]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (178, 164, 1, 3, 3, 'runtime', 88, 'You cannot loop directly over an `int` - only over things like strings, lists and other collections.', 'Convert `n` to a string with `str(n)` before looping over it.');
INSERT INTO `bh_puzzle_bugs` VALUES (179, 165, 1, 2, 2, 'runtime', 88, 'An `int` cannot be indexed with `[]` - only sequences like strings and lists can.', 'Convert to a string, index it, then convert the single character back to an `int`.');
INSERT INTO `bh_puzzle_bugs` VALUES (180, 166, 1, 2, 2, 'runtime', 89, '`scores[-2]` crashes if `scores` has fewer than two items - negative indexes are still bounded by the list\'s actual length.', 'Check the length first and return `None` for a too-short list.');
INSERT INTO `bh_puzzle_bugs` VALUES (181, 167, 1, 2, 2, 'runtime', 90, '`.pop(key)` raises `KeyError` if `key` isn\'t in the dictionary, the same as `dict[key]` would.', 'Check `item in cart` before popping it.');
INSERT INTO `bh_puzzle_bugs` VALUES (182, 168, 1, 2, 2, 'runtime', 89, '`.pop(0)` on an empty list has nothing to remove, which raises an `IndexError`.', 'Check whether `queue` is empty before popping from it.');
INSERT INTO `bh_puzzle_bugs` VALUES (183, 169, 1, 2, 2, 'runtime', 88, '`len()` works on sequences (strings, lists, ...), not on a plain `int`.', 'Convert `n` to a string before measuring its length.');
INSERT INTO `bh_puzzle_bugs` VALUES (184, 170, 1, 2, 2, 'runtime', 88, '`int()` cannot parse text that contains anything other than digits (and an optional sign) - `\"25 years\"` has extra words in it.', 'Split the text and convert only the first word.');
INSERT INTO `bh_puzzle_bugs` VALUES (185, 171, 1, 2, 2, 'runtime', 88, '`list + int` is not a valid operation - `+` on a list only works with another list.', 'Add `bonus` to each item individually with a list comprehension.');
INSERT INTO `bh_puzzle_bugs` VALUES (186, 172, 1, 2, 2, 'runtime', 88, '`\"18\"` is a string, not a number - comparing an `int` to a `str` with `>=` is not supported.', 'Use the number `18`, not the string `\"18\"`.');
INSERT INTO `bh_puzzle_bugs` VALUES (187, 173, 1, 2, 2, 'runtime', 105, '`.appned` is a typo of `.append` - no such method exists on a list.', 'Fix the spelling: `.append(item)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (188, 174, 1, 3, 3, 'runtime', 95, 'The loop continues while `i <= len(numbers)`, but the valid indexes only go up to `len(numbers) - 1` - at `i == len(numbers)` the index is out of range.', 'Change `<=` to `<`.');
INSERT INTO `bh_puzzle_bugs` VALUES (189, 175, 1, 2, 2, 'runtime', 87, '`total` is assigned later in this function, which makes it local throughout the whole function - so referencing it on the line before that assignment fails, rather than falling back to an outer `total` (there isn\'t one here anyway).', 'Remove the leftover `print(total)` line written before `total` exists.');
INSERT INTO `bh_puzzle_bugs` VALUES (190, 176, 1, 2, 2, 'runtime', 94, '`round()` takes at most two arguments (the number and the number of decimal places) - a third one is one too many.', 'Remove the extra third argument.');
INSERT INTO `bh_puzzle_bugs` VALUES (191, 177, 1, 2, 2, 'runtime', 90, 'Direct indexing `grades[subject]` crashes if `subject` is not a key - `.get(key, default)` handles the missing case gracefully.', 'Use `.get(subject, \"Not taken\")` instead of `[subject]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (192, 178, 1, 3, 3, 'runtime', 90, 'A list cannot be a dictionary key because lists are mutable - Python requires keys to be hashable (unchangeable).', 'Convert `stops` to a tuple before using it as a key.');
INSERT INTO `bh_puzzle_bugs` VALUES (193, 179, 1, 2, 2, 'runtime', 95, 'The last valid index of a string is `len(word) - 1`, not `len(word)`.', 'Subtract 1 from the index.');
INSERT INTO `bh_puzzle_bugs` VALUES (194, 180, 1, 2, 2, 'runtime', 91, 'An empty list has length `0`, so dividing by `len(numbers)` crashes with `ZeroDivisionError`.', 'Check for an empty list before dividing.');
INSERT INTO `bh_puzzle_bugs` VALUES (195, 181, 1, 5, 5, 'runtime', 87, '`start_game()` is called before its `def` has been reached, so it does not exist yet at that point in the script.', 'Move the `start_game` definition above the code that calls it.');
INSERT INTO `bh_puzzle_bugs` VALUES (196, 182, 1, 2, 2, 'runtime', 105, 'Strings have no `.sort()` method because strings are immutable - they cannot be changed in place.', 'Use the `sorted()` function, which returns a new sorted list, then join it back into a string.');
INSERT INTO `bh_puzzle_bugs` VALUES (197, 183, 1, 2, 2, 'runtime', 108, 'There is no base case - `countdown` calls itself unconditionally, forever, until Python runs out of stack space.', 'Add a base case that returns without recursing once `n` reaches 0 or below.');
INSERT INTO `bh_puzzle_bugs` VALUES (198, 184, 1, 5, 6, 'runtime', 111, 'Calling `next()` a third time asks for an item that might not exist - once an iterator is exhausted, `next()` raises `StopIteration`.', 'Only call `next()` as many times as items you actually need.');
INSERT INTO `bh_puzzle_bugs` VALUES (199, 185, 1, 2, 2, 'runtime', 91, '`%` raises `ZeroDivisionError` when the right-hand side is `0`, exactly like `/` does.', 'Guard against `group_size == 0` before using `%`.');
INSERT INTO `bh_puzzle_bugs` VALUES (200, 186, 1, 2, 2, 'runtime', 101, 'Starting `total` as an empty string means `total += p` tries to add a number to a string, which fails immediately.', 'Start `total` at `0`.');
INSERT INTO `bh_puzzle_bugs` VALUES (201, 187, 1, 2, 2, 'runtime', 90, '`.keys()` only exists on dictionaries - `students` here is a list, which has no such method.', 'Loop through the list and collect names you have not already added.');
INSERT INTO `bh_puzzle_bugs` VALUES (202, 188, 1, 5, 5, 'runtime', 94, '`compute_total` has a parameter named `price` (singular), but the call uses the keyword `prices` (plural) - they have to match exactly.', 'Use the correct keyword: `price=price`.');
INSERT INTO `bh_puzzle_bugs` VALUES (203, 189, 1, 2, 2, 'runtime', 88, 'Unpacking `first, last = full_name.split(\" \")` requires exactly two parts - a name with three or more words produces more values than there are variables to catch them.', 'Split into a list and take the first and last items by index instead of unpacking directly.');
INSERT INTO `bh_puzzle_bugs` VALUES (204, 190, 1, 2, 2, 'runtime', 88, 'Unpacking into `x, y, z` requires three values, but a 2-item point only has two.', 'Unpack into `x, y` instead.');
INSERT INTO `bh_puzzle_bugs` VALUES (205, 191, 1, 3, 3, 'logic', 95, '`range(1, n)` stops at `n - 1`, so `n` is never added.', 'Use `range(1, n + 1)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (206, 192, 1, 2, 2, 'logic', 95, 'The number of posts is always one more than the number of sections (there\'s a post at both ends), but this just returns the section count.', 'Return `sections + 1`.');
INSERT INTO `bh_puzzle_bugs` VALUES (207, 193, 1, 2, 2, 'logic', 97, '`//` throws away the remainder (integer division); the brief needs the exact average, including any fraction.', 'Use `/` instead of `//`.');
INSERT INTO `bh_puzzle_bugs` VALUES (208, 194, 1, 2, 2, 'logic', 98, 'Without brackets, `/` happens before `+`, so this divides only `b` by 2 instead of the whole sum.', 'Add brackets: `(a + b) / 2`.');
INSERT INTO `bh_puzzle_bugs` VALUES (209, 195, 1, 2, 2, 'logic', 99, 'With `or`, almost every length passes (anything satisfies at least one side). Both conditions need to hold at once.', 'Change `or` to `and`.');
INSERT INTO `bh_puzzle_bugs` VALUES (210, 196, 1, 5, 5, 'logic', 100, '`return None` is inside the loop, so it runs on the very first number if that one isn\'t even - the loop never gets a chance to check the rest.', 'Dedent `return None` so it\'s after the loop, not inside it.');
INSERT INTO `bh_puzzle_bugs` VALUES (211, 197, 1, 2, 2, 'logic', 101, '`total` is only reset to 0 once, before the outer loop starts, so each inner list\'s sum keeps adding onto the previous one.', 'Move `total = 0` inside the outer loop, right before the inner loop.');
INSERT INTO `bh_puzzle_bugs` VALUES (212, 198, 1, 4, 4, 'logic', 102, '`n` is never decreased, so `n > 0` stays true forever and the loop never ends.', 'Add `n -= 1` after `result.append(n)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (213, 199, 1, 2, 2, 'logic', 88, '`a` and `b` are strings, so `a > b` compares them alphabetically (like a dictionary), not numerically - `\"9\"` sorts after `\"10\"`.', 'Convert both to `int` before comparing.');
INSERT INTO `bh_puzzle_bugs` VALUES (214, 200, 1, 2, 2, 'runtime', 103, 'Naming a variable `sum` hides the built-in `sum()` function for the rest of this scope, so `sum(unique)` later tries to call the number `0` instead.', 'Remove the `sum = 0` line - it\'s unused, and it shadows the builtin needed later.');
INSERT INTO `bh_puzzle_bugs` VALUES (215, 201, 1, 2, 4, 'logic', 104, 'Removing items from `nums` while looping over it shifts the remaining items\' positions, so the loop can skip the item right after a removed one.', 'Build a new filtered list instead, e.g. with a list comprehension.');
INSERT INTO `bh_puzzle_bugs` VALUES (216, 202, 1, 4, 4, 'logic', 105, '`\"aeiou\"` only matches lowercase vowels, so uppercase ones like `\'A\'` are never counted.', 'Use `ch.lower() in \"aeiou\"`.');
INSERT INTO `bh_puzzle_bugs` VALUES (217, 203, 1, 2, 2, 'logic', 101, 'Starting `best` at `0` silently assumes the real maximum is never negative.', 'Start `best` at the first real item, `numbers[0]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (218, 204, 1, 2, 2, 'logic', 127, '`a - b` can be negative - the brief wants the positive difference regardless of argument order.', 'Wrap the result in `abs(...)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (219, 205, 1, 3, 3, 'logic', 128, 'Returning `True` as soon as one score passes checks \"does *any* score pass?\", not \"do *all* scores pass?\".', 'Return `False` on the first failing score instead, and only return `True` after checking every score.');
INSERT INTO `bh_puzzle_bugs` VALUES (220, 206, 1, 2, 4, 'logic', 129, 'The condition is correct, but the two return values have been swapped between the branches.', 'Swap the two return values back.');
INSERT INTO `bh_puzzle_bugs` VALUES (221, 207, 1, 2, 2, 'logic', 88, '`score1 + score2` concatenates the two strings (`\"10\" + \"20\"` gives `\"1020\"`) instead of adding their numeric values - no error, just the wrong kind of answer.', 'Convert both arguments to `int` before adding them.');
INSERT INTO `bh_puzzle_bugs` VALUES (222, 208, 1, 2, 2, 'logic', 113, '`sorted()` defaults to ascending order, so `[:3]` takes the 3 *smallest* values, not the 3 largest.', 'Pass `reverse=True` to sort largest-first.');
INSERT INTO `bh_puzzle_bugs` VALUES (223, 209, 1, 2, 2, 'logic', 88, '`max()` on strings compares them character by character (lexicographically), not numerically - `\"9\"` sorts after `\"10\"` that way.', 'Use `max(ids, key=int)` to compare by numeric value instead.');
INSERT INTO `bh_puzzle_bugs` VALUES (224, 210, 1, 2, 2, 'logic', 130, '`int()` truncates (always rounds towards zero) rather than rounding to the nearest whole number.', 'Use `round()` instead of `int()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (225, 211, 1, 2, 4, 'logic', 95, '`score > 90` excludes a score of exactly 90, but the brief says 90 should count as \"A\".', 'Change `>` to `>=` on both boundaries.');
INSERT INTO `bh_puzzle_bugs` VALUES (226, 212, 1, 2, 2, 'logic', 82, '`name in names` compares text exactly as written - it treats `\"ada\"` and `\"Ada\"` as completely different.', 'Convert both the name and the list to lower case before checking membership.');
INSERT INTO `bh_puzzle_bugs` VALUES (227, 213, 1, 2, 2, 'logic', 115, '`is` checks object identity, not value equality - two lists with identical contents are still different objects unless they are literally the same one.', 'Use `==` to compare values instead of `is`.');
INSERT INTO `bh_puzzle_bugs` VALUES (228, 214, 1, 2, 2, 'logic', 96, 'A step of `1` includes every number, not just even ones - the step needs to be `2` to skip the odd numbers.', 'Change the step argument from `1` to `2`.');
INSERT INTO `bh_puzzle_bugs` VALUES (229, 215, 1, 2, 2, 'logic', 95, 'A slice `text[0:n]` already stops before index `n`, giving exactly `n` characters - subtracting an extra 1 cuts one character too many.', 'Remove the `-1`: use `text[0:n]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (230, 216, 1, 6, 7, 'logic', 102, '`break` exits the loop entirely as soon as one non-positive number is seen, ignoring any positives that come after it.', 'Remove the `break` - a non-positive number should just be skipped, not stop the count.');
INSERT INTO `bh_puzzle_bugs` VALUES (231, 217, 1, 2, 2, 'logic', 131, 'The division is the wrong way round - it computes `total / correct` instead of `correct / total`.', 'Swap the numerator and denominator.');
INSERT INTO `bh_puzzle_bugs` VALUES (232, 218, 1, 6, 6, 'logic', 93, 'The fallback `return 10` accidentally copies silver\'s discount instead of using the \"anything else\" value of `0`.', 'Change the final `return` to `0`.');
INSERT INTO `bh_puzzle_bugs` VALUES (233, 219, 1, 4, 4, 'logic', 98, '`letter == \"a\" or \"e\" or \"i\" or \"o\" or \"u\"` is parsed as `(letter == \"a\") or (\"e\") or (\"i\") or (\"o\") or (\"u\")` - every string after the first is just a non-empty string, which Python treats as truthy regardless of `letter`, so the whole condition is always `True`.', 'Use `letter in \"aeiou\"` to properly check whether `letter` is one of the vowels.');
INSERT INTO `bh_puzzle_bugs` VALUES (234, 220, 1, 4, 4, 'logic', 101, 'The condition checks for odd numbers (`% 2 == 1`) while the function is meant to sum even ones.', 'Change `== 1` to `== 0`.');
INSERT INTO `bh_puzzle_bugs` VALUES (235, 221, 1, 4, 4, 'logic', 101, 'Keeping the value whenever `p > best` tracks the *largest* value seen, which finds a maximum - \"cheapest\" needs a minimum.', 'Change `>` to `<` so it keeps the smallest value instead.');
INSERT INTO `bh_puzzle_bugs` VALUES (236, 222, 1, 2, 2, 'logic', 99, '`or` lets the password pass if just one condition holds - the brief requires both the length *and* the alphanumeric check to hold.', 'Change `or` to `and`.');
INSERT INTO `bh_puzzle_bugs` VALUES (237, 223, 1, 2, 2, 'logic', 99, '`and` requires both the height *and* the adult to be present - the brief says either one on its own is enough.', 'Change `and` to `or`.');
INSERT INTO `bh_puzzle_bugs` VALUES (238, 224, 1, 2, 2, 'logic', 99, 'The condition keeps numbers where `n % 2 == 0` (even), but the function is meant to keep odd numbers.', 'Change the condition to `n % 2 == 1`.');
INSERT INTO `bh_puzzle_bugs` VALUES (239, 225, 1, 2, 2, 'logic', 93, 'The parts are concatenated as `last` then `first`, the reverse of the order the brief asks for.', 'Swap the order to `first + \" \" + last`.');
INSERT INTO `bh_puzzle_bugs` VALUES (240, 226, 1, 2, 2, 'logic', 93, 'The function returns `items` on its own, completely ignoring `price_per_item` - the actual cost calculation is missing.', 'Multiply the two parameters together.');
INSERT INTO `bh_puzzle_bugs` VALUES (241, 227, 1, 2, 2, 'logic', 95, '\"5 years or more\" includes exactly 5, but `>` excludes it.', 'Change `>` to `>=`.');
INSERT INTO `bh_puzzle_bugs` VALUES (242, 228, 1, 3, 3, 'logic', 101, 'Dividing by a hardcoded `100` only gives a correct average when there happen to be exactly 100 scores.', 'Divide by `len(scores)`, the actual number of scores, instead.');
INSERT INTO `bh_puzzle_bugs` VALUES (243, 229, 1, 2, 4, 'logic', 129, '`my_score < their_score` is labelled `\"Win\"` and `my_score > their_score` is labelled `\"Loss\"` - the opposite of what those words mean.', 'Swap the two comparison operators.');
INSERT INTO `bh_puzzle_bugs` VALUES (244, 230, 1, 2, 2, 'logic', 97, '`/` gives the exact, possibly-fractional result (e.g. `2.0833...`) - the brief wants only whole minutes.', 'Use `//` for integer (floor) division.');
INSERT INTO `bh_puzzle_bugs` VALUES (245, 231, 1, 5, 5, 'logic', 87, '`longest = words` stores the *entire list* (plural) instead of `w`, the current word (singular) - a one-letter difference in the name with a completely different meaning.', 'Change `words` to `w` on that line.');
INSERT INTO `bh_puzzle_bugs` VALUES (246, 232, 1, 2, 2, 'logic', 98, 'Without brackets, `/` happens before `+` - this computes `a + (b / 2)`, not `(a + b) / 2`.', 'Add brackets around `a + b`.');
INSERT INTO `bh_puzzle_bugs` VALUES (247, 233, 1, 1, 2, 'runtime', 108, 'There\'s no base case, so `factorial` keeps calling itself with a smaller `n` forever, until Python\'s recursion limit is hit.', 'Add `if n <= 1: return 1` before the recursive call.');
INSERT INTO `bh_puzzle_bugs` VALUES (248, 234, 1, 1, 1, 'logic', 106, 'The default list `[]` is created once when the function is defined, and reused across every call that doesn\'t supply its own basket - so items pile up across calls instead of starting fresh.', 'Default to `None`, and create a new list inside the function when no basket is given.');
INSERT INTO `bh_puzzle_bugs` VALUES (249, 235, 1, 2, 2, 'logic', 107, '`doubled = original` makes `doubled` point at the same list object as `original`, so changing one through its index changes both.', 'Use `original.copy()` to create an independent list.');
INSERT INTO `bh_puzzle_bugs` VALUES (250, 236, 1, 1, 1, 'logic', 107, '`[[0] * 3] * 3` makes a list containing the *same* inner list object three times, so changing one row through an index changes every row.', 'Build the rows with a list comprehension so each one is a separate list.');
INSERT INTO `bh_puzzle_bugs` VALUES (251, 237, 1, 7, 9, 'logic', 109, 'Setting `low = mid` or `high = mid` (instead of `mid + 1` / `mid - 1`) can leave the search bounds unchanged between passes, looping forever when the target isn\'t present.', 'Move the bounds past `mid`: `low = mid + 1` and `high = mid - 1`, and start `high` at `len(items) - 1`.');
INSERT INTO `bh_puzzle_bugs` VALUES (252, 238, 1, 3, 3, 'logic', 110, 'The lambda doesn\'t capture `i`\'s value at creation time - it looks `i` up when called, by which point the loop has finished and `i` holds its final value for every lambda.', 'Use a default argument to capture the current value: `lambda i=i: i`.');
INSERT INTO `bh_puzzle_bugs` VALUES (253, 239, 1, 4, 4, 'logic', 87, '`local_high` copies `high_score`\'s value but never writes back to it, so the module-level `high_score` stays `0` forever and each call compares against that, not the real running high score.', 'Add `global high_score` and update `high_score` itself.');
INSERT INTO `bh_puzzle_bugs` VALUES (254, 240, 1, 2, 2, 'logic', 111, 'A generator can only be stepped through once - the first `list(evens)` consumes every value, so the second one has nothing left to give.', 'Use a list comprehension `[n for n in nums if ...]` instead, which can be read as many times as needed.');
INSERT INTO `bh_puzzle_bugs` VALUES (255, 241, 1, 2, 2, 'logic', 112, 'Floating-point numbers can\'t represent most decimal fractions exactly, so `0.1 + 0.2 + 0.7` comes out as something like `0.9999999999999999`, not exactly `1.0`.', 'Use `math.isclose(...)` to compare with a small tolerance instead of `==`.');
INSERT INTO `bh_puzzle_bugs` VALUES (256, 242, 1, 2, 2, 'runtime', 104, 'Python detects that the dictionary\'s size changed mid-loop (from `del`) and refuses to continue, since it can no longer guarantee which items have been visited.', 'Loop over a snapshot of the keys instead: `for item in list(stock.keys()):`.');
INSERT INTO `bh_puzzle_bugs` VALUES (257, 243, 1, 2, 2, 'logic', 113, '`sorted()` defaults to ascending order, so taking the first 3 items gives the lowest scorers, not the highest.', 'Add `reverse=True`.');
INSERT INTO `bh_puzzle_bugs` VALUES (258, 244, 1, 3, 6, 'logic', 114, 'A typo (`resutl` instead of `result`) causes a `NameError` every single call, but the bare `except:` catches it silently and returns `None`, hiding the real bug completely.', 'Fix the typo, and avoid bare `except:` clauses that can hide genuine bugs like this one.');
INSERT INTO `bh_puzzle_bugs` VALUES (259, 245, 1, 2, 2, 'logic', 115, '`is` checks object identity (are these literally the same object?), not equal contents - two separately-created lists with identical items are still different objects.', 'Use `==` to compare values instead of `is`.');
INSERT INTO `bh_puzzle_bugs` VALUES (260, 246, 1, 2, 2, 'logic', 107, '`[[0] * size] * size` makes a list containing the *same* inner list object `size` times, so changing one row through an index changes every row.', 'Build the rows with a list comprehension so each one is a separate list.');
INSERT INTO `bh_puzzle_bugs` VALUES (261, 247, 1, 2, 2, 'logic', 106, '`dict.fromkeys(players, [])` gives every player the *same* list object - appending to one player\'s list appends to all of them.', 'Build the dictionary with a comprehension so each player gets their own independent list.');
INSERT INTO `bh_puzzle_bugs` VALUES (262, 248, 1, 2, 2, 'logic', 132, '`.sort()` sorts `names` in place and returns `None` - assigning `names = names.sort()` throws away the real list and keeps `None` instead.', 'Call `.sort()` without reassigning it, then return `names` on its own.');
INSERT INTO `bh_puzzle_bugs` VALUES (263, 249, 1, 2, 2, 'logic', 132, '`.append()` modifies `items` in place and returns `None` - reassigning `items` to that result loses the real list.', 'Call `.append()` on its own line, then return `items`.');
INSERT INTO `bh_puzzle_bugs` VALUES (264, 250, 1, 2, 2, 'logic', 132, '`.reverse()` reverses `queue` in place and returns `None` - reassigning to it loses the list.', 'Call `.reverse()` without reassigning, then return `queue`.');
INSERT INTO `bh_puzzle_bugs` VALUES (265, 251, 1, 1, 1, 'logic', 106, 'The default `log={}` is created once at definition time and shared by every call that does not supply its own - so entries from earlier calls leak into later ones.', 'Default to `None` and build a fresh dictionary inside the function body when needed.');
INSERT INTO `bh_puzzle_bugs` VALUES (266, 252, 1, 3, 3, 'runtime', 110, '`count += 1` makes `count` local to `increment`, so it tries to read `count` before that local ever has a value - it does not automatically reach out to the enclosing function\'s `count`.', 'Add `nonlocal count` before using it, so `increment` modifies the outer variable instead of creating its own.');
INSERT INTO `bh_puzzle_bugs` VALUES (267, 253, 1, 3, 3, 'logic', 108, 'The base case for an empty list returns `1` instead of `0` - since every recursive call eventually bottoms out at this base case, every call to `sum_list` ends up one too high.', 'Return `0` for the empty-list base case, the identity value for addition.');
INSERT INTO `bh_puzzle_bugs` VALUES (268, 254, 1, 2, 2, 'logic', 133, '`zip()` stops at the length of the shorter iterable, silently discarding any extra items in the longer one - no error, no warning.', 'Use `itertools.zip_longest()` to keep every item, padding missing ones with `None`.');
INSERT INTO `bh_puzzle_bugs` VALUES (269, 255, 1, 2, 2, 'logic', 133, '`enumerate()` numbers items starting at `0` unless told otherwise - the brief wants human-friendly 1-based numbering.', 'Pass `start=1` to `enumerate()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (270, 256, 1, 2, 2, 'logic', 134, 'Python\'s `bool` is actually a subtype of `int` - `True` equals `1` and hashes the same way, so a plain `set` merges them into a single entry.', 'Include the type alongside the value (e.g. `(type(x), x)`) so `True` and `1` are kept distinct.');
INSERT INTO `bh_puzzle_bugs` VALUES (271, 257, 1, 2, 2, 'logic', 113, 'Without a `key`, each `[name, score]` pair is compared element by element starting with the first one (the name) - the score is only used to break ties between identical names.', 'Sort using `key=lambda s: s[1]` to compare by score specifically.');
INSERT INTO `bh_puzzle_bugs` VALUES (272, 258, 1, 4, 4, 'logic', 112, 'Adding `0.1` repeatedly accumulates tiny rounding errors that an exact `==` comparison never tolerates, even though the values are \"the same\" for any practical purpose.', 'Use `math.isclose(...)` for a tolerant comparison instead of `==`.');
INSERT INTO `bh_puzzle_bugs` VALUES (273, 259, 1, 4, 4, 'logic', 107, '`copy.copy()` (a shallow copy) duplicates the outer list only - the inner row lists are still the *same objects* as in the original, so mutating a row through the copy mutates it in the original too.', 'Use `copy.deepcopy()` to copy every nested level independently.');
INSERT INTO `bh_puzzle_bugs` VALUES (274, 260, 1, 2, 3, 'logic', 105, '`.strip()` and `.title()` return new strings rather than changing `name` in place - calling them without reassigning the result does nothing to `name` itself.', 'Reassign the result of each call back to `name`.');
INSERT INTO `bh_puzzle_bugs` VALUES (275, 261, 1, 2, 2, 'logic', 93, '`compute_bmi` returns the values in the order `(height_m, weight_kg)`, but `bmi_category` unpacks them as `weight, height` - the two orders disagree, so `weight` actually ends up holding the height and vice versa.', 'Make the returned tuple order match the order used to unpack it: `weight_kg, height_m`.');
INSERT INTO `bh_puzzle_bugs` VALUES (276, 262, 1, 1, 1, 'logic', 106, 'The default `result=[]` is shared across every top-level call to `collect_evens` that does not supply its own list - results from an earlier, unrelated call leak into a later one.', 'Default to `None` and create the real list inside the function.');
INSERT INTO `bh_puzzle_bugs` VALUES (277, 263, 1, 2, 4, 'logic', 111, 'A generator expression can only be iterated once - after `sum(1 for _ in evens)` has consumed it, `list(evens)` finds it already exhausted and gets an empty list.', 'Build a plain list comprehension once (`[n for n in numbers if n % 2 == 0]`) and reuse that list for both the count and the result.');
INSERT INTO `bh_puzzle_bugs` VALUES (278, 264, 1, 2, 2, 'logic', 107, '`data` inside `get_sorted` is the same object as `original` outside it (lists are passed by reference) - sorting `data` in place mutates `original` directly.', 'Copy `data` before sorting it, so the caller\'s original list is untouched.');
INSERT INTO `bh_puzzle_bugs` VALUES (279, 265, 1, 2, 2, 'logic', 135, 'Plain `sorted()` compares text exactly as written - every capital letter sorts before every lowercase letter, which is not the same as alphabetical order a reader would expect.', 'Sort with `key=str.lower` to compare case-insensitively.');
INSERT INTO `bh_puzzle_bugs` VALUES (280, 266, 1, 2, 2, 'logic', 107, 'A chained assignment `a = b = []` creates one list object and points both `a` and `b` at it - they are not independent, so changing one changes \"both\".', 'Assign each team its own list on a separate line.');
INSERT INTO `bh_puzzle_bugs` VALUES (281, 267, 1, 3, 3, 'logic', 107, '`copy_of_list = original` does not copy anything - it just creates a second name for the same list object, so mutating either one mutates both.', 'Use `original[:]` (or `original.copy()`) to actually create an independent list.');
INSERT INTO `bh_puzzle_bugs` VALUES (282, 268, 1, 3, 3, 'logic', 87, '`global running_total` means every call to `add_all` keeps adding onto the same running total from previous calls, instead of starting from zero.', 'Use a fresh local variable inside the function instead of a shared global one.');
INSERT INTO `bh_puzzle_bugs` VALUES (283, 269, 1, 5, 5, 'logic', 112, 'Dictionary lookup (`prices.get(...)`) requires an exact match - a `total_weight` built up from repeated floating-point addition is extremely unlikely to exactly equal a literal like `0.3`, even though it looks identical when printed.', 'Search the dictionary comparing keys with a tolerance, using `math.isclose()`, instead of exact lookup.');
INSERT INTO `bh_puzzle_bugs` VALUES (284, 270, 1, 2, 2, 'logic', 136, '`result` is only ever created inside the `if` branch - if no even number is ever found, `result` never gets assigned at all (and this would actually crash on an all-odd list, rather than falling back to `default`).', 'Initialise `result = default` before the loop begins.');
INSERT INTO `bh_puzzle_bugs` VALUES (285, 271, 1, 3, 3, 'logic', 90, '`for item in inventory:` iterates over the dictionary\'s *keys* by default - to get at the values (the quantities), you need `inventory.values()`.', 'Loop over `inventory.values()` instead of `inventory` itself.');
INSERT INTO `bh_puzzle_bugs` VALUES (286, 272, 1, 3, 3, 'logic', 108, 'The base case returns `0`, but every recursive call multiplies by the eventual base-case result - multiplying any chain of numbers by `0` collapses the whole answer to `0`.', 'Return `1` for the base case, the identity value for multiplication (the same way `0` is the identity value for addition).');
INSERT INTO `bh_puzzle_bugs` VALUES (287, 273, 1, 3, 3, 'logic', 107, 'A dictionary\'s `.copy()` is shallow - it duplicates the dictionary itself, but any mutable value inside it (like a list) is still the *same object*, shared between the original and the copy.', 'Use `copy.deepcopy()` to copy the list values independently too.');
INSERT INTO `bh_puzzle_bugs` VALUES (288, 274, 1, 2, 2, 'logic', 137, '`not score` treats `0` the same as `None` - both are \"falsy\" - but a score of `0` is a real, meaningful value, not a missing one.', 'Check `score is None` specifically, rather than relying on general truthiness.');
INSERT INTO `bh_puzzle_bugs` VALUES (289, 275, 1, 2, 2, 'logic', 135, '`min(names)` without a `key` compares the strings alphabetically - it has no idea you meant to compare by length.', 'Pass `key=len` to compare by string length instead.');
INSERT INTO `bh_puzzle_bugs` VALUES (290, 276, 1, 5, 5, 'runtime', 91, 'If `scores` is empty, `len(scores)` is `0` and dividing by it crashes with a `ZeroDivisionError`.', 'Check for an empty list first and return `\"No scores\"` before dividing.');
INSERT INTO `bh_puzzle_bugs` VALUES (291, 276, 2, 6, 9, 'logic', NULL, 'Using `>` instead of `>=` means a score landing exactly on a boundary (70 or 50) is marked down a grade.', 'Change both comparisons to `>=` so the boundary itself counts for the higher grade.');
INSERT INTO `bh_puzzle_bugs` VALUES (292, 277, 1, 4, 4, 'logic', 95, 'Adding `shift` directly to the character code doesn\'t wrap around the alphabet - shifting \'z\' just gives the character after \'z\', not back to \'a\'.', 'Work in alphabet positions 0-25 with `% 26` to wrap around, then convert back to a character.');
INSERT INTO `bh_puzzle_bugs` VALUES (293, 277, 2, 4, 5, 'logic', NULL, 'Every character is shifted, including spaces and punctuation, which should be left exactly as they are.', 'Only shift letters (`ch.isupper()` or `ch.islower()`); copy everything else through unchanged.');
INSERT INTO `bh_puzzle_bugs` VALUES (294, 278, 1, 1, 8, 'logic', NULL, 'Only rows and columns are checked for a win - the two diagonals are never checked at all.', 'Also check `board[0][0], board[1][1], board[2][2]` and `board[0][2], board[1][1], board[2][0]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (295, 278, 2, 8, 8, 'logic', NULL, 'A full board with no winner should return `\"Draw\"`, but this always returns `None` once every line has been checked.', 'After checking every line, check if every cell is filled and return `\"Draw\"` if so.');
INSERT INTO `bh_puzzle_bugs` VALUES (296, 279, 1, 2, 2, 'logic', 106, '`transactions = []` written directly under the class is a *class* attribute, shared by every instance - one account\'s withdrawals show up in every other account\'s transaction list.', 'Move it inside `__init__` as `self.transactions = []` so each account gets its own list.');
INSERT INTO `bh_puzzle_bugs` VALUES (297, 279, 2, 7, 9, 'logic', NULL, '`withdraw` never checks the balance, so an account can be withdrawn into a negative balance with no warning.', 'Raise an error (e.g. `ValueError`) if `amount` is more than `self.balance`.');
INSERT INTO `bh_puzzle_bugs` VALUES (298, 280, 1, 4, 5, 'logic', NULL, '`stock[item] -= qty` is duplicated, so every order is deducted from stock twice.', 'Delete one of the two identical lines.');
INSERT INTO `bh_puzzle_bugs` VALUES (299, 280, 2, 4, 4, 'runtime', 90, 'An order for an item not already in `stock` crashes with a `KeyError` instead of being safely ignored.', 'Check `if item not in stock: continue` before updating it.');
INSERT INTO `bh_puzzle_bugs` VALUES (300, 281, 1, 2, 4, 'logic', 95, 'The list has size `n` and the loops stop before reaching `n`, so `n` itself is never considered - even when it\'s prime.', 'Size the list `n + 1` and loop through `range(2, n + 1)` so `n` is included.');
INSERT INTO `bh_puzzle_bugs` VALUES (301, 281, 2, 3, 3, 'logic', NULL, '`1` is never marked as not-prime (only index `0` is), so it can incorrectly show up in the result for small values of `n`.', 'Also set `is_prime[1] = False`.');
INSERT INTO `bh_puzzle_bugs` VALUES (302, 282, 1, 15, 15, 'logic', NULL, 'The merging loop stops as soon as one side (`left` or `right`) is exhausted, but any remaining items in the *other* side are never added to the result - they\'re silently dropped.', 'After the loop, append the leftover tail of both `left` and `right` to `merged`.');
INSERT INTO `bh_puzzle_bugs` VALUES (303, 283, 1, 10, 12, 'logic', NULL, '`current.next = prev` overwrites the link to the rest of the list *before* `current = current.next` reads it, so after the very first step `current` becomes `prev` and the rest of the original list is lost.', 'Save `next_node = current.next` before overwriting `current.next`, and advance using the saved value.');
INSERT INTO `bh_puzzle_bugs` VALUES (304, 284, 1, 2, 2, 'runtime', 91, 'An empty (or whitespace-only) `text` produces an empty `words` list, and dividing by `len(words)` (which is `0`) crashes.', 'Check for an empty `words` list and return the zero-result early.');
INSERT INTO `bh_puzzle_bugs` VALUES (305, 284, 2, 2, 2, 'logic', NULL, 'Punctuation attached to a word (like the comma in \"Hello,\") is counted as part of its length, inflating `avg_word_length`.', 'Strip punctuation characters off each word (e.g. with `.strip(\'.,!?;:\"\\\'\')`) before measuring its length.');
INSERT INTO `bh_puzzle_bugs` VALUES (306, 285, 1, 3, 3, 'logic', 98, 'The discount amount is computed as `total - discount_percent / 100`, which is nowhere close to \"X% of the total\" - it should be a multiplication, not a subtraction.', 'Compute the discount as `total * (discount_percent / 100)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (307, 286, 1, 11, 14, 'logic', 99, '`is_solved` returns `True` when it finds an unguessed letter and `False` otherwise - the exact opposite of what \"solved\" means.', 'Swap the two return values.');
INSERT INTO `bh_puzzle_bugs` VALUES (308, 286, 2, 17, 20, 'logic', 95, '`play_round` computes the masked word and solved status *before* adding the new guess, so the result never reflects the guess that was just made.', 'Append the new guess first, then compute the masked word and solved status.');
INSERT INTO `bh_puzzle_bugs` VALUES (309, 287, 1, 8, 8, 'syntax', 83, '`if p1 = p2:` uses assignment instead of comparison.', 'Change `=` to `==`.');
INSERT INTO `bh_puzzle_bugs` VALUES (310, 287, 2, 2, 2, 'logic', 99, 'The winning pairs list has `(\"paper\", \"scissors\")` instead of `(\"paper\", \"rock\")` - paper should beat rock, not scissors.', 'Change that pair to `(\"paper\", \"rock\")`.');
INSERT INTO `bh_puzzle_bugs` VALUES (311, 288, 1, 3, 3, 'runtime', 95, '`range(1, 6)` only covers 1 to 5 - rolling a `6` then crashes with a `KeyError` since `counts` never got a `6` entry.', 'Change `range(1, 6)` to `range(1, 7)` to include 6.');
INSERT INTO `bh_puzzle_bugs` VALUES (312, 289, 1, 4, 4, 'logic', 82, 'Comparing `answers[i] == correct_answers[i]` directly is case-sensitive, but the brief wants case-insensitive matching.', 'Lower-case both sides before comparing.');
INSERT INTO `bh_puzzle_bugs` VALUES (313, 290, 1, 6, 7, 'logic', 101, 'There is no handling for a word\'s *first* appearance - only existing entries ever get incremented, so a word seen exactly once never makes it into the dictionary at all.', 'Add an `else` branch that sets the count to `1` the first time a word is seen.');
INSERT INTO `bh_puzzle_bugs` VALUES (314, 291, 1, 3, 3, 'logic', 101, '`total = s` overwrites the running total with just the current score each time, instead of adding to it - the final total is only ever the *last* score.', 'Change `total = s` to `total += s`.');
INSERT INTO `bh_puzzle_bugs` VALUES (315, 291, 2, 8, 8, 'logic', 95, '`avg > 50` excludes an average of exactly 50, but the brief says 50 or above should pass.', 'Change `>` to `>=`.');
INSERT INTO `bh_puzzle_bugs` VALUES (316, 292, 1, 6, 6, 'syntax', 80, 'The `for` line has no colon.', 'Add `:` at the end of the `for` line.');
INSERT INTO `bh_puzzle_bugs` VALUES (317, 293, 1, 6, 6, 'logic', 87, 'The function returns `title` (the last loop variable value) instead of `titles` (the list that was actually being built) - a one-letter, singular/plural name mixup.', 'Return `titles` instead of `title`.');
INSERT INTO `bh_puzzle_bugs` VALUES (318, 293, 2, 4, 4, 'logic', 82, 'Comparing authors with `==` directly is case-sensitive, but the brief wants a case-insensitive match.', 'Lower-case both sides before comparing.');
INSERT INTO `bh_puzzle_bugs` VALUES (319, 294, 1, 2, 3, 'logic', 107, '`.remove()` and `.insert()` mutate `playlist` in place, and since lists are passed by reference, this also mutates whatever list the caller passed in - even though \"moving to front\" was only meant to affect the returned copy.', 'Copy `playlist` first, and perform the remove/insert on the copy.');
INSERT INTO `bh_puzzle_bugs` VALUES (320, 295, 1, 5, 5, 'logic', 82, 'Checking `email not in seen_emails` compares the email exactly as written, so `\"a@x.com\"` and `\"A@X.com\"` are treated as different emails.', 'Lower-case the email before checking membership.');
INSERT INTO `bh_puzzle_bugs` VALUES (321, 295, 2, 7, 7, 'logic', 82, 'Even once the check is fixed, `seen_emails` still needs to store the lower-cased email to stay consistent with the check.', 'Append the lower-cased email to `seen_emails`, inside the `if` branch (not for every contact).');
INSERT INTO `bh_puzzle_bugs` VALUES (322, 296, 1, 5, 5, 'logic', 82, '`clean` strips spaces but leaves the original case untouched, so \"Noon\" becomes \"Noon\" (not a palindrome by exact comparison) instead of \"noon\".', 'Lower-case each character while building the cleaned string.');
INSERT INTO `bh_puzzle_bugs` VALUES (323, 297, 1, 7, 7, 'runtime', 88, '`words - 1` tries to subtract a number from a list, which is not a valid operation and crashes immediately.', 'Just use `len(words)` - there is no need to subtract anything.');
INSERT INTO `bh_puzzle_bugs` VALUES (324, 298, 1, 9, 9, 'logic', 101, '`result = ch` overwrites the entire result built so far with just the current non-letter character, throwing away everything before it.', 'Change `result = ch` to `result += ch`.');
INSERT INTO `bh_puzzle_bugs` VALUES (325, 299, 1, 5, 5, 'runtime', 88, '`.replace()` requires its replacement to be a string - passing a non-string value (like the integer `12`) crashes with a `TypeError`.', 'Convert the value with `str(...)` before passing it to `.replace()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (326, 300, 1, 2, 2, 'logic', 107, '`result = numbers` makes `result` just another name for the same list - sorting it in place also sorts the original list the caller passed in, which the brief says should not happen.', 'Copy the list first with `numbers.copy()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (327, 301, 1, 4, 5, 'logic', 101, 'Incrementing `comparisons` only happens inside the `if` branch, so only the single comparison that actually matched gets counted - every comparison that did *not* match is left out.', 'Increment `comparisons` on every loop iteration, before checking for a match.');
INSERT INTO `bh_puzzle_bugs` VALUES (328, 302, 1, 6, 6, 'logic', 89, '`.pop(0)` removes from the *front* of the list, but a stack is meant to pop from the *top* (the end) - this is actually behaving like a queue, not a stack.', 'Use `.pop()` with no argument to remove from the end.');
INSERT INTO `bh_puzzle_bugs` VALUES (329, 302, 2, 6, 6, 'runtime', 89, 'Popping when the stack is already empty crashes with an `IndexError`, but the brief says it should just be ignored.', 'Check `if stack:` before popping.');
INSERT INTO `bh_puzzle_bugs` VALUES (330, 303, 1, 2, 2, 'runtime', 89, 'Calling `.pop(0)` on an empty list crashes with an `IndexError`, but the brief says this should return `None` instead.', 'Check whether `queue` is empty before popping from it.');
INSERT INTO `bh_puzzle_bugs` VALUES (331, 304, 1, 8, 8, 'logic', 138, 'The LCM formula needs `a * b // g`, but this adds `a` and `b` instead of multiplying them.', 'Change `(a + b) // g` to `a * b // g`.');
INSERT INTO `bh_puzzle_bugs` VALUES (332, 305, 1, 4, 4, 'logic', 95, 'The sequence is seeded with `[1, 1]` instead of `[0, 1]` - every number produced is shifted one place further along the real Fibonacci sequence than it should be.', 'Seed the sequence with `[0, 1]` instead of `[1, 1]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (333, 306, 1, 2, 4, 'logic', 129, 'The condition `guess > secret` (guess is too high) is labelled `\"Too low\"`, and vice versa - the two messages are swapped.', 'Swap the two return values.');
INSERT INTO `bh_puzzle_bugs` VALUES (334, 307, 1, 4, 4, 'logic', 107, '`[[0] * rows] * cols` makes a list of `cols` references to the *same* inner list - writing to one row through `result[c][r] = ...` overwrites every row at once.', 'Build the rows with a list comprehension so each one is independent.');
INSERT INTO `bh_puzzle_bugs` VALUES (335, 308, 1, 13, 13, 'logic', 102, 'The current run is only recorded when a *different* character ends it - the very last run in the text has nothing after it to trigger that, so it never gets added.', 'Append the final run to `result` once more, after the loop has finished.');
INSERT INTO `bh_puzzle_bugs` VALUES (336, 309, 1, 14, 14, 'logic', 131, 'Converting *from* centimetres *to* kilometres should divide (a km is much bigger than a cm), but this multiplies instead - the same mistake as the `m` branch, just the wrong operation in the other direction.', 'Change `value * 100000` to `value / 100000`.');
INSERT INTO `bh_puzzle_bugs` VALUES (337, 310, 1, 11, 11, 'logic', 106, 'The default `history=[]` is created once and shared across every call that relies on it - results from one call to `calculate` can leak into a later, unrelated call.', 'Default `history` to `None` and build a fresh list inside the function.');
INSERT INTO `bh_puzzle_bugs` VALUES (338, 311, 1, 5, 5, 'logic', 102, 'Returning as soon as the first match is found stops checking the rest of the list - if more than one task happens to share the same name, only the first one gets marked done.', 'Remove the early return inside the loop so every matching task gets updated.');
INSERT INTO `bh_puzzle_bugs` VALUES (339, 312, 1, 6, 6, 'logic', 101, '`errors = [...]` replaces the whole list rather than adding to it, so an earlier \"Username too short\" error (if any) gets wiped out.', 'Use `.append(...)` instead of reassigning `errors`.');
INSERT INTO `bh_puzzle_bugs` VALUES (340, 313, 1, 3, 3, 'logic', 135, 'Sorting the names list with no `key` sorts alphabetically - it never looks at `scores` at all, so the \"leaderboard\" order has nothing to do with actual performance.', 'Sort with `key=lambda name: scores[name], reverse=True` to rank by score.');
INSERT INTO `bh_puzzle_bugs` VALUES (341, 314, 1, 11, 11, 'logic', 113, '`a == b` checks the letters are in the exact same order - two anagrams have the same letters, but usually in a different order, so they would only match by coincidence.', 'Compare sorted versions of both: `sorted(a) == sorted(b)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (342, 315, 1, 8, 8, 'logic', 87, 'The function returns `amount` (the last transaction\'s amount) instead of `balance` (the actual running total) - a mixup between two similarly-used loop variables.', 'Return `balance` instead of `amount`.');
