INSERT INTO `bh_puzzle_tests` VALUES (922, 312, 2, 'validate_signup(\"Ada\", 20)', '(\'Ada\', 20)', NULL, NULL, 'returns', '[]', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (923, 312, 3, 'validate_signup(\"Ada\", 10)', '(\'Ada\', 10)', NULL, NULL, 'returns', '[\"Must be 13 or older\"]', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (924, 313, 1, 'top_n_players({\"Ada\": 90, \"Sam\": 70, \"Bo\": 85}, 2)', '({\'Ada\': 90, \'Sam\': 70, \'Bo\': 85}, 2)', NULL, NULL, 'returns', '[\"Ada\", \"Bo\"]', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (925, 313, 2, 'top_n_players({\"X\": 1, \"Y\": 2}, 1)', '({\'X\': 1, \'Y\': 2}, 1)', NULL, NULL, 'returns', '[\"Y\"]', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (926, 313, 3, 'top_n_players({\"Solo\": 100}, 5)', '({\'Solo\': 100}, 5)', NULL, NULL, 'returns', '[\"Solo\"]', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (927, 314, 1, 'are_anagrams(\"listen\", \"silent\")', '(\'listen\', \'silent\')', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (928, 314, 2, 'are_anagrams(\"hello\", \"world\")', '(\'hello\', \'world\')', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (929, 314, 3, 'are_anagrams(\"Dormitory\", \"Dirty Room\")', '(\'Dormitory\', \'Dirty Room\')', NULL, NULL, 'returns', 'True', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (930, 315, 1, 'apply_transactions(100, [[\"deposit\", 50], [\"withdrawal\", 30]])', '(100, [[\'deposit\', 50], [\'withdrawal\', 30]])', NULL, NULL, 'returns', '120', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (931, 315, 2, 'apply_transactions(50, [[\"withdrawal\", 100]])', '(50, [[\'withdrawal\', 100]])', NULL, NULL, 'returns', '50', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (932, 315, 3, 'apply_transactions(0, [])', '(0, [])', NULL, NULL, 'returns', '0', 'exact', 1);
INSERT INTO `bh_puzzles` VALUES (111, 'colon-needed', 11, 'Colon Needed', 1, 1, NULL, 'syntax', '`is_even(n)` should return `True` if `n` is even, and `False` otherwise.\n\nExample: `is_even(4)` should return `True`. `is_even(7)` should return `False`.', 'def is_even(n)\n    return n % 2 == 0\n', 'def is_even(n):\n    return n % 2 == 0\n', 'function', 'is_even', 'Every block header in Python - `def`, `if`, `for`, `while`, `class`, and the rest - ends with a colon. Without it, Python\'s parser doesn\'t know an indented block is coming next, and it fails before running a single line of your code.', 'Before you run anything, scan every line that should open a block and check it ends in `:`.', NULL, 'published', '186e8fc0c1891932c7ec4b984870c0d63ce405c4b29b0f28075bae0c51fd5553', '2026-11-22 20:26:13', NULL, '2026-11-22 20:26:13', '2026-11-22 20:26:13');
INSERT INTO `bh_puzzles` VALUES (112, 'missing-bracket', 11, 'Missing Bracket', 2, 1, NULL, 'syntax', 'This program should print the final score.\n\nExample output: `Final score: 10`', 'score = 10\nprint(\"Final score:\", score\n', 'score = 10\nprint(\"Final score:\", score)\n', 'script', NULL, 'Every opening bracket - `(`, `[`, `{` - needs a matching closing one. Python keeps reading, looking for that match, until it runs out of file, which is why the error can point somewhere that looks far away from the real mistake.', 'Count brackets in pairs on any line you\'re not sure about. An editor that highlights matching brackets (like this one) makes this easy to check at a glance.', NULL, 'published', '6275f982a653c9a139676f50f1ea85e541e123691e9e385b452148cd7aeed9a2', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (113, 'lonely-quote', 11, 'The Lonely Quote', 3, 1, NULL, 'syntax', 'This program should print a level-complete message.\n\nExample output: `Level complete!`', 'print(\"Level complete!)\n', 'print(\"Level complete!\")\n', 'script', NULL, 'A string needs a quote mark at both ends, matching in type (both `\"` or both `\'`). Miss one and Python treats everything afterwards as still being inside the string.', 'Count quote marks in pairs, the same way you would brackets.', NULL, 'published', 'c02f95389c3c4b0e8efc2f682891c5ce7ab9020435d5bb6254d901638afab8e2', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (114, 'indentation-station', 11, 'Indentation Station', 4, 1, NULL, 'syntax', '`double(n)` should return `n` multiplied by 2.\n\nExample: `double(5)` should return `10`.', 'def double(n):\nreturn n * 2\n', 'def double(n):\n    return n * 2\n', 'function', 'double', 'Python uses indentation, not brackets, to show which lines belong inside a block. A colon-ended line always needs its body indented one level in, consistently.', 'After any line ending in `:`, check the next line is indented - your editor\'s auto-indent usually does this for you, which is exactly why it\'s easy to miss when it doesn\'t.', NULL, 'published', '0efa631340af77346e55b17c28866bae25c440e3020bbbe6fc7154489d2fd71e', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (115, 'mixed-signals', 11, 'Mixed Signals', 5, 2, NULL, 'syntax', '`classify(n)` should return `\"positive\"` if `n` is greater than 0, and `\"non-positive\"` otherwise.\n\nExample: `classify(5)` should return `\"positive\"`.', 'def classify(n):\n    if n > 0:\n	x = \"positive\"\n        return x\n    return \"non-positive\"\n', 'def classify(n):\n    if n > 0:\n        return \"positive\"\n    return \"non-positive\"\n', 'function', 'classify', 'Tabs and spaces can look identical on screen but mean different things to Python\'s parser. Mixing them within the same block is ambiguous enough that Python refuses to guess and raises an error instead.', 'Set your editor to show whitespace characters, or just always use spaces (most Python style guides, and this editor, default to this).', NULL, 'published', 'fea6ef16cca2d8419ba02269d1ab155be29ebab9947318b0986db19a205e6bfc', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (116, 'capital-offence', 11, 'Capital Offence', 6, 1, NULL, 'runtime', 'This program should print a name.\n\nExample output: `Ada`', 'name = \"Ada\"\nPrint(name)\n', 'name = \"Ada\"\nprint(name)\n', 'script', NULL, 'Python treats `Print`, `print` and `PRINT` as three unrelated names. Built-in functions and keywords are always lowercase, so a capital letter here means Python goes looking for a name that was never created.', 'If a `NameError` names something that looks like a familiar built-in, check its capitalisation first.', NULL, 'published', '500f0b10e6b98e5454a109d7680842bdf76d2a6d07535d53632bbd35bdeeca32', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (117, 'single-equals', 11, 'Single Equals', 7, 2, NULL, 'syntax', '`check(x)` should return `\"five\"` if `x` equals 5, and `\"not five\"` otherwise.\n\nExample: `check(5)` should return `\"five\"`.', 'def check(x):\n    if x = 5:\n        return \"five\"\n    return \"not five\"\n', 'def check(x):\n    if x == 5:\n        return \"five\"\n    return \"not five\"\n', 'function', 'check', '`=` and `==` look similar but do very different jobs. `=` stores a value in a variable; `==` asks \"are these equal?\" and gives back `True` or `False`. Conditions always need the question, not the assignment.', 'Whenever you write an `if` or `while` condition, check for a single `=` - it should almost always be `==`.', NULL, 'published', '14b30efadffaf2c6b27b0f6199ef1e019ac41f3bc77fe863ceebde07380485a6', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (118, 'keyword-mixup', 11, 'Keyword Mixup', 8, 2, NULL, 'syntax', '`grade(score)` should return `\"Pass\"` if `score` is 50 or above, `\"Fail\"` if it\'s 0 or above but under 50, and `\"Invalid\"` otherwise.\n\nExample: `grade(70)` should return `\"Pass\"`.', 'def grade(score):\n    if score >= 50:\n        return \"Pass\"\n    elseif score >= 0:\n        return \"Fail\"\n    else:\n        return \"Invalid\"\n', 'def grade(score):\n    if score >= 50:\n        return \"Pass\"\n    elif score >= 0:\n        return \"Fail\"\n    else:\n        return \"Invalid\"\n', 'function', 'grade', 'Python\'s keywords are fixed, exact words - `elif`, `in`, `and`, `not`, and so on. Writing a keyword from a different language, or a plausible-looking variant, just gives Python an unrecognised word instead.', 'If you\'ve used another language before, double check Python\'s exact keyword spelling rather than assuming it matches.', NULL, 'published', '4165c3e494882aa07be32df718a6f42c732b38fb63b411a045bd58d396a5efeb', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (119, 'wrong-brackets', 11, 'Wrong Brackets', 9, 2, NULL, 'runtime', '`shout(word)` should return `word` in uppercase.\n\nExample: `shout(\"hello\")` should return `\"HELLO\"`.', 'def shout(word):\n    result = word.upper[]\n    return result\n', 'def shout(word):\n    result = word.upper()\n    return result\n', 'function', 'shout', '`()`, `[]` and `{}` all mean different things in Python: calling, indexing, and sets/dicts respectively. Using the wrong bracket type usually still runs - it just does something else entirely, or crashes with a type error.', 'When calling a method or function, it\'s always round brackets `()`, even with nothing inside them.', NULL, 'published', '1dded55d171d9ca033e6b09f4b052f442f49ba0de67f5f4fbedc5484e6a8dcdf', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (120, 'unfinished-function', 11, 'Unfinished Function', 10, 1, NULL, 'syntax', '`square(n)` should return `n` multiplied by itself.\n\nExample: `square(4)` should return `16`.', 'def square n:\n    return n * n\n', 'def square(n):\n    return n * n\n', 'function', 'square', 'A function definition always follows the same shape: `def`, a name, parentheses around the parameters, then a colon. Missing any one of those pieces means Python can\'t parse the line at all.', 'Check every `def` line has the full shape: `def name(params):`.', NULL, 'published', 'f456cd30cd94daf0c3da428fe63d1a3fb593d3534d590ab53dfb15cd3f9d136b', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (121, 'missing-colon-if', 11, 'Missing Colon: if', 11, 1, NULL, 'syntax', '`check_age(age)` should return `\"adult\"` if `age` is 18 or over, and `\"minor\"` otherwise.\n\nExample: `check_age(20)` should return `\"adult\"`.', 'def check_age(age):\n    if age >= 18\n        return \"adult\"\n    return \"minor\"\n', 'def check_age(age):\n    if age >= 18:\n        return \"adult\"\n    return \"minor\"\n', 'function', 'check_age', 'Every block header in Python ends with a colon, and `if` is no exception. Without it, Python has no signal that an indented body is about to follow.', 'Scan every `if` line the same way you\'d check a `def` line.', NULL, 'published', '76504dce4af5bdea316c76da40472bf4445c310761edffc0815cb8b6ffcdbf15', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (122, 'missing-colon-for', 11, 'Missing Colon: for', 12, 1, NULL, 'syntax', 'This program should print the sum of the numbers 0 to 4.\n\nExample output: `10`', 'total = 0\nfor i in range(5)\n    total += i\nprint(total)\n', 'total = 0\nfor i in range(5):\n    total += i\nprint(total)\n', 'script', NULL, '`for` loops are block headers just like `if` and `def` - they need a colon before their indented body.', 'Any line that\'s about to be followed by an indented block should end in `:`.', NULL, 'published', 'b26ec792871857e40dff306a5f8d2cb5c930ff73b9700491989a14697e412a71', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (123, 'missing-colon-while', 11, 'Missing Colon: while', 13, 1, NULL, 'syntax', 'This program should count a number down to 0 and print the final value.\n\nExample output: `0`', 'n = 5\nwhile n > 0\n    n -= 1\nprint(n)\n', 'n = 5\nwhile n > 0:\n    n -= 1\nprint(n)\n', 'script', NULL, '`while` loops follow the same rule as every other block header: condition, then colon, then an indented body.', 'Treat every loop header the same way you check `if` and `def` lines.', NULL, 'published', 'f57c5cfae51af756774beee921e88f1c22483fdd392cc395ed1e79044b681c9b', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (124, 'missing-colon-class', 11, 'Missing Colon: class', 14, 1, NULL, 'syntax', 'This program defines a `Dog` with a name, then prints that name.\n\nExample output: `Rex`', 'class Dog\n    def __init__(self, name):\n        self.name = name\n\nd = Dog(\"Rex\")\nprint(d.name)\n', 'class Dog:\n    def __init__(self, name):\n        self.name = name\n\nd = Dog(\"Rex\")\nprint(d.name)\n', 'script', NULL, 'A `class` definition is a block header too - name, then colon, then the indented body describing what the class contains.', 'Every block-opening keyword (`if`, `for`, `while`, `def`, `class`, `try`, `except`) needs a trailing colon - check all of them, not just the ones you expect to be wrong.', NULL, 'published', '0e1edb3efaa04f898bff77702a76b36c341985f38633c95c1a47b8fe7e0f28e3', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (125, 'missing-colon-except', 11, 'Missing Colon: except', 15, 1, NULL, 'syntax', '`safe_divide(a, b)` should return `a / b`, or `None` if `b` is 0.\n\nExample: `safe_divide(10, 2)` should return `5.0`.', 'def safe_divide(a, b):\n    try:\n        return a / b\n    except ZeroDivisionError\n        return None\n', 'def safe_divide(a, b):\n    try:\n        return a / b\n    except ZeroDivisionError:\n        return None\n', 'function', 'safe_divide', '`try` and `except` are a matched pair of block headers - both need their own colon.', 'In a try/except block, check both headers end in `:`, not just the `try`.', NULL, 'published', '1e4a831f245cc47e0ed4ede9487adcdca6650cb6ea0604949c81b967ba4f6570', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (126, 'unclosed-list', 11, 'Unclosed List', 16, 1, NULL, 'syntax', 'This program should print the sum of three scores.\n\nExample output: `60`', 'scores = [10, 20, 30\ntotal = sum(scores)\nprint(total)\n', 'scores = [10, 20, 30]\ntotal = sum(scores)\nprint(total)\n', 'script', NULL, 'Square brackets for a list need to come in a matching pair, exactly like round brackets for a function call.', 'Count opening and closing square brackets on any line that builds a list.', NULL, 'published', '5491ea2de18ea01970f0afc98807554e6e5e71faf9cc00f1d59174b674dacea3', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (127, 'unclosed-dict', 11, 'Unclosed Dict', 17, 1, NULL, 'syntax', 'This program should print the price of an apple.\n\nExample output: `1`', 'prices = {\"apple\": 1, \"pear\": 2\nprint(prices[\"apple\"])\n', 'prices = {\"apple\": 1, \"pear\": 2}\nprint(prices[\"apple\"])\n', 'script', NULL, 'Curly braces for a dictionary follow the same rule as any other bracket: every opening one needs a matching close.', 'Count curly braces in pairs the same way you would square or round brackets.', NULL, 'published', '17d751319f9da8f69be6a56ec3c9747d7f8a9be5821473c38c0394128140d461', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (128, 'mismatched-brackets', 11, 'Mismatched Brackets', 18, 1, NULL, 'syntax', 'This program should print a tuple of three numbers.\n\nExample output: `(1, 2, 3)`', 'values = (1, 2, 3]\nprint(values)\n', 'values = (1, 2, 3)\nprint(values)\n', 'script', NULL, 'Each bracket type opens and closes with its own kind - `(` with `)`, `[` with `]`, `{` with `}`. Python will tell you exactly which pair disagreed.', 'When you open with one bracket character, make sure you close with the same type.', NULL, 'published', '8a36be37ba306e6e0bddcb3fff035c7d0d5d97c5caff0f1010ee92c2e1937a43', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (129, 'unterminated-docstring', 11, 'Unterminated Docstring', 19, 1, NULL, 'syntax', 'This program should print a welcome message.\n\nExample output:\n```\nWelcome\nto the game\n```', 'message = \"\"\"Welcome\nto the game\nprint(message)\n', 'message = \"\"\"Welcome\nto the game\"\"\"\nprint(message)\n', 'script', NULL, 'Triple-quoted strings (used for multi-line text) still need a matching close - just three quote marks instead of one.', 'If a string spans multiple lines on purpose, double-check it\'s a triple-quoted one, properly closed.', NULL, 'published', '2247621d15b7136ede4093e56b224834d81bbbd09cea583488fde7157dcecd4b', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (130, 'fstring-missing-brace', 11, 'f-string Missing Brace', 20, 2, NULL, 'syntax', 'This program should print a greeting using a name.\n\nExample output: `Hello, Ada`', 'name = \"Ada\"\ngreeting = f\"Hello, {name\"\nprint(greeting)\n', 'name = \"Ada\"\ngreeting = f\"Hello, {name}\"\nprint(greeting)\n', 'script', NULL, 'An f-string (`f\"...\"`) lets you embed values using `{expression}`. Just like any other bracket, the curly braces inside it need to come in a matching pair.', 'Check every `{` inside an f-string has its own `}`.', NULL, 'published', '243e08deeef19466b9cc4babe6374106a4e97b1b039ccdc00c3d99ca4a288911', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (131, 'while-single-equals', 11, 'Single Equals in while', 21, 2, NULL, 'syntax', 'This program should loop while `status` is `\"pending\"`, and print how many times it looped.\n\nExample output: `3`', 'status = \"pending\"\ncount = 0\nwhile status = \"pending\":\n    count += 1\n    if count >= 3:\n        status = \"done\"\nprint(count)\n', 'status = \"pending\"\ncount = 0\nwhile status == \"pending\":\n    count += 1\n    if count >= 3:\n        status = \"done\"\nprint(count)\n', 'script', NULL, 'This is the same mix-up as a single `=` in an `if` condition, just in a `while` loop instead - any condition needs `==`, never a bare `=`.', 'Check every `while` condition for a stray single `=`, the same way you would an `if`.', NULL, 'published', '499a78722774a9b25b5f94c08120e157de8f00195fe3b4f2b60583a7106751f9', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (132, 'non-default-after-default', 11, 'Default Argument Order', 22, 2, NULL, 'syntax', '`greet(name, greeting=\"Hello\")` should return `greeting + \", \" + name`.\n\nExample: `greet(\"Ada\")` should return `\"Hello, Ada\"`.', 'def greet(greeting=\"Hello\", name):\n    return greeting + \", \" + name\n', 'def greet(name, greeting=\"Hello\"):\n    return greeting + \", \" + name\n', 'function', 'greet', 'Default parameter values have to come after every parameter that doesn\'t have one - otherwise Python couldn\'t tell which arguments you meant to skip.', 'When a function definition has default values, check they all sit at the end of the parameter list.', NULL, 'published', '4c2e85ea8f951017050913897e8e7f07a1c30d179090592704abe447e8d7660b', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (133, 'dict-equals-not-colon', 11, 'Dict Using = Instead of :', 23, 2, NULL, 'syntax', 'This program should print the price of an apple.\n\nExample output: `1`', 'prices = {\"apple\" = 1, \"pear\" = 2}\nprint(prices[\"apple\"])\n', 'prices = {\"apple\": 1, \"pear\": 2}\nprint(prices[\"apple\"])\n', 'script', NULL, 'A dictionary literal looks like `{key: value, key: value}`. The colon is what links each key to its value - `=` is for variable assignment, a different thing entirely.', 'Every entry inside a `{}` dictionary literal should use `:`, never `=`.', NULL, 'published', 'e512acdab6d70462065c1e981f855cc523754d69682249dbc2932428a566f366', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (134, 'reserved-keyword-as-name', 11, 'Reserved Word as a Name', 24, 2, NULL, 'syntax', 'This program should print a class name.\n\nExample output: `Year 12`', 'class = \"Year 12\"\nprint(class)\n', 'class_name = \"Year 12\"\nprint(class_name)\n', 'script', NULL, 'Python\'s keywords (`if`, `for`, `class`, `return`, and so on) are reserved - they always mean the same special thing, so they can never double up as a variable name.', 'If a `SyntaxError` points at a variable name that looks like an ordinary English word, check it isn\'t one of Python\'s keywords.', NULL, 'published', '80f105f086e78052008004dc516b7f0f1549192083f7ed153d5c4f4f158a2b27', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (135, 'orphaned-else-body', 11, 'Unindented else Body', 25, 2, NULL, 'syntax', '`check(n)` should return `\"positive\"` if `n` is greater than 0, and `\"non-positive\"` otherwise.\n\nExample: `check(5)` should return `\"positive\"`.', 'def check(n):\n    if n > 0:\n        result = \"positive\"\n    else:\n    result = \"non-positive\"\n    return result\n', 'def check(n):\n    if n > 0:\n        result = \"positive\"\n    else:\n        result = \"non-positive\"\n    return result\n', 'function', 'check', 'An `else:` needs its own indented body, lined up the same way as the `if` block\'s body - it\'s easy to fix the header and forget the line underneath.', 'Check the indentation of the line immediately under `else:`, not just the `else:` line itself.', NULL, 'published', '0903e446baa6999db3d26775711e91abdd423a4bbdebd5cc15a3aa24d543df83', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (136, 'missing-in-keyword', 11, 'Missing in Keyword', 26, 1, NULL, 'syntax', 'This program should print the sum of the numbers 0 to 4.\n\nExample output: `10`', 'total = 0\nfor i range(5):\n    total += i\nprint(total)\n', 'total = 0\nfor i in range(5):\n    total += i\nprint(total)\n', 'script', NULL, 'A `for` loop always has the same shape: `for`, a name for the current item, `in`, the thing being looped over, then a colon. Every piece is required.', 'Read every `for` line out loud as \"for ... in ...:\" and check each word is actually there.', NULL, 'published', '0b4e8888e385100a04c7441033c355fd299079bc75868f2af5cf8919ddb645e7', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (137, 'python2-except-syntax', 11, 'Old except Syntax', 27, 2, NULL, 'syntax', '`safe_int(text)` should return `text` converted to an integer, or `None` if that fails.\n\nExample: `safe_int(\"5\")` should return `5`.', 'def safe_int(text):\n    try:\n        return int(text)\n    except ValueError, e:\n        return None\n', 'def safe_int(text):\n    try:\n        return int(text)\n    except ValueError as e:\n        return None\n', 'function', 'safe_int', 'To give a caught exception a name in Python 3, use `except SomeError as name:`. The older comma-based form was removed when Python 2 support ended.', 'If you\'ve seen Python 2 examples online, double check `except` lines use `as`, not a comma.', NULL, 'published', '24c4b18b0b80f2d6e8d586d04007ddb8ce23f5ec60ddceb4a016f23e033d5258', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (138, 'trailing-backslash-string', 11, 'Trailing Backslash in a String', 28, 2, NULL, 'syntax', 'This program should print a file path.\n\nExample output: `C:\\Users\\notes`', 'path = \"C:\\Users\\notes\\\"\nprint(path)\n', 'path = r\"C:\\Users\\notes\"\nprint(path)\n', 'script', NULL, 'Inside an ordinary string, `\\` starts an escape sequence - a backslash right before the closing quote escapes that quote instead of ending the string. A raw string (`r\"...\"`) turns off escaping entirely, which is exactly what file paths usually want.', 'When a string contains Windows-style file paths, reach for a raw string (`r\"...\"`) to avoid backslash surprises.', NULL, 'published', 'fbfa2f86db99f66d514840478d0e89b49222e2fab94a4a0df8ebdd7fd7193ed8', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (139, 'return-outside-function', 11, 'return Outside a Function', 29, 2, NULL, 'syntax', 'This program should print a greeting.\n\nExample output: `Hello, Ada`', 'def greet(name):\n    print(\"Hello, \" + name)\nreturn \"done\"\n\ngreet(\"Ada\")\n', 'def greet(name):\n    print(\"Hello, \" + name)\n    return \"done\"\n\ngreet(\"Ada\")\n', 'script', NULL, '`return` sends a value back from a function call - it only makes sense while Python is inside a function, so writing one outside any function is a syntax error, not a logic one.', 'If a `return` line isn\'t indented inside a `def` block, that\'s the problem, not what it\'s trying to return.', NULL, 'published', 'b96eae99939105e9b8af3d9a372a0b6dad771d255c0a0c94eef6e4c5292d4842', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (140, 'break-outside-loop', 11, 'break Outside a Loop', 30, 2, NULL, 'syntax', 'This program should print each item in a list.\n\nExample output:\n```\n1\n2\n3\n```', 'items = [1, 2, 3]\nfor item in items:\n    print(item)\nbreak\n', 'items = [1, 2, 3]\nfor item in items:\n    print(item)\n', 'script', NULL, '`break` exits the loop it is written inside - it only makes sense while Python is inside a loop body, so one sitting outside any loop is a syntax error.', 'Check that every `break` (and `continue`) is indented inside a `for` or `while` body, not sitting next to it.', NULL, 'published', '3057de5b43326378727ed3f9494cdcf40aeb603406ef396a72de55e0b2ba2516', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (141, 'hyphen-in-variable-name', 11, 'Hyphen in a Variable Name', 31, 2, NULL, 'syntax', 'This program should print the number of students.\n\nExample output: `10`', 'student-count = 10\nprint(student-count)\n', 'student_count = 10\nprint(student_count)\n', 'script', NULL, 'Python variable names can contain letters, digits and underscores, but not hyphens - a hyphen is always read as a minus sign.', 'Join words in a variable name with an underscore (`_`), never a hyphen.', NULL, 'published', '3b0dee0222bd99e3929a5c4034bf90e1a079582a218db9d16d367fe4d23ac8a7', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (142, 'identifier-starts-with-digit', 11, 'Name Starting With a Digit', 32, 2, NULL, 'syntax', 'This program should print who came second.\n\nExample output: `Silver`', '2nd_place = \"Silver\"\nprint(2nd_place)\n', 'second_place = \"Silver\"\nprint(second_place)\n', 'script', NULL, 'Variable names must start with a letter or underscore - digits are only allowed after the first character.', 'If you want a name that starts with a number idea, spell it out in words instead (`second_place`, not `2nd_place`).', NULL, 'published', '3035b7fde0804cc335fa2e13426c0db064a9f67ff8f36167d8cf8502ae01cd63', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (143, 'extra-closing-bracket', 11, 'Extra Closing Bracket', 33, 1, NULL, 'syntax', 'This program should print the result of adding two numbers.\n\nExample output: `8`', 'total = (5 + 3))\nprint(total)\n', 'total = (5 + 3)\nprint(total)\n', 'script', NULL, 'Bracket matching works both ways - too many closing brackets is just as much a mismatch as too few, Python just notices it differently (there\'s nothing left open to match).', 'Count brackets in both directions: enough opens for every close, and no closes left over.', NULL, 'published', 'e1930bd27b9747e37b04c74b7802f08b77a3a059c10b914247f7696373282100', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (144, 'lambda-missing-colon', 11, 'Lambda Missing Colon', 34, 2, NULL, 'syntax', 'This program defines a `square` function using `lambda` and prints `square(4)`.\n\nExample output: `16`', 'square = lambda x x * x\nprint(square(4))\n', 'square = lambda x: x * x\nprint(square(4))\n', 'script', NULL, 'A `lambda` is a small, unnamed function written on one line: `lambda parameters: expression`. The colon is required, just like in a `def`.', 'Check every `lambda` has exactly one colon, separating its parameters from what it computes.', NULL, 'published', 'f1651baea398f6acf5f319f1a92885814c2e1846816d7aea627cdb5906021f5d', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (145, 'bad-line-continuation', 11, 'Broken Multi-line Expression', 35, 2, NULL, 'syntax', 'This program should print the sum of four numbers, split across two lines.\n\nExample output: `10`', 'total = 1 + 2 +\n3 + 4\nprint(total)\n', 'total = (1 + 2 +\n         3 + 4)\nprint(total)\n', 'script', NULL, 'Python normally ends a statement at the end of a line. To spread one expression over several lines, either wrap it in brackets (the usual way) or end each line with a backslash `\\` - without one of those, Python treats the next line as a brand new statement.', 'If an expression needs to span multiple lines, wrap it in parentheses rather than relying on a trailing backslash.', NULL, 'published', '2b8254e712e38e763733675fab9405397ff48da5cf837170283968817082e7ef', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (146, 'global-assignment-syntax', 11, 'global With an Assignment', 36, 2, NULL, 'syntax', 'This program should increment a counter and print it.\n\nExample output: `1`', 'counter = 0\n\ndef increment():\n    global counter = counter + 1\n\nincrement()\nprint(counter)\n', 'counter = 0\n\ndef increment():\n    global counter\n    counter = counter + 1\n\nincrement()\nprint(counter)\n', 'script', NULL, '`global name` tells Python \"inside this function, `name` means the module-level variable, not a new local one\" - it is purely a declaration, never an assignment, so it can never include `=`.', 'A `global` line should only ever contain the keyword and the name(s) - never an `=`.', NULL, 'published', 'a1a7a8ed3060a8e747c1a06162e62e9b5be517a8a1f8ef088e48c550094343a8', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (147, 'old-style-print', 11, 'Old-style print Statement', 37, 1, NULL, 'syntax', 'This program should print a message.\n\nExample output: `Game over`', 'print \"Game over\"\n', 'print(\"Game over\")\n', 'script', NULL, 'In older versions of Python, `print` was a special statement written without parentheses. Current Python made `print` an ordinary function, so it needs to be called like any other: with `()`.', 'If you see `print` followed directly by text with no parentheses in an example online, it\'s written for an old Python version.', NULL, 'published', 'b9c80996b45d429f03195b89dc15c369d51875be5c16d80394420503cac20f1a', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (148, 'missing-colon-elif', 11, 'Missing Colon: elif', 38, 1, NULL, 'syntax', '`grade(score)` should return `\"A\"` for 90+, `\"B\"` for 80-89, and `\"C\"` otherwise.\n\nExample: `grade(95)` should return `\"A\"`.', 'def grade(score):\n    if score >= 90:\n        return \"A\"\n    elif score >= 80\n        return \"B\"\n    else:\n        return \"C\"\n', 'def grade(score):\n    if score >= 90:\n        return \"A\"\n    elif score >= 80:\n        return \"B\"\n    else:\n        return \"C\"\n', 'function', 'grade', '`elif` is a block header in exactly the same way as `if` and `else` - every one of them needs its own colon.', 'In an if/elif/else chain, check every single header, not just the first one you see.', NULL, 'published', 'ffc021e70f4e5603af71f3faf71d21590149b642ae452b98e0a4b1dbdd0c282c', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (149, 'unterminated-fstring', 11, 'Unterminated f-string', 39, 1, NULL, 'syntax', 'This program should print a greeting using a name.\n\nExample output: `Hello, Ada`', 'name = \"Ada\"\nmessage = f\"Hello, {name}\nprint(message)\n', 'name = \"Ada\"\nmessage = f\"Hello, {name}\"\nprint(message)\n', 'script', NULL, 'An f-string still needs its outer quote marks to match, completely separately from the `{}` used inside it - both have to be checked.', 'Check an f-string in two passes: do the outer quotes match, and does every `{` have its `}`?', NULL, 'published', '19a83b5a2d46f7d28ae5502a641f01cb6f457f7ded9bba7ed054dbbd4ac9b752', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (150, 'mismatched-triple-quotes', 11, 'Mismatched Triple Quotes', 40, 2, NULL, 'syntax', 'This program should print a short poem.\n\nExample output:\n```\nRoses are red\nViolets are blue\n```', 'poem = \'\'\'Roses are red\nViolets are blue\"\"\"\nprint(poem)\n', 'poem = \'\'\'Roses are red\nViolets are blue\'\'\'\nprint(poem)\n', 'script', NULL, 'A triple-quoted string has to close with the exact same quote character it opened with - three of `\'` need three of `\'` to close, not three of `\"`.', 'When a multi-line string refuses to end, check the closing quote type matches the opening one, not just that there are three of them.', NULL, 'published', 'c8d2025bc1015128f16c1cf177d9418c580738ffa78310069bb33d8cf4216d8e', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (151, 'mystery-name', 12, 'Mystery Name', 1, 1, NULL, 'runtime', '`greet(name)` should return a greeting like `\"Hello, Ada!\"`.\n\nExample: `greet(\"Ada\")` should return `\"Hello, Ada!\"`.', 'def greet(name):\n    message = \"Hello, \" + nmae + \"!\"\n    return message\n', 'def greet(name):\n    message = \"Hello, \" + name + \"!\"\n    return message\n', 'function', 'greet', 'Python only recognises a name once it\'s been created - it doesn\'t guess what you meant. A typo in a variable name looks right to the eye but is a completely different, undefined name to Python, so it crashes as soon as that line runs.', 'When you see a `NameError`, compare the named variable letter-by-letter against where it was created.', NULL, 'published', '8fa305c3f67692f3251ec0c811c8fc4e5621645d9217c298a69935975e20e568', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (152, 'text-plus-number', 12, 'Text Plus Number', 2, 1, NULL, 'runtime', '`describe_age(age)` should return a string like `\"Age: 17\"`.\n\nExample: `describe_age(17)` should return `\"Age: 17\"`.', 'def describe_age(age):\n    return \"Age: \" + age\n', 'def describe_age(age):\n    return \"Age: \" + str(age)\n', 'function', 'describe_age', 'Python\'s `+` operator means something different depending on the types either side of it: joining for two strings, addition for two numbers. Mixing a string and a number directly leaves Python unable to decide which you meant.', 'Before joining a value to a string with `+`, check its type - numbers need `str()` first.', NULL, 'published', 'f7b12336f99fc507d5bc05fddefc57bc8d25268c01ee6c6b53c45ee8101aab0a', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (153, 'past-the-end', 12, 'Past the End', 3, 2, NULL, 'runtime', '`last_item(items)` should return the last item in the list `items`.\n\nExample: `last_item([1, 2, 3])` should return `3`.', 'def last_item(items):\n    return items[len(items)]\n', 'def last_item(items):\n    return items[len(items) - 1]\n', 'function', 'last_item', 'A list of length `n` has valid indexes `0` through `n - 1`. `len(items)` is one more than the last valid index, so using it directly always lands one step past the end.', 'Whenever you index with `len(...)`, check whether you need to subtract 1.', NULL, 'published', 'caad02ab90ce55e08a5e7e723ad378f40038bbe7b3e5ca04cd44ab2f0e4d7032', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (154, 'missing-key', 12, 'Missing Key', 4, 2, NULL, 'runtime', '`get_colour(fruit)` should return the colour of `fruit`, or `\"unknown\"` if it isn\'t in the list.\n\nExample: `get_colour(\"apple\")` should return `\"red\"`.', 'def get_colour(fruit):\n    colours = {\"apple\": \"red\", \"banana\": \"yellow\"}\n    return colours[fruit]\n', 'def get_colour(fruit):\n    colours = {\"apple\": \"red\", \"banana\": \"yellow\"}\n    return colours.get(fruit, \"unknown\")\n', 'function', 'get_colour', '`dict[key]` crashes with `KeyError` if the key isn\'t present. `.get(key, default)` checks safely and returns the default instead, which is almost always what you want when the key might be missing.', 'Any time you index a dictionary with something that didn\'t come from iterating its own keys, consider `.get()` instead.', NULL, 'published', '7a07ad9f1998bcfe1fc61746b75d145ec28501af4c6c9e5b60b9e8cf76785710', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (155, 'divide-by-nothing', 12, 'Divide by Nothing', 5, 2, NULL, 'runtime', '`average(nums)` should return the mean of the numbers in `nums`, or `0` if the list is empty.\n\nExample: `average([2, 4, 6])` should return `4`.', 'def average(nums):\n    return sum(nums) / len(nums)\n', 'def average(nums):\n    if len(nums) == 0:\n        return 0\n    return sum(nums) / len(nums)\n', 'function', 'average', 'Dividing by zero always crashes in Python. Any time a divisor comes from a count that could be zero - like the length of a list - it needs a guard before the division runs.', 'Ask \"could this count ever be zero?\" for every division, and test with an empty input to check.', NULL, 'published', '6a947c268ccf7c3d800b60c4a85dfab8ae80bfd21a9285f414996e3547dc3211', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (156, 'not-a-number', 12, 'Not a Number', 6, 2, NULL, 'runtime', '`to_whole(text)` should convert a piece of text like `\"3\"` or `\"3.5\"` into a whole number, rounding down.\n\nExample: `to_whole(\"3.5\")` should return `3`.', 'def to_whole(text):\n    return int(text)\n', 'def to_whole(text):\n    return int(float(text))\n', 'function', 'to_whole', '`int(text)` requires the text to look like a whole number already. Text containing a decimal point needs `float()` first, which `int()` can then round down.', 'If text might contain a decimal point, convert with `float()` before `int()`.', NULL, 'published', '5c3e19597c15f27c03f473d740a31976a227a88cbfcf424f4f5b791efbecccb3', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (157, 'nothing-returned', 12, 'Nothing Returned', 7, 1, NULL, 'runtime', '`add(a, b)` should return the sum of `a` and `b`.\n\nExample: `add(2, 3)` should return `5`.', 'def add(a, b):\n    total = a + b\n', 'def add(a, b):\n    total = a + b\n    return total\n', 'function', 'add', 'A function that doesn\'t hit a `return` statement gives back `None` automatically - computing a value inside a function does nothing on its own unless it\'s returned.', 'If a function\'s result always seems to be `None`, check it actually has a `return` on the path that runs.', NULL, 'published', 'cb7de63f179a96347c859f484fc71d81bfe82866e7a0278e0487285e7d944785', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (158, 'local-trouble', 12, 'Local Trouble', 8, 3, NULL, 'runtime', 'This program keeps a running `count` and should print `1` then `2`.\n\nExample output:\n```\n1\n2\n```', 'count = 0\n\ndef increment():\n    count = count + 1\n    return count\n\nprint(increment())\nprint(increment())\n', 'count = 0\n\ndef increment():\n    global count\n    count = count + 1\n    return count\n\nprint(increment())\nprint(increment())\n', 'script', NULL, 'Python decides whether a name is local or global by scanning the whole function for assignments - not line by line. Assigning to `count` anywhere inside `increment` makes every use of `count` in that function local, which crashes if it reads `count` before any local assignment has happened.', 'If a function needs to update a variable from outside it, add `global name` at the top of the function.', NULL, 'published', 'd9a9d7decdf3153798abc37b14f1cc77e36d4fd961904c0ceb07ee2610e2a926', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (159, 'string-that-looked-like-a-number', 12, 'The String That Looked Like a Number', 9, 2, NULL, 'runtime', '`total_cost(price_text, quantity)` should return the cost of `quantity` items at the price given in `price_text` (a string, as if it came from `input()`), plus a flat ┬ú5 delivery fee.\n\nExample: `total_cost(\"4\", 3)` should return `17`.', 'def total_cost(price_text, quantity):\n    return price_text * quantity + 5\n', 'def total_cost(price_text, quantity):\n    return int(price_text) * quantity + 5\n', 'function', 'total_cost', 'Text that *looks* like a number is still text until it\'s explicitly converted. `input()` always returns a string, which is exactly why this bug is so common in real programs - multiplying text by a number repeats it instead of doing arithmetic.', 'If a value could have come from `input()` or another text source, check it\'s been converted before doing arithmetic with it.', NULL, 'published', '1891e8a9c2e87fabf02beb2f206dd3f4f4c2fbb672895e3bf010f4b5ee340c11', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (160, 'wrong-number-of-arguments', 12, 'Wrong Number of Arguments', 10, 2, NULL, 'runtime', '`greet(first_name, last_name)` should return a greeting using both names.\n\nExample: `greet(\"Ada\", \"Lovelace\")` should return `\"Hello, Ada Lovelace!\"`.', 'def greet(name):\n    return \"Hello, \" + name + \"!\"\n', 'def greet(first_name, last_name):\n    return \"Hello, \" + first_name + \" \" + last_name + \"!\"\n', 'function', 'greet', 'A function\'s parameter list is a contract: every call must supply exactly the arguments it\'s defined to accept (unless defaults are used). A mismatch between how a function is defined and how it\'s meant to be used is a `TypeError` waiting to happen.', 'When a `TypeError` mentions argument counts, compare the `def` line to every place the function is called or tested.', NULL, 'published', 'ca942b4f30ef35e8da48add6eea2264f5a7841b772f47b242f43135b8c443a4d', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (161, 'attr-error-string-method', 12, 'The Method That Never Was', 11, 1, NULL, 'runtime', '`shout_name(name)` should return `name` in uppercase.\n\nExample: `shout_name(\"ada\")` should return `\"ADA\"`.', 'def shout_name(name):\n    return name.uppercase()\n', 'def shout_name(name):\n    return name.upper()\n', 'function', 'shout_name', '`AttributeError` means the object exists, but it doesn\'t have the attribute or method you asked for - usually because of a typo or a method name remembered from a different language.', 'When you see `AttributeError: \'...\' object has no attribute \'...\'`, check the exact spelling against Python\'s real method names.', NULL, 'published', '3843548672553c13daf60c6fbf5fff4242c9a2fdd7e76429bfd2d668aa2f3e10', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (162, 'attr-error-none', 12, 'A Function That Forgot to Return', 12, 2, NULL, 'runtime', '`greeting(record)` should return a greeting using `record[\"name\"]` in uppercase, or `\"UNKNOWN\"` if there is no name.\n\nExample: `greeting({\"name\": \"ada\"})` should return `\"ADA\"`.', 'def get_name(record):\n    if record.get(\"name\"):\n        return record[\"name\"]\n\ndef greeting(record):\n    name = get_name(record)\n    return name.upper()\n', 'def get_name(record):\n    if record.get(\"name\"):\n        return record[\"name\"]\n    return \"unknown\"\n\ndef greeting(record):\n    name = get_name(record)\n    return name.upper()\n', 'function', 'greeting', 'A function with no matching `return` for some path implicitly returns `None`. That `None` is a perfectly valid value right up until something tries to use it as if it were the real thing - here, calling `.upper()` on it.', 'If an `AttributeError` mentions `NoneType`, trace backwards to find where that `None` actually came from - it\'s rarely the line that crashed.', NULL, 'published', '296b01e80612946f7173ed2351e4460460fc64951d2e6ec21540f2af668c3932', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (163, 'typeerror-list-not-callable', 12, 'Calling a List', 13, 1, NULL, 'runtime', '`get_first(totals)` should return the first item in `totals`.\n\nExample: `get_first([10, 20, 30])` should return `10`.', 'def get_first(totals):\n    return totals(0)\n', 'def get_first(totals):\n    return totals[0]\n', 'function', 'get_first', 'This runs because the syntax is valid - `totals(0)` is a legal-looking function call. It only fails once Python actually tries to call a list as if it were a function.', 'A `TypeError` mentioning \"not callable\" almost always means `()` was used where `[]` was meant.', NULL, 'published', 'e0e246107c8f6c7088114595dbbae0d02318bcfc67a05d3804094e91c43a4a9c', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (164, 'typeerror-int-not-iterable', 12, 'Looping Over a Number', 14, 1, NULL, 'runtime', '`digits_of(n)` should return a list of the digits of `n` as characters.\n\nExample: `digits_of(123)` should return `[\"1\", \"2\", \"3\"]`.', 'def digits_of(n):\n    result = []\n    for digit in n:\n        result.append(digit)\n    return result\n', 'def digits_of(n):\n    result = []\n    for digit in str(n):\n        result.append(digit)\n    return result\n', 'function', 'digits_of', 'A `for` loop needs something iterable - a sequence of values to step through. A whole number is a single value, not a sequence, so Python has nothing to loop over until you convert it to something that is, like a string.', '\"not iterable\" in the error means check what type the thing after `in` actually is.', NULL, 'published', 'e38e9db5521eb8755e4aacd505d9d3842bd4f40c1443a4b015b2f58685d70832', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (165, 'typeerror-int-not-subscriptable', 12, 'Indexing a Number', 15, 1, NULL, 'runtime', '`get_units(n)` should return the units (last) digit of `n`, as an integer.\n\nExample: `get_units(123)` should return `3`.', 'def get_units(n):\n    return n[-1]\n', 'def get_units(n):\n    return int(str(n)[-1])\n', 'function', 'get_units', '\"not subscriptable\" means the object does not support `[]` indexing at all. Converting between types - here, number to string and back - is how you get at individual digits.', 'If `[]` on a number crashes, convert it to a string first.', NULL, 'published', 'b7805e8e727782d2cbd7dbbc8db8e84c92b7fa15fcb80c95c3cdcc3ab8185036', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (166, 'indexerror-negative-overflow', 12, 'Negative Index Out of Range', 16, 2, NULL, 'runtime', '`second_to_last(scores)` should return the second-to-last score, or `None` if there are fewer than two scores.\n\nExample: `second_to_last([10, 20, 30])` should return `20`.', 'def second_to_last(scores):\n    return scores[-2]\n', 'def second_to_last(scores):\n    if len(scores) < 2:\n        return None\n    return scores[-2]\n', 'function', 'second_to_last', 'Negative indexes (`-1`, `-2`, ...) count backwards from the end, but they are just as capable of going out of range as positive ones - a one-item list has no `-2`.', 'Before using a negative index, check the collection is actually long enough for it.', NULL, 'published', 'b0cf7be6ce94ebd63d6386ece02041df3f64cbac374a90bf0e2175008bb60275', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (167, 'keyerror-pop-missing', 12, 'Popping a Missing Key', 17, 1, NULL, 'runtime', '`remove_item(cart, item)` should remove `item` from the `cart` dictionary if present, and return the dictionary either way.\n\nExample: `remove_item({\"apple\": 1, \"pear\": 2}, \"apple\")` should return `{\"pear\": 2}`.', 'def remove_item(cart, item):\n    cart.pop(item)\n    return cart\n', 'def remove_item(cart, item):\n    if item in cart:\n        cart.pop(item)\n    return cart\n', 'function', 'remove_item', '`.pop()` removes and returns a value by key, but like direct indexing, it crashes if the key doesn\'t exist. Checking membership first (or using `.pop(key, default)`) avoids the crash.', 'Before popping a dictionary key that might not exist, check for it first or supply a default.', NULL, 'published', 'db67b545faae08e3d26324d2d8cb882be85d6ddd54e3622b06335fb5cc102f93', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (168, 'indexerror-pop-empty', 12, 'Popping From an Empty List', 18, 1, NULL, 'runtime', '`take_turn(queue)` should remove and return the first item in `queue`, or `None` if `queue` is empty.\n\nExample: `take_turn([1, 2, 3])` should return `1`.', 'def take_turn(queue):\n    return queue.pop(0)\n', 'def take_turn(queue):\n    if not queue:\n        return None\n    return queue.pop(0)\n', 'function', 'take_turn', 'Removing an item by position only works if that position actually exists - an empty list has no position `0`, so `.pop(0)` crashes exactly like indexing past the end would.', 'Before popping from a list that might be empty, check it first.', NULL, 'published', '4dc496ea3629f1f210fb78e3ed1865f3e146f7a62aa3770cbf46b73848182504', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (169, 'typeerror-len-on-int', 12, 'Length of a Number', 19, 1, NULL, 'runtime', '`count_digits(n)` should return how many digits `n` has.\n\nExample: `count_digits(123)` should return `3`.', 'def count_digits(n):\n    return len(n)\n', 'def count_digits(n):\n    return len(str(n))\n', 'function', 'count_digits', '`len()` counts the items in a sequence. A number on its own is not a sequence - converting it to a string first turns it into one, letting you count its digits.', '\"object of type \'int\' has no len()\" means you need a conversion before measuring length.', NULL, 'published', '9e9bf39ebce2fd818b52e419ea739df2e93b2055314bc62d9a02a646ac7187bf', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (170, 'valueerror-int-with-text', 12, 'Parsing a Number With Extra Text', 20, 2, NULL, 'runtime', '`parse_age(text)` should return the age as an integer, from text like `\"25 years\"`.\n\nExample: `parse_age(\"25 years\")` should return `25`.', 'def parse_age(text):\n    return int(text)\n', 'def parse_age(text):\n    return int(text.split()[0])\n', 'function', 'parse_age', '`int(text)` expects `text` to be exactly a number, with nothing else around it. Real-world text often needs cleaning up - splitting, stripping, or slicing - before it is safe to convert.', 'If a `ValueError` happens converting user text to a number, check for extra characters sneaking in alongside the digits.', NULL, 'published', '51f31d036c9fbb4d74661f4227dfb82bc660cc3a12444a9b2e99756f1a75dae0', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (171, 'typeerror-list-plus-int', 12, 'Adding a Number to a List', 21, 2, NULL, 'runtime', '`add_bonus(scores, bonus)` should return a new list with `bonus` added to every score.\n\nExample: `add_bonus([1, 2, 3], 5)` should return `[6, 7, 8]`.', 'def add_bonus(scores, bonus):\n    return scores + bonus\n', 'def add_bonus(scores, bonus):\n    return [s + bonus for s in scores]\n', 'function', 'add_bonus', '`+` means different things for different types: numeric addition for numbers, concatenation for lists (list-plus-list only). Mixing a list with a plain number is not defined.', 'If you want to apply an operation to every item in a list, use a loop or comprehension - `+` on the list itself concatenates, it does not map.', NULL, 'published', 'e6444acdde98fecb6f592ed3a711a42182f32d843935bafb79f104eebdbe9866', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (172, 'typeerror-compare-str-int', 12, 'Comparing a Number to Text', 22, 1, NULL, 'runtime', '`is_adult(age)` should return `True` if `age` is 18 or over.\n\nExample: `is_adult(20)` should return `True`.', 'def is_adult(age):\n    return age >= \"18\"\n', 'def is_adult(age):\n    return age >= 18\n', 'function', 'is_adult', 'A stray pair of quote marks turns a number into text. Python won\'t guess which one you meant when comparing sizes - `int` and `str` just are not comparable that way.', 'If a comparison crashes with a type error, check both sides are actually the type you think they are.', NULL, 'published', '0fe7bd5d10fd37ea9fccd3a6ba84cf4e74613a1bdabbd5b848d997abee5ae077', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (173, 'attributeerror-method-typo', 12, 'A Typo in a Method Name', 23, 1, NULL, 'runtime', '`add_item(cart, item)` should add `item` to the end of the `cart` list and return it.\n\nExample: `add_item([], \"apple\")` should return `[\"apple\"]`.', 'def add_item(cart, item):\n    cart.appned(item)\n    return cart\n', 'def add_item(cart, item):\n    cart.append(item)\n    return cart\n', 'function', 'add_item', 'A single swapped letter is enough to turn a real method into an undefined one. The error message spells out the exact (wrong) name it tried to find - comparing it letter by letter against the real method usually reveals the typo instantly.', 'When an `AttributeError` names a method that *looks* right, check it letter by letter - it\'s often one character off.', NULL, 'published', '5b27ce91d9d0a9010e58e8214ff3bc2e7ebc6ce5a8819ae96d21b14667f2ab2b', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (174, 'indexerror-while-loop', 12, 'One Step Too Far in a while Loop', 24, 2, NULL, 'runtime', '`find_first_negative(numbers)` should return the first negative number in the list, or `None` if there isn\'t one.\n\nExample: `find_first_negative([1, -2, 3])` should return `-2`.', 'def find_first_negative(numbers):\n    i = 0\n    while i <= len(numbers):\n        if numbers[i] < 0:\n            return numbers[i]\n        i += 1\n    return None\n', 'def find_first_negative(numbers):\n    i = 0\n    while i < len(numbers):\n        if numbers[i] < 0:\n            return numbers[i]\n        i += 1\n    return None\n', 'function', 'find_first_negative', 'A `while` loop walking through a list by index needs to stop one short of the list\'s length, not at it - `len(numbers)` is one past the last valid index.', 'In a manual `while` loop over indexes, double-check the boundary: is it `<` or `<=`, and is that actually correct?', NULL, 'published', 'ac4d9798eba7a4a244b66846796e405ae7446c17017e81a72b62329f6bc737c3', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (175, 'unboundlocal-leftover-print', 12, 'Using a Variable Before It Exists', 25, 3, NULL, 'runtime', '`total_with_tax(price)` should return `price` multiplied by 1.2.\n\nExample: `total_with_tax(100)` should return `120.0`.', 'def total_with_tax(price):\n    print(total)\n    total = price * 1.2\n    return total\n', 'def total_with_tax(price):\n    total = price * 1.2\n    return total\n', 'function', 'total_with_tax', 'Python decides whether a name is local to a function by scanning the *whole* function body for an assignment to it - not just the lines before the one you\'re looking at. If it\'s assigned anywhere in the function, every use of that name in that function is local, even before the assignment runs.', '`UnboundLocalError` almost always means a variable is assigned somewhere later in the same function - look for a leftover line that runs before that assignment.', NULL, 'published', 'dd59387b7706fbd23e624d187189fd4d6f065852f269c3372b0c3eced64c6361', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (176, 'wrong-args-round', 12, 'Too Many Arguments to round()', 26, 1, NULL, 'runtime', '`round_price(price)` should return `price` rounded to 2 decimal places.\n\nExample: `round_price(19.995)` should return `20.0`.', 'def round_price(price):\n    return round(price, 2, 10)\n', 'def round_price(price):\n    return round(price, 2)\n', 'function', 'round_price', 'Every function - built-in or your own - has a fixed set of parameters it accepts. Supplying more arguments than it is written to take is a `TypeError`, not a logic bug.', 'If a `TypeError` mentions \"takes at most N arguments\", count exactly how many you actually passed.', NULL, 'published', '7ff2436f102ea750ad6e9175261bc6521b13f01bfe0870ef9fd2dbbe3ca63720', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (177, 'keyerror-grade-lookup', 12, 'A Subject That Was Never Taken', 27, 1, NULL, 'runtime', '`get_grade(grades, subject)` should return the grade for `subject`, or `\"Not taken\"` if it is not in `grades`.\n\nExample: `get_grade({\"Maths\": \"A\"}, \"Maths\")` should return `\"A\"`.', 'def get_grade(grades, subject):\n    return grades[subject]\n', 'def get_grade(grades, subject):\n    return grades.get(subject, \"Not taken\")\n', 'function', 'get_grade', '`dict[key]` crashes if the key is missing; `dict.get(key, default)` returns `default` instead. Whenever a missing key is a normal, expected possibility (not a bug), `.get()` is the safer choice.', 'If a dictionary lookup could reasonably be missing, use `.get()` with a sensible default rather than direct indexing.', NULL, 'published', '06b873dad0e8bf8d4be841f4933b9219c37362f7a2e9f44f157031a8a0d33925', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (178, 'typeerror-unhashable-list-key', 12, 'Using a List as a Dictionary Key', 28, 2, NULL, 'runtime', '`tag_route(stops)` should record `stops` as a visited route and return how many distinct routes have been recorded so far (always `1` for a single call).\n\nExample: `tag_route([1, 2, 3])` should return `1`.', 'def tag_route(stops):\n    visited = {}\n    visited[stops] = True\n    return len(visited)\n', 'def tag_route(stops):\n    visited = {}\n    visited[tuple(stops)] = True\n    return len(visited)\n', 'function', 'tag_route', 'Dictionary keys must be hashable, which roughly means \"never changes after creation\". Lists can be modified in place, so they\'re explicitly disallowed as keys - tuples, which look similar but can\'t be changed, work fine instead.', '\"unhashable type: \'list\'\" means swap the list for a tuple if you need to use it as a dictionary key.', NULL, 'published', 'e2743624dd6d0ffc429653b807ae6b2f8685a398527d9c7ba610f09966ccfe90', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (179, 'indexerror-string-index', 12, 'One Past the Last Character', 29, 1, NULL, 'runtime', '`last_char(word)` should return the last character of `word`.\n\nExample: `last_char(\"hello\")` should return `\"o\"`.', 'def last_char(word):\n    return word[len(word)]\n', 'def last_char(word):\n    return word[len(word) - 1]\n', 'function', 'last_char', 'A string of length `n` has valid indexes `0` through `n - 1`. Forgetting the `-1` is one of the most common off-by-one mistakes there is.', 'Whenever you index using `len(...)` directly, check whether you actually need `len(...) - 1`.', NULL, 'published', 'b90b4a0a8e2131caa52079dc2df4ae150e254275768a2f1d8f18b0e0d37e17ad', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (180, 'zerodivision-average-empty', 12, 'Average of an Empty List', 30, 1, NULL, 'runtime', '`average(numbers)` should return the mean of `numbers`, or `0` if the list is empty.\n\nExample: `average([2, 4, 6])` should return `4.0`.', 'def average(numbers):\n    return sum(numbers) / len(numbers)\n', 'def average(numbers):\n    if not numbers:\n        return 0\n    return sum(numbers) / len(numbers)\n', 'function', 'average', 'Any division whose denominator is computed (like `len(numbers)`) rather than written as a literal needs a guard for the case where that denominator turns out to be zero.', 'Whenever you divide by something computed rather than a fixed number, ask \"could this ever be zero?\"', NULL, 'published', '067d236e351433faab9e6e80bd7e2e630ff105a89d5847a0f9f82985eb28bfb5', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (181, 'nameerror-function-order', 12, 'Called Before It Existed', 31, 2, NULL, 'runtime', 'This program should print `Game started`.\n\nExample output: `Game started`', 'def run_game():\n    return \"preparing\"\n\nresult = run_game()\nprint(start_game())\n\ndef start_game():\n    return \"Game started\"\n', 'def run_game():\n    return \"preparing\"\n\ndef start_game():\n    return \"Game started\"\n\nresult = run_game()\nprint(start_game())\n', 'script', NULL, 'Defining a function doesn\'t make it exist at every point in the file - only from the moment Python actually runs that `def` line onwards. Calling it any earlier is a plain `NameError`, the same as any other undefined name.', 'If a `NameError` names something that is clearly defined later in the file, check the actual order the lines run in, not just where things appear on the page.', NULL, 'published', 'e026991c1370db2300ec827ee301d087b28c3bdb2badf764ce8d6ed508ebf6d6', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (182, 'attributeerror-sort-on-string', 12, 'Sorting a String in Place', 32, 1, NULL, 'runtime', '`sorted_letters(word)` should return the letters of `word` sorted alphabetically, as a string.\n\nExample: `sorted_letters(\"bca\")` should return `\"abc\"`.', 'def sorted_letters(word):\n    word.sort()\n    return word\n', 'def sorted_letters(word):\n    return \"\".join(sorted(word))\n', 'function', 'sorted_letters', '`.sort()` is a list method that rearranges a list in place - it relies on the list being mutable. Strings are immutable, so there is no in-place sort; `sorted(...)` instead returns a brand new sorted sequence.', 'If you want a sorted version of a string, use `sorted()` (which returns a list) and join it back together - don\'t look for an in-place `.sort()`.', NULL, 'published', 'c5bcea7d925682f40cad57f27fac7ff23df9d53c5d20a0a2e1cd8b1541e4b8ec', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (183, 'recursion-no-base-case', 12, 'Recursion With No Way Out', 33, 2, NULL, 'runtime', '`countdown(n)` should count down to 0 and return `\"Liftoff!\"`.\n\nExample: `countdown(3)` should return `\"Liftoff!\"`.', 'def countdown(n):\n    return countdown(n - 1)\n', 'def countdown(n):\n    if n <= 0:\n        return \"Liftoff!\"\n    return countdown(n - 1)\n', 'function', 'countdown', 'Every recursive function needs a base case - a condition where it stops calling itself and just returns a value directly. Without one, it recurses until Python hits its recursion limit and raises `RecursionError`.', 'When you write a recursive function, write the base case first, before the recursive call.', NULL, 'published', '1bb076a156f1bf23b522679be789464afbe52ce4ac9559f9d872ef51a004d1bc', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (184, 'stopiteration-manual-next', 12, 'Asking an Iterator for Too Much', 34, 2, NULL, 'runtime', '`first_two(items)` should return the first two items of `items` as a list.\n\nExample: `first_two([1, 2, 3])` should return `[1, 2]`.', 'def first_two(items):\n    it = iter(items)\n    a = next(it)\n    b = next(it)\n    c = next(it)\n    return [a, b, c]\n', 'def first_two(items):\n    it = iter(items)\n    a = next(it)\n    b = next(it)\n    return [a, b]\n', 'function', 'first_two', 'An iterator gives out one value per call to `next()`, and raises `StopIteration` once it has nothing left. Asking for more items than exist is a crash, not a graceful empty result.', 'Count exactly how many times you call `next()` against how many items you actually expect to be there.', NULL, 'published', 'bf24e7ddd6047eca7344dd85fb711019a6c666025fdc35dc3a0c02bd4487518c', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (185, 'zerodivision-modulo-zero', 12, 'Modulo by Zero', 35, 1, NULL, 'runtime', '`is_even_group(n, group_size)` should return whether `n` divides evenly into `group_size`-sized groups, or `False` if `group_size` is 0.\n\nExample: `is_even_group(10, 5)` should return `True`.', 'def is_even_group(n, group_size):\n    return n % group_size == 0\n', 'def is_even_group(n, group_size):\n    if group_size == 0:\n        return False\n    return n % group_size == 0\n', 'function', 'is_even_group', 'Modulo (`%`) computes a remainder, which is undefined when dividing by zero - it raises the exact same `ZeroDivisionError` as ordinary division.', 'Don\'t forget that `%` needs a zero-guard too, not just `/`.', NULL, 'published', 'fa818e8d297a85f84b51e8b33efb635e0d21bd2a4d5a308a7f01cfd3c458fb36', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (186, 'typeerror-mixed-type-sum', 12, 'Starting a Total With the Wrong Type', 36, 2, NULL, 'runtime', '`total_price(prices)` should return the sum of the numbers in `prices`.\n\nExample: `total_price([10, 20, 30])` should return `60`.', 'def total_price(prices):\n    total = \"\"\n    for p in prices:\n        total += p\n    return total\n', 'def total_price(prices):\n    total = 0\n    for p in prices:\n        total += p\n    return total\n', 'function', 'total_price', 'An accumulator\'s starting value has to be the identity for whatever you\'re accumulating - `0` for adding numbers, `\"\"` for joining text, `[]` for building a list. Mixing them up crashes on the first step.', 'When a `TypeError` mentions concatenation on the very first loop iteration, check the accumulator\'s starting value against what you\'re actually adding to it.', NULL, 'published', '45e13bcef64861947c2a2cf83a30ee8982bc946ce07cb9dd19ea1c67d2b137d6', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (187, 'attributeerror-keys-on-list', 12, 'Treating a List Like a Dictionary', 37, 1, NULL, 'runtime', '`unique_names(students)` should return the names in `students`, keeping only the first occurrence of each.\n\nExample: `unique_names([\"Ada\", \"Sam\", \"Ada\"])` should return `[\"Ada\", \"Sam\"]`.', 'def unique_names(students):\n    return students.keys()\n', 'def unique_names(students):\n    seen = []\n    for s in students:\n        if s not in seen:\n            seen.append(s)\n    return seen\n', 'function', 'unique_names', 'It\'s easy to reach for a dictionary method out of habit when working with any collection - but lists and dictionaries have genuinely different methods, because they store data differently.', 'If an `AttributeError` names a dictionary-only method, double check the variable is actually a dictionary, not a list.', NULL, 'published', '5fd8fb51edae223b64a743151fd4629f84f7cd2f9f85af6f11e55b4e404fbf5a', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (188, 'typeerror-unexpected-keyword', 12, 'The Wrong Keyword Argument Name', 38, 3, NULL, 'runtime', '`checkout(price, tax)` should return `price + tax`.\n\nExample: `checkout(10, 2)` should return `12`.', 'def compute_total(price, tax):\n    return price + tax\n\ndef checkout(price, tax):\n    return compute_total(prices=price, tax=tax)\n', 'def compute_total(price, tax):\n    return price + tax\n\ndef checkout(price, tax):\n    return compute_total(price=price, tax=tax)\n', 'function', 'checkout', 'When calling a function with `name=value` keyword arguments, `name` must exactly match one of the parameter names in that function\'s definition - a near-miss spelling is just as invalid as a completely wrong name.', 'When a keyword argument is \"unexpected\", go back to the function definition and compare its exact parameter names.', NULL, 'published', '74c32c4f2d73df3fee95429e6a82296c4816c9a8e122d0c30cdd1dfcc5720a89', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (189, 'valueerror-unpack-too-many', 12, 'Too Many Values to Unpack', 39, 2, NULL, 'runtime', '`split_name(full_name)` should return `[last_word, first_word]` from a space-separated name.\n\nExample: `split_name(\"Ada Lovelace\")` should return `[\"Lovelace\", \"Ada\"]`.', 'def split_name(full_name):\n    first, last = full_name.split(\" \")\n    return [last, first]\n', 'def split_name(full_name):\n    parts = full_name.split(\" \")\n    first = parts[0]\n    last = parts[-1]\n    return [last, first]\n', 'function', 'split_name', 'Unpacking (`a, b = something`) requires exactly as many values on the right as names on the left. It is a convenient shorthand, but only safe when you are certain of the exact count.', 'If unpacking might receive a different number of values than expected, split into a list first and index into it instead.', NULL, 'published', 'c73f1ecf0f2e269ad926b3777e1b1bffbc5254a1f39d1aaa33b349cde35b3092', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (190, 'valueerror-unpack-too-few', 12, 'Not Enough Values to Unpack', 40, 2, NULL, 'runtime', '`get_coordinates(point)` should return `[x, y]` from a 2-item point.\n\nExample: `get_coordinates([3, 4])` should return `[3, 4]`.', 'def get_coordinates(point):\n    x, y, z = point\n    return [x, y]\n', 'def get_coordinates(point):\n    x, y = point\n    return [x, y]\n', 'function', 'get_coordinates', 'Just as unpacking fails with too many values, it fails the other way too - not enough values for the number of names you are trying to fill.', 'Before unpacking, check the number of names on the left genuinely matches the number of values you expect on the right.', NULL, 'published', 'dc98d676d05fa82c25f000c11e0c897a2a439e8b610b00e93832ed73c0d34a09', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (191, 'sum-to-n-off-by-one', 13, 'The Missing Number', 1, 2, NULL, 'logic', '`sum_to(n)` should return the sum of all whole numbers from 1 up to and including `n`.\n\nExample: `sum_to(4)` should return `10` (1 + 2 + 3 + 4).', 'def sum_to(n):\n    total = 0\n    for i in range(1, n):\n        total += i\n    return total\n', 'def sum_to(n):\n    total = 0\n    for i in range(1, n + 1):\n        total += i\n    return total\n', 'function', 'sum_to', 'Python\'s `range(a, b)` includes `a` but excludes `b` - a deliberate design choice that trips almost everyone up at least once. Whenever a loop should include the upper value, add one to the second argument.', 'Any time you loop with `range`, check the first and last values by hand with a tiny input like `n = 1` or `n = 2`.', 'What do you think `sum_to(4)` returns? Write it down before you run anything.', 'published', 'c2cce40ef041d810d878a68da015a43af8c9b0d5a1a112bad5741ddb7f2f0d96', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (192, 'fence-posts', 13, 'Fence Posts', 2, 2, NULL, 'logic', 'A straight fence needs one post at the start, then one more post per section. `posts_needed(sections)` should return the number of posts needed for a fence with that many sections.\n\nExample: `posts_needed(4)` should return `5`.', 'def posts_needed(sections):\n    return sections\n', 'def posts_needed(sections):\n    return sections + 1\n', 'function', 'posts_needed', 'This is the classic \"fencepost\" off-by-one: counting the gaps (sections) isn\'t the same as counting the boundaries between them (posts). Drawing a tiny example (1 or 2 sections) on paper makes the relationship obvious.', 'For anything involving counting items versus counting the gaps between them, sketch a tiny example by hand first.', 'If a fence has 4 sections, how many posts does it need? Write your answer down before running anything.', 'published', '4fff50b46110b3c2d452ba52d1b79b80c4a34859cf195784e062178f2c4aa7fb', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (193, 'half-a-result', 13, 'Half a Result', 3, 2, NULL, 'logic', '`average_two(a, b)` should return the exact average of `a` and `b`.\n\nExample: `average_two(3, 4)` should return `3.5`.', 'def average_two(a, b):\n    return (a + b) // 2\n', 'def average_two(a, b):\n    return (a + b) / 2\n', 'function', 'average_two', '`/` always gives the exact, possibly-fractional result. `//` rounds down to a whole number, discarding whatever came after the decimal point. They look almost identical but behave very differently.', 'Test division with numbers that don\'t divide evenly - that\'s when `//` versus `/` shows up clearly.', NULL, 'published', 'a9633fd518a8aeb7c7917a8674129cbc088829abff7c08e28e548d9aa302bb12', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (194, 'average-trouble', 13, 'Average Trouble', 4, 2, NULL, 'logic', '`average_two(a, b)` should return the average of `a` and `b`.\n\nExample: `average_two(4, 6)` should return `5`.', 'def average_two(a, b):\n    return a + b / 2\n', 'def average_two(a, b):\n    return (a + b) / 2\n', 'function', 'average_two', 'Python follows the normal maths order of operations: multiplication and division happen before addition and subtraction, unless brackets say otherwise. `a + b / 2` means `a + (b / 2)`, not `(a + b) / 2`.', 'When a calculation mixes `+`/`-` with `*`/`/`, add brackets to make the intended order explicit, even when you\'re confident of the rules.', NULL, 'published', 'fe253e7f3d3006e39ddf763304d23027a7b027e4bc7bda4bbcf4232bc783384c', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (195, 'and-or-or', 13, 'And or Or', 5, 2, NULL, 'logic', 'A valid username is between 3 and 20 characters long (inclusive). `is_valid_username(name)` should return `True` or `False` accordingly.\n\nExample: `is_valid_username(\"al\")` should return `False` (too short).', 'def is_valid_username(name):\n    return len(name) >= 3 or len(name) <= 20\n', 'def is_valid_username(name):\n    return len(name) >= 3 and len(name) <= 20\n', 'function', 'is_valid_username', '`or` is true if *either* side is true; `and` needs *both*. A validator that should enforce a range on both ends almost always needs `and`, since `or` lets almost everything through.', 'When a validator seems to accept things it shouldn\'t, check every `or` - would `and` be stricter and more correct?', NULL, 'published', 'e172c3cadc1b2707b1b1e9e6fb2f7873ee83bbb7759c912a0c31be6620a6f713', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (196, 'too-early-to-return', 13, 'Too Early to Return', 6, 3, NULL, 'logic', '`find_first_even(nums)` should return the first even number in `nums`, or `None` if there isn\'t one.\n\nExample: `find_first_even([1, 3, 4, 5])` should return `4`.', 'def find_first_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n        return None\n', 'def find_first_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n    return None\n', 'function', 'find_first_even', 'A `return` immediately exits the function, from wherever it is. Put one inside a loop by mistake, and it can end the search after checking just one item instead of letting the loop run its course.', 'Check what\'s actually inside a loop versus after it by reading the indentation carefully, not just the order lines appear on the page.', NULL, 'published', 'a3ce5ef37187d42991bc5607acd642d9b6c9c0750aecc20e3b899c21c192a7a8', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (197, 'forgot-to-reset', 13, 'Forgot to Reset', 7, 3, NULL, 'logic', '`sum_each(lists)` should return a list containing the sum of each inner list in `lists`.\n\nExample: `sum_each([[1, 2], [3, 4]])` should return `[3, 7]`.', 'def sum_each(lists):\n    total = 0\n    results = []\n    for lst in lists:\n        for num in lst:\n            total += num\n        results.append(total)\n    return results\n', 'def sum_each(lists):\n    results = []\n    for lst in lists:\n        total = 0\n        for num in lst:\n            total += num\n        results.append(total)\n    return results\n', 'function', 'sum_each', 'An accumulator variable needs resetting at the start of each new thing it\'s accumulating for. Initialise it outside a loop that\'s meant to restart it each time, and the totals bleed into each other.', 'For every accumulator, ask: \"does this get reset exactly where I need a fresh start?\"', NULL, 'published', 'bda4ab8d6463123f70abe19713cbbf67fa0e44f3e8b0f1298ccc40bd6f7d473b', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (198, 'the-loop-that-never-ends', 13, 'The Loop That Never Ends', 8, 2, NULL, 'logic', '`count_down(n)` should return a list counting down from `n` to `1`.\n\nExample: `count_down(3)` should return `[3, 2, 1]`.', 'def count_down(n):\n    result = []\n    while n > 0:\n        result.append(n)\n    return result\n', 'def count_down(n):\n    result = []\n    while n > 0:\n        result.append(n)\n        n -= 1\n    return result\n', 'function', 'count_down', 'Every `while` loop needs something inside it that moves its condition towards becoming false. Forgetting the update step - like decreasing a counter - leaves the condition permanently true.', 'For every `while` loop, find the line that changes the condition\'s variable. If there isn\'t one, that\'s the bug.', NULL, 'published', '3d3194e5533b3478043b6fb2a09837cb3d90e8df9c11ee4a32e25701bc642f83', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (199, 'ten-is-less-than-nine', 13, 'Ten Is Less Than Nine', 9, 3, NULL, 'logic', '`bigger(a, b)` takes two numbers written as text (as if read from `input()`) and returns the larger one as a number.\n\nExample: `bigger(\"10\", \"9\")` should return `10`.', 'def bigger(a, b):\n    if a > b:\n        return a\n    return b\n', 'def bigger(a, b):\n    a, b = int(a), int(b)\n    if a > b:\n        return a\n    return b\n', 'function', 'bigger', 'Comparing strings compares them character by character, the way a dictionary is ordered - `\"10\"` comes before `\"9\"` because `\"1\"` comes before `\"9\"`. Numbers written as text need converting before a numeric comparison makes sense.', 'If values might be text (especially from `input()`), check they\'re converted before comparing them as numbers.', NULL, 'published', '67322d8cb73cb48e28ab0b458dcc18cb24aeae595d9e1cba0b50be1b0a6752ef', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (200, 'shadowed', 13, 'Shadowed', 10, 3, NULL, 'runtime', '`total_of_unique(items)` should return the sum of the unique numbers in `items`.\n\nExample: `total_of_unique([1, 2, 2, 3])` should return `6`.', 'def total_of_unique(items):\n    sum = 0\n    unique = []\n    for item in items:\n        if item not in unique:\n            unique.append(item)\n    return sum(unique)\n', 'def total_of_unique(items):\n    unique = []\n    for item in items:\n        if item not in unique:\n            unique.append(item)\n    return sum(unique)\n', 'function', 'total_of_unique', 'Python lets you name a variable the same as a built-in function - `sum`, `list`, `str`, `type` are common ones - but doing so hides the built-in everywhere in that scope from that point on. If you need the real one later, the shadowed name causes a crash.', 'Avoid naming variables after built-in functions you might need later in the same function - `total` instead of `sum`, `items` instead of `list`.', NULL, 'published', '60c0751ef4377dd5b15df4a175df8277327a545a592c343e4de44e5af3fde678', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (201, 'modify-while-looping', 13, 'Modify While Looping', 11, 3, NULL, 'logic', '`remove_negatives(nums)` should return `nums` with every negative number removed.\n\nExample: `remove_negatives([1, -2, -3, 4])` should return `[1, 4]`.', 'def remove_negatives(nums):\n    for n in nums:\n        if n < 0:\n            nums.remove(n)\n    return nums\n', 'def remove_negatives(nums):\n    return [n for n in nums if n >= 0]\n', 'function', 'remove_negatives', 'When you remove an item from a list mid-iteration, everything after it shifts one position earlier - but the loop\'s position doesn\'t shift back to match, so it can silently skip the next item. Building a new list avoids the problem entirely.', 'Never remove items from a list (or dict) while iterating over that same list - build a new one or iterate over a copy instead.', NULL, 'published', '6e21ff18e4f4db554cf2be839ecc9c7bf352e709b40e3fdd4b1b60a5ae152a2c', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (202, 'case-matters', 13, 'Case Matters', 12, 2, NULL, 'logic', '`count_vowels(text)` should count how many vowels (a, e, i, o, u) are in `text`, regardless of case.\n\nExample: `count_vowels(\"APPLE\")` should return `2`.', 'def count_vowels(text):\n    count = 0\n    for ch in text:\n        if ch in \"aeiou\":\n            count += 1\n    return count\n', 'def count_vowels(text):\n    count = 0\n    for ch in text:\n        if ch.lower() in \"aeiou\":\n            count += 1\n    return count\n', 'function', 'count_vowels', 'Character comparisons in Python are case-sensitive - `\'A\' == \'a\'` is `False`. Converting both sides to the same case with `.lower()` (or `.upper()`) before comparing handles this cleanly.', 'When comparing text, test with a mix of uppercase and lowercase input to check case is handled the way you expect.', NULL, 'published', '7a1c8f67b9fb05dce5c115d2bc58819322018a3c151152657a9ded20fd0d9a51', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (203, 'wrong-min-init', 13, 'Starting the Maximum at Zero', 13, 2, NULL, 'logic', '`find_max(numbers)` should return the largest number in the list.\n\nExample: `find_max([3, 7, 2])` should return `7`.', 'def find_max(numbers):\n    best = 0\n    for n in numbers:\n        if n > best:\n            best = n\n    return best\n', 'def find_max(numbers):\n    best = numbers[0]\n    for n in numbers:\n        if n > best:\n            best = n\n    return best\n', 'function', 'find_max', 'An accumulator tracking a maximum (or minimum) needs to start from a real value in the data, not an assumed one like `0` - otherwise it quietly \"wins\" against every value in a list where all the real numbers are smaller than it.', 'When initialising a running maximum or minimum, ask: could every real value in the data be smaller (or larger) than my starting point?', 'What do you think `find_max([-5, -2, -8])` returns? Write it down before you run anything.', 'published', '9c37653d33fcb3efe825cb35e9f77dcd03f5565d8dece6a5612b6defa688b70c', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (204, 'forgot-abs-value', 13, 'A Difference That Can Go Negative', 14, 2, NULL, 'logic', '`difference(a, b)` should return the positive difference between `a` and `b`, regardless of which is larger.\n\nExample: `difference(10, 3)` should return `7`.', 'def difference(a, b):\n    return a - b\n', 'def difference(a, b):\n    return abs(a - b)\n', 'function', 'difference', '`abs()` returns the magnitude of a number, stripping any negative sign. Whenever \"how far apart\" or \"how much difference\" matters more than \"which direction\", `abs()` is usually what you want.', 'If a function is meant to work the same way regardless of argument order, try calling it both ways and compare.', NULL, 'published', 'cda7024be6d0e1dce22cd6bf2fb81360d7f5a91bdfdcbdc5078f1cf52d659f45', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (205, 'any-vs-all-confusion', 13, 'Any Pass vs All Pass', 15, 3, NULL, 'logic', '`all_passed(scores)` should return `True` only if every score in the list is 50 or above.\n\nExample: `all_passed([60, 70, 80])` should return `True`.', 'def all_passed(scores):\n    for s in scores:\n        if s >= 50:\n            return True\n    return False\n', 'def all_passed(scores):\n    for s in scores:\n        if s < 50:\n            return False\n    return True\n', 'function', 'all_passed', '\"At least one\" and \"every single one\" are opposite checks, and the loop shape for each is a mirror image: to check *all*, look for a single failure and bail out early; to check *any*, look for a single success and bail out early.', 'Read the brief carefully for \"any\"/\"at least one\" versus \"all\"/\"every\" - they need opposite loop logic.', NULL, 'published', 'bd3cf6345bfbccd3b474a9cacaf104d27538fb19fa4b3f88ed01133ddf4d24e6', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (206, 'swapped-if-else-branches', 13, 'Swapped if/else Results', 16, 2, NULL, 'logic', '`classify_temp(celsius)` should return `\"hot\"` if the temperature is over 30, and `\"mild\"` otherwise.\n\nExample: `classify_temp(35)` should return `\"hot\"`.', 'def classify_temp(celsius):\n    if celsius > 30:\n        return \"mild\"\n    else:\n        return \"hot\"\n', 'def classify_temp(celsius):\n    if celsius > 30:\n        return \"hot\"\n    else:\n        return \"mild\"\n', 'function', 'classify_temp', 'A condition can be perfectly correct while the two outcomes attached to it are swapped - the code still runs without error, it just confidently returns the opposite answer to the one you meant.', 'When a condition looks right but results seem backwards, check which branch returns which value, not just the comparison itself.', NULL, 'published', 'c6f7d8c115f37200749b7ae162252fd653599eba36c1d9f6a8d8d45a2dabdcb3', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (207, 'string-concat-not-sum', 13, 'Adding Scores Given as Text', 17, 2, NULL, 'logic', '`total_score(score1, score2)` should return the sum of two scores given as text.\n\nExample: `total_score(\"10\", \"20\")` should return `30`.', 'def total_score(score1, score2):\n    return score1 + score2\n', 'def total_score(score1, score2):\n    return int(score1) + int(score2)\n', 'function', 'total_score', '`+` does different things depending on type: numeric addition for numbers, concatenation for strings. Text that looks like a number is still a string until you explicitly convert it.', 'If `+` on numbers-that-look-like-text gives a suspiciously long result instead of a sum, you\'re concatenating, not adding.', NULL, 'published', '98df5163d366c600673bad12ea43f5c937d14c52ca8b1e48bfb1bc1f6c889298', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (208, 'sorted-ascending-not-descending', 13, 'Top Scores, Sorted the Wrong Way', 18, 2, NULL, 'logic', '`top_scores(scores)` should return the 3 highest scores, highest first.\n\nExample: `top_scores([5, 1, 9, 3, 7])` should return `[9, 7, 5]`.', 'def top_scores(scores):\n    return sorted(scores)[:3]\n', 'def top_scores(scores):\n    return sorted(scores, reverse=True)[:3]\n', 'function', 'top_scores', '`sorted()` always sorts ascending unless told otherwise. \"Top N\" or \"highest first\" always needs `reverse=True` (or sorting by a negated key).', 'Whenever you see \"top\" or \"highest\" alongside `sorted()`, check for `reverse=True`.', NULL, 'published', '061460d9c6e82f1904448a426843b42df4fd8d1d2e46f8110e6bf29cfc1ad585', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (209, 'lexicographic-number-compare', 13, 'Comparing Numbers Stored as Text', 19, 3, NULL, 'logic', '`highest_id(ids)` should return the numerically largest id from a list of id strings.\n\nExample: `highest_id([\"9\", \"10\", \"2\"])` should return `\"10\"`.', 'def highest_id(ids):\n    return max(ids)\n', 'def highest_id(ids):\n    return max(ids, key=int)\n', 'function', 'highest_id', 'Comparing strings never looks at their numeric meaning - `\"9\"` and `\"10\"` are compared letter by letter, the same way a dictionary orders words, and `\"9\"` comes after `\"10\"` that way purely because `\'9\'` is a \"bigger\" character than `\'1\'`.', 'If you are comparing numbers that happen to be stored as text, convert them (or supply a `key=int`) before comparing.', 'What do you think `highest_id([\"9\", \"10\", \"2\"])` returns? Write it down before you run anything.', 'published', '79b2602256470926dc60844e1d73913a84313fc220f13a43607a1ec2ee72ef76', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (210, 'truncation-not-rounding', 13, 'Truncating Instead of Rounding', 20, 2, NULL, 'logic', '`nearest_dollar(cents)` should return the nearest whole number of dollars.\n\nExample: `nearest_dollar(149)` should return `1`.', 'def nearest_dollar(cents):\n    return int(cents / 100)\n', 'def nearest_dollar(cents):\n    return round(cents / 100)\n', 'function', 'nearest_dollar', '`int(x)` and `round(x)` are not the same thing: `int()` just chops off everything after the decimal point, while `round()` picks the nearest whole number - the difference shows up for any value with a fractional part of 0.5 or more.', 'If a value should round to the \"nearest\" whole number rather than always down, use `round()`, not `int()`.', NULL, 'published', 'f416fea1432133c4a9fc5ec0861d352b50e4950f318983b55870cbfbd5ef06f5', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (211, 'wrong-grade-boundary', 13, 'An Exclusive Grade Boundary', 21, 2, NULL, 'logic', '`grade(score)` should return `\"A\"` for 90 or above, `\"B\"` for 80 or above, and `\"C\"` otherwise.\n\nExample: `grade(95)` should return `\"A\"`.', 'def grade(score):\n    if score > 90:\n        return \"A\"\n    elif score > 80:\n        return \"B\"\n    else:\n        return \"C\"\n', 'def grade(score):\n    if score >= 90:\n        return \"A\"\n    elif score >= 80:\n        return \"B\"\n    else:\n        return \"C\"\n', 'function', 'grade', '\"90 or above\" and \"above 90\" differ by exactly one value - the boundary itself. Reading the brief\'s exact wording (inclusive or exclusive?) decides whether you need `>=` or `>`.', 'Test boundary values exactly - if the brief says \"X or above\", does your code\'s `>` actually need to be `>=`?', NULL, 'published', 'a7d98b2676ffbdf3960301732b149dc9f788e93f1f77ee9ecc85752428174369', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (212, 'case-sensitive-name-match', 13, 'A Name Lookup That Cares About Case', 22, 2, NULL, 'logic', '`is_registered(names, name)` should return whether `name` is in the list `names`, ignoring case.\n\nExample: `is_registered([\"Ada\", \"Sam\"], \"ada\")` should return `True`.', 'def is_registered(names, name):\n    return name in names\n', 'def is_registered(names, name):\n    return name.lower() in [n.lower() for n in names]\n', 'function', 'is_registered', 'Membership checks (`in`) and equality (`==`) both compare text exactly, case included. \"Ignoring case\" always needs an explicit `.lower()` (or `.upper()`) on both sides being compared.', 'If a lookup should be \"case-insensitive\", check that both sides are actually lower-cased (or upper-cased) before comparing.', NULL, 'published', '195a31f466818e70e64d86ed0e450e291afee75279b03055062a86153d05c234', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (213, 'is-not-equality-for-lists', 13, 'is Instead of == for Lists', 23, 3, NULL, 'logic', '`same_order(list1, list2)` should return whether the two lists contain the same values in the same order.\n\nExample: `same_order([1, 2, 3], [1, 2, 3])` should return `True`.', 'def same_order(list1, list2):\n    return list1 is list2\n', 'def same_order(list1, list2):\n    return list1 == list2\n', 'function', 'same_order', '`==` asks \"do these have the same value?\"; `is` asks \"are these the exact same object?\". Two freshly-built lists with identical contents will always fail an `is` check, even though they are equal.', 'Use `==` for value comparisons. Reserve `is` for identity checks like `x is None`.', NULL, 'published', '537769fe84e11a985a69e357bcba5dbe860554eed6e68074fbb87da429eb6ea9', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (214, 'wrong-range-step', 13, 'Evens With the Wrong Step', 24, 2, NULL, 'logic', '`even_numbers_up_to(n)` should return a list of even numbers from 0 up to (not including) `n`.\n\nExample: `even_numbers_up_to(10)` should return `[0, 2, 4, 6, 8]`.', 'def even_numbers_up_to(n):\n    return list(range(0, n, 1))\n', 'def even_numbers_up_to(n):\n    return list(range(0, n, 2))\n', 'function', 'even_numbers_up_to', '`range(start, stop, step)`\'s third argument controls the gap between values. Stepping by 1 visits every number; stepping by 2 from an even start visits only even numbers.', 'When a range should skip values (evens, every third item, and so on), check its step argument matches that.', NULL, 'published', '06030cc923992948087df04599cf2aed3f58a460267719d8e259d94c19eff0c0', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (215, 'off-by-one-first-n-chars', 13, 'One Character Short', 25, 2, NULL, 'logic', '`first_n_chars(text, n)` should return the first `n` characters of `text`.\n\nExample: `first_n_chars(\"hello\", 3)` should return `\"hel\"`.', 'def first_n_chars(text, n):\n    return text[0:n-1]\n', 'def first_n_chars(text, n):\n    return text[0:n]\n', 'function', 'first_n_chars', 'Python slice bounds are already \"up to but not including\" the end value, so `text[0:n]` already gives exactly `n` characters - no further adjustment needed.', 'Before adding a `-1` or `+1` to a slice bound, check whether the slice already does what you think it does.', NULL, 'published', '3c147132ca9f6f7e7a4108a1a3febea3507bf8ec3fde2021316d90bd18ade815', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (216, 'early-break-skips-remaining', 13, 'Stopping at the First Negative', 26, 2, NULL, 'logic', '`count_positives(numbers)` should return how many numbers in the list are positive.\n\nExample: `count_positives([1, -2, 3])` should return `2`.', 'def count_positives(numbers):\n    count = 0\n    for n in numbers:\n        if n > 0:\n            count += 1\n        else:\n            break\n    return count\n', 'def count_positives(numbers):\n    count = 0\n    for n in numbers:\n        if n > 0:\n            count += 1\n    return count\n', 'function', 'count_positives', '`break` means \"stop looking entirely\", while simply not matching a condition means \"skip this one, keep going\". Counting *all* matches in a list needs the second behaviour, not the first.', 'If a loop is meant to examine every item, check whether a `break` is cutting it short partway through.', NULL, 'published', '02e85af075cd4d075e1aed529f01b869c440404b2b528a301a708e51b17b7ef0', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (217, 'percentage-inverted', 13, 'Percentage Calculated Upside Down', 27, 2, NULL, 'logic', '`percent_correct(correct, total)` should return what percentage of `total` questions were `correct`.\n\nExample: `percent_correct(50, 100)` should return `50.0`.', 'def percent_correct(correct, total):\n    return total / correct * 100\n', 'def percent_correct(correct, total):\n    return correct / total * 100\n', 'function', 'percent_correct', 'Division is not symmetric - `a / b` and `b / a` give very different answers unless `a` equals `b`. When a formula involves a ratio or percentage, double-check which value is meant to be on top.', 'For any \"percentage\" or \"ratio\" calculation, say the formula out loud in words first (\"part over whole\") and check the code matches.', NULL, 'published', '0bca1cc5427d12275b2277d11a8505f8ff92f3ba254e46cae63dd706d212758a', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (218, 'wrong-fallback-value', 13, 'A Fallback That Matches the Wrong Case', 28, 2, NULL, 'logic', '`get_discount(level)` should return the % discount for `\"gold\"` (20), `\"silver\"` (10), and `0` for anything else.\n\nExample: `get_discount(\"bronze\")` should return `0`.', 'def get_discount(level):\n    if level == \"gold\":\n        return 20\n    elif level == \"silver\":\n        return 10\n    return 10\n', 'def get_discount(level):\n    if level == \"gold\":\n        return 20\n    elif level == \"silver\":\n        return 10\n    return 0\n', 'function', 'get_discount', 'A copy-pasted value left over from an earlier branch is easy to miss, because the code still runs perfectly - it just quietly returns the wrong fallback for every case that wasn\'t explicitly handled.', 'Check every fallback/default `return` against the brief specifically - it\'s the easiest one to leave wrong after copy-pasting a branch.', NULL, 'published', 'a8859972b63724a391e303231648f0327791766a7574014fa25c114bcee8907d', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (219, 'miscounted-matches', 13, 'A Condition That Is Always True', 29, 3, NULL, 'logic', '`count_vowels(word)` should return how many vowels (a, e, i, o, u) are in `word`.\n\nExample: `count_vowels(\"hello\")` should return `2`.', 'def count_vowels(word):\n    count = 0\n    for letter in word:\n        if letter == \"a\" or \"e\" or \"i\" or \"o\" or \"u\":\n            count += 1\n    return count\n', 'def count_vowels(word):\n    count = 0\n    for letter in word:\n        if letter in \"aeiou\":\n            count += 1\n    return count\n', 'function', 'count_vowels', 'Writing `x == a or b or c` does *not* mean \"x equals a, b, or c\" - each `or` joins a whole separate condition, and a plain non-empty string like `\"e\"` is always truthy on its own. `in` is the correct way to check membership against several options at once.', 'To check \"is this one of several values\", use `x in (a, b, c)` or `x in \"abc\"` - never chain `==` with bare `or`.', 'What do you think `count_vowels(\"sky\")` returns? Write it down before you run anything.', 'published', '75baed15821e00d9003dd1b0d2d02b7bc835623fc9946dfe21508bc368d99d20', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (220, 'swapped-even-odd-condition', 13, 'Summing the Wrong Parity', 30, 2, NULL, 'logic', '`sum_evens(numbers)` should return the sum of the even numbers in the list.\n\nExample: `sum_evens([1, 2, 3, 4])` should return `6`.', 'def sum_evens(numbers):\n    total = 0\n    for n in numbers:\n        if n % 2 == 1:\n            total += n\n    return total\n', 'def sum_evens(numbers):\n    total = 0\n    for n in numbers:\n        if n % 2 == 0:\n            total += n\n    return total\n', 'function', 'sum_evens', 'A modulo check for \"even\" and \"odd\" differ by exactly one comparison value - `== 0` versus `== 1` - easy to swap, and the code runs without any error either way.', 'When filtering by even/odd, double check the function\'s name actually matches which remainder it tests for.', NULL, 'published', '8c6b406f784eabc4ffb2f95246c23468986e3483c845174310ab74c6491f3101', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (221, 'wrong-comparison-for-minimum', 13, 'Cheapest, or Most Expensive?', 31, 2, NULL, 'logic', '`cheapest(prices)` should return the smallest price in the list.\n\nExample: `cheapest([5, 2, 8])` should return `2`.', 'def cheapest(prices):\n    best = prices[0]\n    for p in prices:\n        if p > best:\n            best = p\n    return best\n', 'def cheapest(prices):\n    best = prices[0]\n    for p in prices:\n        if p < best:\n            best = p\n    return best\n', 'function', 'cheapest', 'Finding a minimum and finding a maximum use the exact same loop shape - the only difference is a single comparison operator. It is easy to copy a \"find the maximum\" pattern and forget to flip it.', 'When adapting a \"find the maximum\" pattern into a \"find the minimum\" one (or vice versa), double check the comparison operator was actually flipped.', NULL, 'published', '513814408fcfa6ae69260c53cc71188f2a2910642fb6d4ff8da0733a3b84057d', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (222, 'wrong-and-or-condition', 13, 'or Where and Was Needed', 32, 2, NULL, 'logic', '`is_valid_password(password)` should return `True` only if the password is at least 8 characters long *and* contains only letters and digits.\n\nExample: `is_valid_password(\"abc12345\")` should return `True`.', 'def is_valid_password(password):\n    return len(password) >= 8 or password.isalnum()\n', 'def is_valid_password(password):\n    return len(password) >= 8 and password.isalnum()\n', 'function', 'is_valid_password', '`and` requires every condition to be true; `or` only needs one. \"Both of these rules must hold\" always means `and`, never `or` - a very easy pair to mix up since both read naturally in English.', 'Read requirements literally: \"must be X and Y\" needs `and`; \"must be X or Y\" needs `or` - they are not interchangeable.', NULL, 'published', 'd330490fa708be46fa183b204e45391b27d3e0d1f31717f06bce7c311dfca6eb', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (223, 'wrong-and-or-condition-reversed', 13, 'and Where or Was Needed', 33, 2, NULL, 'logic', '`can_ride(height_cm, has_adult)` should return `True` if the rider is tall enough (120cm or more), *or* accompanied by an adult.\n\nExample: `can_ride(150, False)` should return `True`.', 'def can_ride(height_cm, has_adult):\n    return height_cm >= 120 and has_adult\n', 'def can_ride(height_cm, has_adult):\n    return height_cm >= 120 or has_adult\n', 'function', 'can_ride', 'This is the mirror image of mixing up `and` for `or` - here, a rule that should accept \"either condition\" was written to require \"both\". The English words \"or\" and \"and\" in the brief are exact instructions, not interchangeable phrasing.', 'When a brief says \"either\" or uses \"or\", check the code doesn\'t quietly require both with `and`.', NULL, 'published', 'fc7706f19b47249636bc76b9d0d2e7516d44eecdeb18f28327e656e2eb13cb09', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (224, 'wrong-list-comprehension-condition', 13, 'Filtering for the Wrong Parity', 34, 2, NULL, 'logic', '`odd_only(numbers)` should return only the odd numbers from the list.\n\nExample: `odd_only([1, 2, 3, 4, 5])` should return `[1, 3, 5]`.', 'def odd_only(numbers):\n    return [n for n in numbers if n % 2 == 0]\n', 'def odd_only(numbers):\n    return [n for n in numbers if n % 2 == 1]\n', 'function', 'odd_only', 'A list comprehension\'s filter condition is just an ordinary boolean expression - it is exactly as easy to get backwards here as in a regular `if` statement.', 'Read a comprehension\'s `if` condition exactly as carefully as you would a normal `if` statement - it is easy to skim past.', NULL, 'published', '4d64cd7aa8d1cf37b8e2664c6be4a0d91055917c514a4a51dbedc81c8cca0767', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (225, 'wrong-concatenation-order', 13, 'Name Parts in the Wrong Order', 35, 2, NULL, 'logic', '`full_name(first, last)` should return `\"first last\"`.\n\nExample: `full_name(\"Ada\", \"Lovelace\")` should return `\"Ada Lovelace\"`.', 'def full_name(first, last):\n    return last + \" \" + first\n', 'def full_name(first, last):\n    return first + \" \" + last\n', 'function', 'full_name', 'String concatenation happens in exactly the order you write it - there is no automatic correction for parameters joined in the wrong sequence.', 'Check the exact order of concatenated pieces against the brief\'s own example output.', NULL, 'published', '89704e5a7db798bb2a298a8f84beaf555c75309df04cab43372564f10d0839c5', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (226, 'forgot-multiply-by-rate', 13, 'Forgot the Price Per Item', 36, 2, NULL, 'logic', '`total_cost(items, price_per_item)` should return the total cost of buying `items` items at `price_per_item` each.\n\nExample: `total_cost(3, 10)` should return `30`.', 'def total_cost(items, price_per_item):\n    return items\n', 'def total_cost(items, price_per_item):\n    return items * price_per_item\n', 'function', 'total_cost', 'If a function\'s result never changes no matter what you pass for one of its parameters, that parameter probably isn\'t being used in the calculation at all - a strong sign a step was simply left out.', 'Try varying each parameter independently - if the result never changes, that parameter is being ignored.', NULL, 'published', '24bd011e02f6a07828d041b2a8749697f8017d8d30dc12bf291341d9fd48e7a9', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (227, 'inclusive-range-boundary-bonus', 13, 'Exactly 5 Years Should Count', 37, 2, NULL, 'logic', '`bonus_eligible(years_worked)` should return `True` once an employee has worked 5 years or more.\n\nExample: `bonus_eligible(10)` should return `True`.', 'def bonus_eligible(years_worked):\n    return years_worked > 5\n', 'def bonus_eligible(years_worked):\n    return years_worked >= 5\n', 'function', 'bonus_eligible', '\"Or more\" / \"or above\" / \"at least\" are all inclusive phrases - they need `>=`, not `>`. \"More than\" / \"over\" / \"above\" are the exclusive versions that actually need `>`.', 'Check a brief\'s exact wording - \"at least N\" needs `>=`; \"more than N\" needs `>`.', NULL, 'published', '03cbdc4a47ea96d04662b47bc25e8c48e47b851c2b651ed4023b777db2f42541', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (228, 'average-of-wrong-count', 13, 'Dividing by a Fixed Number', 38, 2, NULL, 'logic', '`class_average(scores)` should return the mean of the scores in the list.\n\nExample: `class_average([50, 60, 70])` should return `60.0`.', 'def class_average(scores):\n    total = sum(scores)\n    return total / 100\n', 'def class_average(scores):\n    total = sum(scores)\n    return total / len(scores)\n', 'function', 'class_average', 'A mean is always \"total divided by count\" - using a fixed number instead of the real count only works by coincidence, for exactly one specific input size.', 'If a calculation divides by a literal number rather than something measured from the actual data (like `len(...)`), check whether that number can really be assumed fixed.', NULL, 'published', '6e6ff7f425b458798bf8cded98d43d6446b7c124867e59b9f1e1497bf528b1af', '2026-11-22 20:26:14', NULL, '2026-11-22 20:26:14', '2026-11-22 20:26:14');
INSERT INTO `bh_puzzles` VALUES (229, 'swapped-win-loss-condition', 13, 'Win and Loss Swapped', 39, 2, NULL, 'logic', '`game_result(my_score, their_score)` should return `\"Win\"` if `my_score` is higher, `\"Loss\"` if lower, and `\"Draw\"` if equal.\n\nExample: `game_result(10, 5)` should return `\"Win\"`.', 'def game_result(my_score, their_score):\n    if my_score < their_score:\n        return \"Win\"\n    elif my_score > their_score:\n        return \"Loss\"\n    else:\n        return \"Draw\"\n', 'def game_result(my_score, their_score):\n    if my_score > their_score:\n        return \"Win\"\n    elif my_score < their_score:\n        return \"Loss\"\n    else:\n        return \"Draw\"\n', 'function', 'game_result', 'Comparisons and their labels have to agree - \"Win\" should mean *your* score is higher, not lower. Both branches here run without error; they are just confidently backwards.', 'For any \"win/loss\" or \"higher/lower\" style branch, check the comparison direction matches the label exactly, not just that there is one branch per outcome.', NULL, 'published', '271cfff48d2210549e3f78e4569190ea0add6f1285a0c01d278a4cf88926d886', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (230, 'wrong-increment-amount', 13, 'Minutes as a Fraction', 40, 2, NULL, 'logic', '`seconds_to_minutes(seconds)` should return how many whole minutes have elapsed.\n\nExample: `seconds_to_minutes(125)` should return `2`.', 'def seconds_to_minutes(seconds):\n    return seconds / 60\n', 'def seconds_to_minutes(seconds):\n    return seconds // 60\n', 'function', 'seconds_to_minutes', '`/` always gives a float result, carrying any remainder as a fraction. `//` discards the remainder and gives a whole number - exactly what \"whole minutes elapsed\" means.', 'If a brief says \"whole\" anything, check for `//` rather than `/`.', NULL, 'published', 'd5f8073e9513a71a52ecd1e4d184cb689579560ec5b46992ba5208e4586970e0', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (231, 'plural-variable-mixup', 13, 'The Current Item vs the Whole List', 41, 3, NULL, 'logic', '`longest_word(words)` should return the longest word in the list (the first one, if there is a tie).\n\nExample: `longest_word([\"cat\", \"elephant\", \"dog\"])` should return `\"elephant\"`.', 'def longest_word(words):\n    longest = \"\"\n    for w in words:\n        if len(w) > len(longest):\n            longest = words\n    return longest\n', 'def longest_word(words):\n    longest = \"\"\n    for w in words:\n        if len(w) > len(longest):\n            longest = w\n    return longest\n', 'function', 'longest_word', 'Python can\'t warn you when a name that happens to exist (like the function\'s own parameter) is used by mistake instead of the loop variable - both are valid names, just not the one you meant.', 'When a loop variable and an outer variable have very similar names (singular/plural is a classic case), check every use of them carefully - a typo-like slip between them won\'t raise any error.', 'What do you think `longest_word([\"cat\", \"elephant\", \"dog\"])` returns? Write it down before you run anything.', 'published', '89d71e9af99305b2664db22f0efa0462c6f94325e6147b1d3cc121e6a0c64d06', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (232, 'wrong-order-of-operations', 13, 'An Average Without Brackets', 42, 2, NULL, 'logic', '`average_of_two(a, b)` should return the average of `a` and `b`.\n\nExample: `average_of_two(4, 6)` should return `5.0`.', 'def average_of_two(a, b):\n    return a + b / 2\n', 'def average_of_two(a, b):\n    return (a + b) / 2\n', 'function', 'average_of_two', 'Python follows the standard order of operations: multiplication and division happen before addition and subtraction, regardless of the order you wrote them in. Any formula that needs addition done *first* must say so with brackets.', 'Whenever a formula mixes `+`/`-` with `*`/`/`, check whether brackets are needed to force the order you actually want.', NULL, 'published', '3bb114c16dd77a55312734255a860aec9de75637915f85ab94d6ec31242cfc54', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (233, 'infinite-descent', 14, 'Infinite Descent', 1, 3, NULL, 'runtime', '`factorial(n)` should return `n!` (n factorial): `n * (n-1) * (n-2) * ... * 1`.\n\nExample: `factorial(5)` should return `120`. By definition, `factorial(0)` and `factorial(1)` both return `1`.', 'def factorial(n):\n    return n * factorial(n - 1)\n', 'def factorial(n):\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\n', 'function', 'factorial', 'Recursive functions need two things: a base case that returns without recursing, and a recursive case that\'s guaranteed to move closer to that base case. This function only has the recursive case, so it never stops - it just keeps calling itself with smaller and smaller numbers until Python gives up.', 'Whenever you write a recursive function, write the base case first and check the recursive call actually moves towards it.', 'What do you think happens when you run `factorial(5)`? Will it finish? Write down what you expect before you run it.', 'published', '8cda8441bd441b79d4348d243b274fe7f2358ded3914d0f00021ccb64686a5ad', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (234, 'shared-default', 14, 'Shared Default', 2, 3, NULL, 'logic', 'Each call to `add_item` should start from a fresh, empty basket unless one is given.\n\nExpected output:\n```\n[\'apple\']\n[\'banana\']\n```', 'def add_item(item, basket=[]):\n    basket.append(item)\n    return basket\n\nprint(add_item(\"apple\"))\nprint(add_item(\"banana\"))\n', 'def add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nprint(add_item(\"apple\"))\nprint(add_item(\"banana\"))\n', 'script', NULL, 'A default argument value is evaluated exactly once, when `def` runs - not fresh on every call. For an immutable default like a number or string this never matters, but a mutable default like a list or dict gets shared and silently mutated across every call that relies on it.', 'Never use a mutable value (`[]`, `{}`, a class instance) as a default argument - use `None` and create the real default inside the function body instead.', 'Each call leaves out the `basket` argument. What do you expect the two printed lines to look like?', 'published', '2d78064811ca3aa88e97a29acd15016cb3925e5f55dce354e16f48535ea5d6b5', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (235, 'same-list-two-names', 14, 'Same List, Two Names', 3, 3, NULL, 'logic', 'Doubling a copy of a list should leave the original list unchanged.\n\nExpected output:\n```\n[1, 2, 3]\n[2, 4, 6]\n```', 'original = [1, 2, 3]\ndoubled = original\nfor i in range(len(doubled)):\n    doubled[i] = doubled[i] * 2\nprint(original)\nprint(doubled)\n', 'original = [1, 2, 3]\ndoubled = original.copy()\nfor i in range(len(doubled)):\n    doubled[i] = doubled[i] * 2\nprint(original)\nprint(doubled)\n', 'script', NULL, 'Assigning a list to a new name doesn\'t copy it - both names point at the exact same object in memory. Changing the contents through either name changes what both names see, which is surprising if you expected an independent copy.', 'If you need a genuinely separate list, use `.copy()`, `list(...)`, or a slice `[:]` - plain `=` never copies a list.', 'After `doubled = original`, are `original` and `doubled` separate lists, or two names for the same one? What do you expect printed?', 'published', '631841c23f9f6f2b0691361d6b266d14f96284af7059a436f2e28c82118db40d', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (236, 'grid-surprise', 14, 'Grid Surprise', 4, 4, NULL, 'logic', 'Changing one cell of a grid should only affect that one cell.\n\nExpected output:\n```\n[[1, 0, 0], [0, 0, 0], [0, 0, 0]]\n```', 'grid = [[0] * 3] * 3\ngrid[0][0] = 1\nprint(grid)\n', 'grid = [[0] * 3 for _ in range(3)]\ngrid[0][0] = 1\nprint(grid)\n', 'script', NULL, 'Multiplying a list with `*` repeats references to the same object, not independent copies - this is harmless for immutable items like numbers, but for a list-of-lists, every \"row\" ends up being the exact same row, aliased three times over.', 'Never build a 2D grid with `[[...] * n] * m` - use a comprehension so each row is created fresh.', 'After `grid[0][0] = 1`, how many of the 9 cells do you expect to show `1`?', 'published', 'aad26edd514fa5f1814e44f59b8e304ebb026f46c2a966151563eef29a6686fc', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (237, 'the-search-that-hangs', 14, 'The Search That Hangs', 5, 4, NULL, 'logic', '`binary_search(items, target)` should return the index of `target` in the sorted list `items`, or `-1` if it isn\'t there.\n\nExample: `binary_search([1, 3, 5, 7, 9], 7)` should return `3`.', 'def binary_search(items, target):\n    low, high = 0, len(items)\n    while low < high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid\n        else:\n            high = mid\n    return -1\n', 'def binary_search(items, target):\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n', 'function', 'binary_search', 'Binary search relies on the search range shrinking every single pass. If a new bound is set to `mid` itself rather than one step past it, the range can stop shrinking entirely when the target isn\'t in the list - looping forever instead of giving up.', 'For any loop meant to narrow down a range, check by hand that the range can\'t get stuck at the same size pass after pass.', NULL, 'published', '9e3b4c7e6fad8345fca5c1ba78b0077225e6bfd6ce8c7cb151086b2c0ff07260', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (238, 'late-binding', 14, 'Late Binding', 6, 4, NULL, 'logic', 'Each function made in the loop should remember its *own* value of `i` at the time it was created.\n\nExpected output:\n```\n[0, 1, 2]\n```', 'makers = []\nfor i in range(3):\n    makers.append(lambda: i)\nprint([m() for m in makers])\n', 'makers = []\nfor i in range(3):\n    makers.append(lambda i=i: i)\nprint([m() for m in makers])\n', 'script', NULL, 'A closure remembers the *variable*, not the value it held at creation time. Since all three lambdas share the same loop variable `i`, and the loop has finished by the time any of them are called, they all see `i`\'s final value. A default argument is evaluated once, at creation, which is how to capture the value instead.', 'If you create functions inside a loop that need to remember the loop variable\'s value, capture it with a default argument: `lambda x=x: ...`.', 'Three lambdas are created, one per loop iteration. What do you expect calling all three, in order, to give?', 'published', '8416e56bc0e9651ca3521b3316d160fe0da0047e19b26c18758e39d4fbbf9561', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (239, 'global-mistake', 14, 'Global Mistake', 7, 3, NULL, 'logic', '`record_score` should remember the highest score seen so far, across separate calls.\n\nExpected output:\n```\n50\n50\n80\n```', 'high_score = 0\n\ndef record_score(points):\n    local_high = high_score\n    if points > local_high:\n        local_high = points\n    return local_high\n\nprint(record_score(50))\nprint(record_score(30))\nprint(record_score(80))\n', 'high_score = 0\n\ndef record_score(points):\n    global high_score\n    if points > high_score:\n        high_score = points\n    return high_score\n\nprint(record_score(50))\nprint(record_score(30))\nprint(record_score(80))\n', 'script', NULL, 'Reading a global variable into a local one copies its current value - it doesn\'t create a live link back to the original. Without `global`, any \"updates\" only change the local copy, which disappears when the function returns, leaving the real global untouched.', 'If a function needs to remember something between separate calls, it has to update a genuine global (with `global`) - a local copy resets every time.', 'Three scores are recorded in a row: 50, then 30, then 80. What do you expect printed each time?', 'published', 'caedc6ab358244af587b488d96946b0c5924de6e695916b41f6c24df03f054bf', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (240, 'used-up', 14, 'Used Up', 8, 4, NULL, 'logic', 'Listing the same filtered results twice should give the same answer both times.\n\nExpected output:\n```\n[2, 4, 6]\n[2, 4, 6]\n```', 'def even_numbers(nums):\n    return (n for n in nums if n % 2 == 0)\n\nevens = even_numbers([1, 2, 3, 4, 5, 6])\nprint(list(evens))\nprint(list(evens))\n', 'def even_numbers(nums):\n    return [n for n in nums if n % 2 == 0]\n\nevens = even_numbers([1, 2, 3, 4, 5, 6])\nprint(list(evens))\nprint(list(evens))\n', 'script', NULL, 'Generators produce values lazily, one at a time, and don\'t remember them afterwards - once consumed, they\'re exhausted for good. A list holds all its values at once and can be read repeatedly, which is what\'s needed here.', 'If something needs to be iterated over more than once, make sure it\'s a list (or another reusable collection), not a one-shot generator.', '`list(evens)` is called twice on the same `evens`. What do you expect the second call to print?', 'published', 'e8c742acbb814da1a7833b8aa47913a2843a673df9c755f070d22d272c76c55d', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (241, 'nearly-equal', 14, 'Nearly Equal', 9, 3, NULL, 'logic', '`adds_to_one(a, b, c)` should return `True` if the three numbers add up to (very close to) `1`.\n\nExample: `adds_to_one(0.7, 0.2, 0.1)` should return `True`.', 'def adds_to_one(a, b, c):\n    return a + b + c == 1.0\n', 'import math\n\ndef adds_to_one(a, b, c):\n    return math.isclose(a + b + c, 1.0)\n', 'function', 'adds_to_one', 'Computers store `float` numbers in binary, and most decimal fractions (like 0.1) can\'t be represented exactly in binary any more than 1/3 can be written exactly in decimal. The tiny rounding errors this creates mean exact equality (`==`) between floats is almost never the right check.', 'Never compare floats with `==` - use `math.isclose()` (or check the difference is smaller than a small tolerance) instead.', 'Do you expect `0.7 + 0.2 + 0.1` to be exactly equal to `1.0` in Python? Write down yes or no before running it.', 'published', '5bf2aab5c63b64dd7dd5e392024da80beda327a09b2f31a9996692ba4352993d', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (242, 'changing-while-iterating-dict', 14, 'Changing While Iterating', 10, 4, NULL, 'runtime', '`remove_zero_stock(stock)` should remove any item from the `stock` dictionary whose count is `0`, and return the dictionary.\n\nExample: `remove_zero_stock({\"pens\": 0, \"pencils\": 5})` should return `{\"pencils\": 5}`.', 'def remove_zero_stock(stock):\n    for item in stock:\n        if stock[item] == 0:\n            del stock[item]\n    return stock\n', 'def remove_zero_stock(stock):\n    for item in list(stock.keys()):\n        if stock[item] == 0:\n            del stock[item]\n    return stock\n', 'function', 'remove_zero_stock', 'Unlike lists, Python actively detects a dictionary changing size while you iterate over it and raises an error rather than risk silently skipping or revisiting items. Looping over a separate list of the keys (taken before the loop starts) sidesteps the problem entirely.', 'Never add or remove keys from a dict while iterating directly over it - loop over `list(d.keys())` if you need to modify it as you go.', NULL, 'published', '04c77145e6f7f84cffd032f231c7fa1210cb37107ddf2a37d89d28b57a5f852c', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (243, 'sorted-wrong', 14, 'Sorted Wrong', 11, 3, NULL, 'logic', '`top_scorers(players)` takes a list of `(name, score)` tuples and should return the names of the 3 highest scorers, highest first.\n\nExample: `top_scorers([(\"Al\", 10), (\"Bo\", 30), (\"Cy\", 20), (\"Di\", 5)])` should return `[\"Bo\", \"Cy\", \"Al\"]`.', 'def top_scorers(players):\n    ranked = sorted(players, key=lambda p: p[1])\n    return [name for name, score in ranked[:3]]\n', 'def top_scorers(players):\n    ranked = sorted(players, key=lambda p: p[1], reverse=True)\n    return [name for name, score in ranked[:3]]\n', 'function', 'top_scorers', '`sorted()` always sorts ascending (smallest first) unless told otherwise. Taking a slice from the front after sorting ascending gives you the smallest items, which is the opposite of \"top\" unless `reverse=True` is added.', 'After any `sorted()` call, check whether you want ascending or descending order, and whether `reverse=True` matches that.', NULL, 'published', 'c96c3ebe0c88c28ce451189a6fbfdffbba9aa1b40715d4cd28b068d39952fa2c', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (244, 'silent-failure', 14, 'Silent Failure', 12, 4, NULL, 'logic', '`safe_divide(a, b)` should return `a` divided by `b`.\n\nExample: `safe_divide(10, 2)` should return `5.0`.', 'def safe_divide(a, b):\n    try:\n        resutl = a / b\n        return result\n    except:\n        return None\n', 'def safe_divide(a, b):\n    return a / b\n', 'function', 'safe_divide', 'A bare `except:` catches every exception, including the ones you never intended to - like a plain typo. That turns a loud, obvious crash (which would have pointed straight at the mistake) into a silent wrong answer, which is much harder to track down.', 'Avoid bare `except:` - catch only the specific exception types you actually expect, so unexpected bugs stay loud instead of disappearing silently.', NULL, 'published', '3e202917d57036990d54c2b47c830e925075870015958591cb58b42f6c108c6b', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (245, 'equal-or-identical', 14, 'Equal or Identical', 13, 3, NULL, 'logic', '`same_contents(a, b)` should return `True` if two lists contain the same items in the same order, even if they are different list objects.\n\nExample: `same_contents([1, 2, 3], [1, 2, 3])` should return `True`.', 'def same_contents(a, b):\n    return a is b\n', 'def same_contents(a, b):\n    return a == b\n', 'function', 'same_contents', '`==` asks \"do these have the same value?\"; `is` asks \"are these the exact same object in memory?\" Two separately built lists can hold identical values while being two completely different objects - which is the normal, expected case, not an edge case.', 'Use `==` to compare values (almost always what you want); reserve `is` for checking against `None` or confirming two names refer to the literal same object.', NULL, 'published', '9468ff7d79f67edee7cc7b2bd450032cbe01e9f8c5350295f115bf9cf18aae12', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (246, 'nested-list-multiplication', 14, 'A Board Made of the Same Row', 14, 3, NULL, 'logic', '`make_board(size)` should build a `size` x `size` grid of zeros, set the top-left cell to `1`, and return the grid - with every other cell still `0`.\n\nExample: `make_board(2)` should return `[[1, 0], [0, 0]]`.', 'def make_board(size):\n    board = [[0] * size] * size\n    board[0][0] = 1\n    return board\n', 'def make_board(size):\n    board = [[0] * size for _ in range(size)]\n    board[0][0] = 1\n    return board\n', 'function', 'make_board', '`*` on a list repeats *references* to whatever is inside, not fresh copies of it. `[x] * n` gives you `n` names for the one `x` - entirely different from building `n` independent values.', 'Whenever you multiply a list containing a mutable item (like another list), check whether you actually wanted independent copies - a list comprehension usually does.', 'What do you think `make_board(3)` returns? Write it down before you run anything.', 'published', '69655acbb3a8aeb115dcb2c5f2fd751425a9a8fd3150694fc72cf4b3895b230e', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (247, 'dict-fromkeys-shared-value', 14, 'Every Player Shares One Scoreboard Entry', 15, 3, NULL, 'logic', '`empty_scoreboard(players)` should build a dictionary of empty score lists, one independent list per player, add `10` to the first player\'s list, and return the dictionary.\n\nExample: `empty_scoreboard([\"Ada\", \"Sam\"])` should return `{\"Ada\": [10], \"Sam\": []}`.', 'def empty_scoreboard(players):\n    board = dict.fromkeys(players, [])\n    board[players[0]].append(10)\n    return board\n', 'def empty_scoreboard(players):\n    board = {p: [] for p in players}\n    board[players[0]].append(10)\n    return board\n', 'function', 'empty_scoreboard', '`dict.fromkeys(keys, value)` is convenient, but it only evaluates `value` once and reuses that exact object for every key - the same trap as a mutable default argument, just in a different disguise.', 'If a dictionary or list is being seeded with `fromkeys(...)` or `[x] * n` using a mutable starting value, check whether every entry is secretly the same object.', 'What do you think `empty_scoreboard([\"Ada\", \"Sam\"])` returns? Write it down before you run anything.', 'published', '44967346e108cf63402e6c9b8f916d2565e6bc27933359ba2deed9022eee7c87', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (248, 'sort-returns-none', 14, 'Losing the List to .sort()', 16, 3, NULL, 'logic', '`sorted_names(names)` should return `names` sorted alphabetically.\n\nExample: `sorted_names([\"Bea\", \"Ada\", \"Cal\"])` should return `[\"Ada\", \"Bea\", \"Cal\"]`.', 'def sorted_names(names):\n    names = names.sort()\n    return names\n', 'def sorted_names(names):\n    names.sort()\n    return names\n', 'function', 'sorted_names', '`.sort()` is an in-place method: it rearranges the list itself and hands back `None` as a reminder that nothing new was created. It is one of several common methods that silently return `None` - the bug only shows up if you reassign the result.', 'If a value turns out to be `None` right after calling `.sort()`, `.append()`, `.reverse()`, `.extend()` or similar, check whether you reassigned its result instead of just calling it.', 'What do you think `sorted_names([\"Bea\", \"Ada\", \"Cal\"])` returns? Write it down before you run anything.', 'published', 'd31736bffdb8da3b99cadb7c0665e1096824e8529d4878c6f83e018acaa818f7', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (249, 'append-returns-none', 14, 'Losing the List to .append()', 17, 3, NULL, 'logic', '`add_and_return(items, value)` should add `value` to the end of `items` and return the updated list.\n\nExample: `add_and_return([1, 2], 3)` should return `[1, 2, 3]`.', 'def add_and_return(items, value):\n    items = items.append(value)\n    return items\n', 'def add_and_return(items, value):\n    items.append(value)\n    return items\n', 'function', 'add_and_return', 'Like `.sort()`, `.append()` is an in-place mutator - it changes the list you already have rather than building a new one, so it has nothing meaningful to return.', 'Never write `x = x.append(...)` (or `.sort()`, `.reverse()`, `.extend()`, `.remove()`, `.insert()`) - call the method, then use `x` on its own afterwards.', NULL, 'published', '369a6d17c54185369d9093281a83d85add3f3594173cb8d4d10e87548a11bb89', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (250, 'reverse-returns-none', 14, 'Losing the List to .reverse()', 18, 3, NULL, 'logic', '`reversed_queue(queue)` should return `queue` with its items in reverse order.\n\nExample: `reversed_queue([1, 2, 3])` should return `[3, 2, 1]`.', 'def reversed_queue(queue):\n    queue = queue.reverse()\n    return queue\n', 'def reversed_queue(queue):\n    queue.reverse()\n    return queue\n', 'function', 'reversed_queue', 'Python is consistent about this: methods that change a list in place (`sort`, `reverse`, `append`, `extend`, `insert`, `remove`) always return `None`, as a signal that the useful result is the change itself, not a new value.', 'Learn the short list of common in-place list methods that return `None`, and never assign their result to anything.', NULL, 'published', '2f65eb2db8a24055fbb81aec8d51cc95f569edfc3efd79aa57c559ead5cc024e', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (251, 'default-dict-argument-shared-across-calls', 14, 'A Log That Remembers Between Calls', 19, 4, NULL, 'logic', 'This program adds two separate log entries and prints the second one on its own.\n\nExample output: `{\'b\': 2}`', 'def add_entry(key, value, log={}):\n    log[key] = value\n    return log\n\nfirst = add_entry(\"a\", 1)\nsecond = add_entry(\"b\", 2)\nprint(second)\n', 'def add_entry(key, value, log=None):\n    if log is None:\n        log = {}\n    log[key] = value\n    return log\n\nfirst = add_entry(\"a\", 1)\nsecond = add_entry(\"b\", 2)\nprint(second)\n', 'script', NULL, 'A default argument value is created exactly once, when Python reads the `def` line - not fresh for every call. For an immutable default (a number, a string) this never matters, but a mutable default (a list or dict) is the *same object* every single time, quietly accumulating state across unrelated calls.', 'Never use a mutable value (`[]`, `{}`, `set()`) directly as a default argument - default to `None` and build the real one inside the function.', 'What do you think gets printed? Write it down before you run anything.', 'published', 'aa36d726775c138aa4192f85ee14afb3e9627d6284862c96c44543d21710c5a1', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (252, 'closure-nonlocal-missing', 14, 'A Counter That Cannot Count', 20, 4, NULL, 'runtime', 'This program builds a counter and calls it twice, printing each result.\n\nExample output:\n```\n1\n2\n```', 'def make_counter():\n    count = 0\n    def increment():\n        count += 1\n        return count\n    return increment\n\ncounter = make_counter()\nprint(counter())\nprint(counter())\n', 'def make_counter():\n    count = 0\n    def increment():\n        nonlocal count\n        count += 1\n        return count\n    return increment\n\ncounter = make_counter()\nprint(counter())\nprint(counter())\n', 'script', NULL, 'An inner function can *read* a variable from an enclosing function automatically, but as soon as it *assigns* to that name, Python treats it as a brand new local variable for that inner function - unless you explicitly say `nonlocal name` to mean \"the outer one\".', 'If an inner function needs to change (not just read) a variable from the function that contains it, it needs an explicit `nonlocal` declaration.', NULL, 'published', 'ed6a31171597e97443ff0395476e51dde8c31d102d2c351224e1294853eb2bc0', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (253, 'recursive-base-case-wrong-value', 14, 'A Base Case With the Wrong Value', 21, 3, NULL, 'logic', '`sum_list(numbers)` should return the sum of all the numbers in the list, recursively.\n\nExample: `sum_list([1, 2, 3])` should return `6`.', 'def sum_list(numbers):\n    if not numbers:\n        return 1\n    return numbers[0] + sum_list(numbers[1:])\n', 'def sum_list(numbers):\n    if not numbers:\n        return 0\n    return numbers[0] + sum_list(numbers[1:])\n', 'function', 'sum_list', 'A recursive function\'s base case is not just \"when to stop\" - its return value directly becomes part of the final combined answer. Getting the base case\'s *value* wrong (not just its condition) throws off every result built from it.', 'Test a recursive function on the smallest possible input *on its own* (an empty list, zero, and so on) and check the base case value by hand.', NULL, 'published', 'cdbbe712116cf2d5b16df2df15c56cd05c6b006cb8379bc577e9f7d04f4bcfdb', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (254, 'zip-silently-truncates', 14, 'zip() Drops the Leftovers', 22, 3, NULL, 'logic', '`pair_up(names, scores)` should pair each name with its score. If the lists are different lengths, the extra items should be padded with `None` rather than dropped.\n\nExample: `pair_up([\"Ada\", \"Sam\", \"Bo\"], [10, 20])` should return `[[\"Ada\", 10], [\"Sam\", 20], [\"Bo\", None]]`.', 'def pair_up(names, scores):\n    return [list(pair) for pair in zip(names, scores)]\n', 'from itertools import zip_longest\n\ndef pair_up(names, scores):\n    return [list(pair) for pair in zip_longest(names, scores)]\n', 'function', 'pair_up', '`zip()` is \"as long as the shortest sequence\" by design, which is exactly right when the lists are genuinely meant to be the same length - but a silent, wrong assumption when they might not be.', 'Before using `zip()`, check whether the two sequences are guaranteed to be the same length - if not, consider `zip_longest()`.', 'What do you think `pair_up([\"Ada\", \"Sam\", \"Bo\"], [10, 20])` returns? Write it down before you run anything.', 'published', '07d2ff2b0aaa711afb41719b35b527167c7cfe25d9852d612c809b361aa6cdff', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (255, 'enumerate-starting-index', 14, 'Off by One With enumerate()', 23, 3, NULL, 'logic', '`numbered_list(items)` should return each item labelled with its 1-based position, like `\"1: apple\"`.\n\nExample: `numbered_list([\"apple\", \"pear\"])` should return `[\"1: apple\", \"2: pear\"]`.', 'def numbered_list(items):\n    return [f\"{i}: {item}\" for i, item in enumerate(items)]\n', 'def numbered_list(items):\n    return [f\"{i}: {item}\" for i, item in enumerate(items, start=1)]\n', 'function', 'numbered_list', '`enumerate(items)` matches how Python indexes things internally (from `0`), which is often not what a human-facing \"1st, 2nd, 3rd\" numbering wants - `enumerate(items, start=1)` fixes that directly, without a separate `+1` scattered through the code.', 'If output is meant to be human-numbered from 1, use `enumerate(..., start=1)` rather than adding 1 to the result every time it is used.', NULL, 'published', '4b199dac73e608a89a6d300faf17a2a487359a3e7e2078ea6af625647ffe5101', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (256, 'bool-int-hash-collision', 14, 'True Looks Exactly Like 1', 24, 4, NULL, 'logic', '`distinct_values(items)` should return how many distinct values are in `items`, counting `True` and `1` as different values.\n\nExample: `distinct_values([1, True, 2])` should return `3`.', 'def distinct_values(items):\n    return len(set(items))\n', 'def distinct_values(items):\n    seen_types_and_values = {(type(x), x) for x in items}\n    return len(seen_types_and_values)\n', 'function', 'distinct_values', '`bool` is a subclass of `int` in Python - `True` really is `1`, and `False` really is `0`, as far as equality, hashing, and arithmetic are concerned. This is usually convenient (you can `sum()` a list of booleans to count `True`s) but it is a trap for anything that relies on telling `1` and `True` apart.', 'If `True`/`False` need to be treated as genuinely different from `1`/`0`, you cannot rely on `==`, `in`, or a plain `set`/`dict` - check the type explicitly too.', 'What do you think `distinct_values([1, True, 2])` returns? Write it down before you run anything.', 'published', 'bba831c609bd9a30606b8c9dc6688fd201d85a09263de7806c17740b46be6f20', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (257, 'tuple-sort-wrong-field', 14, 'Sorting Records by the Wrong Field', 25, 3, NULL, 'logic', '`rank_by_score(students)` should return the list of `[name, score]` pairs sorted by score, highest first.\n\nExample: `rank_by_score([[\"Bea\", 70], [\"Ada\", 90]])` should return `[[\"Ada\", 90], [\"Bea\", 70]]`.', 'def rank_by_score(students):\n    return sorted(students, reverse=True)\n', 'def rank_by_score(students):\n    return sorted(students, key=lambda s: s[1], reverse=True)\n', 'function', 'rank_by_score', 'Python compares lists (and tuples) left to right, like comparing words in a dictionary - the first element dominates the comparison unless it ties. To sort by a different field, you need an explicit `key` that picks it out.', 'When sorting a list of multi-field records, ask: am I sorting by the field I actually mean, or just by whichever field happens to come first?', 'What order do you think `rank_by_score([[\"Bea\", 70], [\"Ada\", 90]])` comes back in? Write it down before you run anything.', 'published', '615bca4f22184024ceaa9c08d3716a94006c660fbd4c0b54496a6cbc6cb5c552', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (258, 'floating-point-accumulation', 14, 'Small Errors Adding Up', 26, 3, NULL, 'logic', '`total_exact(deposit, times)` should return whether adding `deposit` to itself `times` times gives (for all practical purposes) the same result as `deposit * times`.\n\nExample: `total_exact(0.1, 10)` should return `True` (they are equal enough, even though floating-point rounding means they are not bit-for-bit identical).', 'def total_exact(deposit, times):\n    total = 0\n    for _ in range(times):\n        total += deposit\n    return total == deposit * times\n', 'import math\n\ndef total_exact(deposit, times):\n    total = 0\n    for _ in range(times):\n        total += deposit\n    return math.isclose(total, deposit * times)\n', 'function', 'total_exact', 'Floating-point numbers cannot represent most decimal fractions exactly. A single `0.1 + 0.1 + 0.1` already drifts slightly from `0.3` - repeating that addition many times only makes the gap more likely to matter, which is why financial and scientific code almost never compares floats with `==`.', 'If a loop repeatedly adds floating-point numbers, don\'t compare the running total to an exact target with `==` - use `math.isclose()`.', 'What do you think `total_exact(0.1, 10)` returns? Write it down before you run anything.', 'published', '385201c040fb2dcc82043c894a36cbfb0d8b378d5bca5f467c74699b2148be9f', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (259, 'deep-vs-shallow-copy', 14, 'A Copy That Still Shares Its Insides', 27, 4, NULL, 'logic', '`duplicate_grid(grid)` should return an independent copy of a 2D grid (a list of lists) - changing a cell in the copy should never affect the original.\n\nExample: for `grid = [[1, 2], [3, 4]]`, changing the copy\'s `[0][0]` should leave `grid[0][0]` as `1`.', 'import copy\n\ndef duplicate_grid(grid):\n    new_grid = copy.copy(grid)\n    new_grid[0][0] = 99\n    return grid[0][0]\n', 'import copy\n\ndef duplicate_grid(grid):\n    new_grid = copy.deepcopy(grid)\n    new_grid[0][0] = 99\n    return grid[0][0]\n', 'function', 'duplicate_grid', 'A shallow copy duplicates one level of container, but anything mutable *inside* it - like the rows of a 2D list - is still shared between the original and the copy. A deep copy duplicates all the way down, so nothing is shared at any level.', 'For a list of lists (or any nested mutable structure), `copy.copy()` or `list(x)` or `x[:]` is rarely enough - reach for `copy.deepcopy()`.', 'What do you think this returns for `grid = [[1, 2], [3, 4]]`? Write it down before you run anything.', 'published', 'd1713abf6cad039cedc201583ec94dab838359f3341aeea6a45b6ebd6a5b3366', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (260, 'string-method-return-ignored', 14, 'Strings Do Not Change Themselves', 28, 3, NULL, 'logic', '`clean_name(name)` should return `name` with leading/trailing spaces removed and converted to title case.\n\nExample: `clean_name(\"  ada lovelace  \")` should return `\"Ada Lovelace\"`.', 'def clean_name(name):\n    name.strip()\n    name.title()\n    return name\n', 'def clean_name(name):\n    name = name.strip()\n    name = name.title()\n    return name\n', 'function', 'clean_name', 'Strings are immutable - no string method ever changes the string you call it on. Every one of them (`.strip()`, `.upper()`, `.replace()`, `.title()`, and so on) returns a brand new string, which is silently thrown away unless you capture it.', 'If calling a string method seems to have no effect, check whether you reassigned its return value - the original string genuinely cannot change.', 'What do you think `clean_name(\"  ada lovelace  \")` returns? Write it down before you run anything.', 'published', '7f09bed2dd62379db6cf4038bb3cab51b3a717a50c15d52a04764e9e94410943', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (261, 'multiple-return-unpack-wrong-order', 14, 'Unpacked in the Wrong Order', 29, 3, NULL, 'logic', '`bmi_category(weight_kg, height_m)` should return `\"underweight\"`, `\"normal\"` or `\"overweight\"` based on BMI = weight / height^2 (under 18.5 is underweight, 18.5-25 is normal, over 25 is overweight).\n\nExample: `bmi_category(70, 1.8)` should return `\"normal\"`.', 'def compute_bmi(weight_kg, height_m):\n    return height_m, weight_kg\n\ndef bmi_category(weight_kg, height_m):\n    weight, height = compute_bmi(weight_kg, height_m)\n    bmi = weight / (height ** 2)\n    if bmi < 18.5:\n        return \"underweight\"\n    elif bmi <= 25:\n        return \"normal\"\n    return \"overweight\"\n', 'def compute_bmi(weight_kg, height_m):\n    return weight_kg, height_m\n\ndef bmi_category(weight_kg, height_m):\n    weight, height = compute_bmi(weight_kg, height_m)\n    bmi = weight / (height ** 2)\n    if bmi < 18.5:\n        return \"underweight\"\n    elif bmi <= 25:\n        return \"normal\"\n    return \"overweight\"\n', 'function', 'bmi_category', 'When a function returns multiple values, there\'s no label attached to each one - the caller matches them up purely by *position*. If the function\'s return order and the caller\'s unpacking order ever disagree, values get silently swapped with no error.', 'When unpacking multiple return values, check the exact order they were returned in, not just the names you are unpacking them into.', 'What do you think `bmi_category(70, 1.8)` returns? Write it down before you run anything.', 'published', '76aa0071dc5a2c5fddd599839135e8b32570533545bc61d36591957efdd663c7', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (262, 'recursion-shared-mutable-accumulator', 14, 'An Accumulator That Remembers Too Much', 30, 4, NULL, 'logic', 'This program collects the even numbers from two separate lists, one after another, and prints the result for just the second list.\n\nExample output: `[]`', 'def collect_evens(numbers, result=[]):\n    if not numbers:\n        return result\n    if numbers[0] % 2 == 0:\n        result.append(numbers[0])\n    return collect_evens(numbers[1:], result)\n\nfirst = collect_evens([1, 2, 3, 4])\nsecond = collect_evens([5, 7])\nprint(second)\n', 'def collect_evens(numbers, result=None):\n    if result is None:\n        result = []\n    if not numbers:\n        return result\n    if numbers[0] % 2 == 0:\n        result.append(numbers[0])\n    return collect_evens(numbers[1:], result)\n\nfirst = collect_evens([1, 2, 3, 4])\nsecond = collect_evens([5, 7])\nprint(second)\n', 'script', NULL, 'A mutable default argument is just as dangerous in a recursive helper as in any other function - the recursive calls that pass `result` explicitly are fine, but any *fresh*, top-level call that relies on the default shares that one surviving list with every other such call.', 'A recursive function with a mutable accumulator default needs the same `None`-then-build-inside fix as any other mutable default.', 'What do you think gets printed? Write it down before you run anything.', 'published', '24dbb2ac2e3468acca272853c3a54de7a8a616066ec357a575d32a8830ce5058', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (263, 'generator-exhausted-second-use', 14, 'A Generator That Only Works Once', 31, 3, NULL, 'logic', '`count_and_list_evens(numbers)` should return `[count, list_of_evens]`, where `count` is how many even numbers there are, counted from the same values that end up in the list.\n\nExample: `count_and_list_evens([1, 2, 3, 4])` should return `[2, [2, 4]]`.', 'def count_and_list_evens(numbers):\n    evens = (n for n in numbers if n % 2 == 0)\n    count = sum(1 for _ in evens)\n    result = list(evens)\n    return [count, result]\n', 'def count_and_list_evens(numbers):\n    evens = [n for n in numbers if n % 2 == 0]\n    count = len(evens)\n    return [count, evens]\n', 'function', 'count_and_list_evens', 'A generator produces its values lazily, one at a time, and permanently forgets each one once it\'s given out - it cannot be \"rewound\" or read twice. A list, by contrast, can be read as many times as you like.', 'If you need to use the same sequence of values more than once, build a list (or tuple) instead of a generator.', 'What do you think `count_and_list_evens([1, 2, 3, 4])` returns? Write it down before you run anything.', 'published', '1abcab0b53fa181b587cfd67cdb1e877e2e8b303f4cebc4128f5900d34793d6f', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (264, 'list-aliasing-via-return', 14, 'A Function That Hands Back Its Own List', 32, 3, NULL, 'logic', '`process_and_check(original)` should sort a *copy* of `original`, and return whether the original list is unchanged.\n\nExample: `process_and_check([3, 1, 2])` should return `True`.', 'def get_sorted(data):\n    data.sort()\n    return data\n\ndef process_and_check(original):\n    before = original.copy()\n    get_sorted(original)\n    return original == before\n', 'def get_sorted(data):\n    result = data.copy()\n    result.sort()\n    return result\n\ndef process_and_check(original):\n    before = original.copy()\n    get_sorted(original)\n    return original == before\n', 'function', 'process_and_check', 'Passing a list into a function does not copy it - the parameter name is just another name for the exact same list object. Any in-place change made to it inside the function is visible to the caller too, whether that was intended or not.', 'If a function is meant to leave its argument unchanged, check whether it actually makes a copy before mutating anything - or whether it just mutates the original and returns it.', 'What do you think `process_and_check([3, 1, 2])` returns? Write it down before you run anything.', 'published', '5f638727482677d93be8d27553ae3ce56bcab7e35354dc7ad5b2ec1af50c7158', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (265, 'sort-case-sensitive-unwanted', 14, 'Sorting That Puts Capitals First', 33, 3, NULL, 'logic', '`alphabetical_order(words)` should return `words` sorted alphabetically, ignoring case.\n\nExample: `alphabetical_order([\"banana\", \"Apple\", \"cherry\"])` should return `[\"Apple\", \"banana\", \"cherry\"]`.', 'def alphabetical_order(words):\n    return sorted(words)\n', 'def alphabetical_order(words):\n    return sorted(words, key=str.lower)\n', 'function', 'alphabetical_order', 'Text sorting compares the underlying character codes, and in that scheme, capital letters all come before lowercase ones - \"ignoring case\" is not automatic, it requires an explicit `key` that normalises case before comparing.', 'If sorted text looks like capitals are oddly grouped at the start, add `key=str.lower` (or `key=str.upper`).', 'What order do you think `alphabetical_order([\"banana\", \"Apple\", \"cherry\"])` comes back in? Write it down before you run anything.', 'published', 'b69c743381dac4bbecaedf478543ef4ea6ad5c5430584d520ad6d9e20db9a02c', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (266, 'chained-assignment-aliasing', 14, 'Two Names Created Together, Still One List', 34, 3, NULL, 'logic', '`make_two_teams()` should return two separate, empty team lists.\n\nExample: after calling it, adding a player to the first team should not add them to the second.', 'def make_two_teams():\n    team_a = team_b = []\n    team_a.append(\"Ada\")\n    return [team_a, team_b]\n', 'def make_two_teams():\n    team_a = []\n    team_b = []\n    team_a.append(\"Ada\")\n    return [team_a, team_b]\n', 'function', 'make_two_teams', 'Chained assignment (`a = b = value`) evaluates `value` exactly once and assigns that same object to every name in the chain. For an immutable value (like a number) this never matters; for a mutable one (like a list), every name ends up pointing at the exact same object.', 'Never use chained assignment (`a = b = ...`) to try to create two independent mutable containers - create each one separately.', 'What do you think this returns? Write it down before you run anything.', 'published', '0566c4ddd430a325d2750c2de72e9f7afa1462a36d6164d9a1ad52f5783f04de', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (267, 'slice-copy-vs-direct-reference', 14, 'Which Assignment Actually Copies?', 35, 3, NULL, 'logic', '`independent_copy(original)` should return a copy of `original`, change the copy\'s first item to `\"changed\"`, and return whether the original list stayed the same.\n\nExample: `independent_copy([1, 2, 3])` should return `True`.', 'def independent_copy(original):\n    before = list(original)\n    copy_of_list = original\n    copy_of_list[0] = \"changed\"\n    return original == before\n', 'def independent_copy(original):\n    before = list(original)\n    copy_of_list = original[:]\n    copy_of_list[0] = \"changed\"\n    return original == before\n', 'function', 'independent_copy', 'Plain assignment (`new_name = existing_list`) never copies a list - it only ever creates another name pointing at the same object. A real copy needs an explicit copying operation: a full slice `[:]`, `.copy()`, `list(...)`, or `copy.deepcopy()` for nested structures.', 'A variable named \"copy\" is not automatically one - check it was built with an actual copying operation, not plain assignment.', 'What do you think `independent_copy([1, 2, 3])` returns? Write it down before you run anything.', 'published', '85ad80b72fd9a6fa9e21f4a530c510f720e327b4f64a267ed848a9cfb734577b', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (268, 'recursion-accidental-global-state', 14, 'A Running Total That Never Resets', 36, 4, NULL, 'logic', 'This program adds up the numbers in two separate lists, one after another, and should print the total for just the second list.\n\nExample output: `30`', 'running_total = 0\n\ndef add_all(numbers):\n    global running_total\n    for n in numbers:\n        running_total += n\n    return running_total\n\nfirst = add_all([1, 2, 3])\nsecond = add_all([10, 10, 10])\nprint(second)\n', 'def add_all(numbers):\n    total = 0\n    for n in numbers:\n        total += n\n    return total\n\nfirst = add_all([1, 2, 3])\nsecond = add_all([10, 10, 10])\nprint(second)\n', 'script', NULL, 'A `global` variable is shared across every call to every function that declares it - useful when you genuinely want persistent shared state, but a trap when a function is meant to compute an independent, fresh result each time it is called.', 'If a function is supposed to give an independent answer on every call, it should use a local variable, not a shared global one.', 'What do you think gets printed? Write it down before you run anything.', 'published', 'a8cc445a0d5261f52d69c6d4f30818bba3bf3c7f7df871dabc486c006b2fb234', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (269, 'float-key-dict-lookup-mismatch', 14, 'A Computed Float as a Dictionary Key', 37, 4, NULL, 'logic', '`price_for_weight(prices, weight)` should look up the price for a given `weight` in kg, where `weight` is built up by repeatedly adding `0.1`.\n\nExample: for `prices = {0.3: 5}`, calling with a weight built from `0.1 + 0.1 + 0.1` should still find the price.', 'def price_for_weight(prices, weight):\n    total_weight = 0\n    for _ in range(3):\n        total_weight += weight\n    return prices.get(total_weight)\n', 'import math\n\ndef price_for_weight(prices, weight):\n    total_weight = 0\n    for _ in range(3):\n        total_weight += weight\n    for key, price in prices.items():\n        if math.isclose(key, total_weight):\n            return price\n    return None\n', 'function', 'price_for_weight', 'Dictionary and set lookups rely on exact equality (and exact hashing). A float computed through arithmetic almost never matches a float literal exactly, even when they *look* the same when printed - this combines floating-point imprecision with how dictionaries actually search for keys.', 'Never use a computed (not literal) float as a dictionary key for lookup - compare with tolerance instead, or key by something exact (like an integer count of cents, not pounds).', 'What do you think `price_for_weight({0.3: 5}, 0.1)` returns? Write it down before you run anything.', 'published', 'daaf8c19efc95a52d419186ec26209ec3fa52cc84c3b909611ed8921b6de5aeb', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (270, 'loop-variable-persists-after-loop', 14, 'The Loop Variable Outlives the Loop', 38, 3, NULL, 'logic', '`last_even_or_default(numbers, default)` should return the last even number in the list, or `default` if there are none at all.\n\nExample: `last_even_or_default([1, 2, 3, 4], 0)` should return `4`. `last_even_or_default([1, 3], 0)` should return `0`.', 'def last_even_or_default(numbers, default):\n    for n in numbers:\n        if n % 2 == 0:\n            result = n\n    return result\n', 'def last_even_or_default(numbers, default):\n    result = default\n    for n in numbers:\n        if n % 2 == 0:\n            result = n\n    return result\n', 'function', 'last_even_or_default', 'Unlike some languages, a variable assigned inside a loop or `if` block in Python is not scoped to just that block - it exists in the whole enclosing function from the moment it\'s first assigned, but *only* if that assignment actually ran. Relying on a fallback value from before the loop needs that fallback set up explicitly first.', 'If a variable is only assigned conditionally inside a loop, check what happens on the path where that condition is never true.', NULL, 'published', '623192a277756d57e72766f2e0da01ab21bc68c6b97f4d0a6c45fcd6b81bf065', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (271, 'keys-vs-values-mixup', 14, 'Dictionaries Iterate Over Keys, Not Values', 39, 3, NULL, 'logic', '`total_stock(inventory)` should return the sum of all the quantities in the `inventory` dictionary (a mapping of item name to quantity).\n\nExample: `total_stock({\"apples\": 5, \"pears\": 3})` should return `8`.', 'def total_stock(inventory):\n    total = 0\n    for item in inventory:\n        total += item\n    return total\n', 'def total_stock(inventory):\n    total = 0\n    for item in inventory.values():\n        total += item\n    return total\n', 'function', 'total_stock', 'Iterating directly over a dictionary always gives you its keys - that\'s true for a plain `for` loop, and for `in` membership checks too. To get values, use `.values()`; to get both together, use `.items()`.', 'If a loop over a dictionary seems to be working with the wrong kind of data, check whether you meant `.values()` or `.items()` instead of looping over the dictionary directly.', 'What do you think happens when you run `total_stock({\"apples\": 5, \"pears\": 3})`? Write it down before you run anything.', 'published', '09433a5cb4d5b3424c2e0c36eecac3972548a6e910eabc7b899fda83a786a7aa', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (272, 'recursive-factorial-wrong-base-case', 14, 'A Base Case That Collapses Everything to Zero', 40, 3, NULL, 'logic', '`factorial(n)` should return `n!` (n factorial), the product of all whole numbers from 1 to `n`.\n\nExample: `factorial(4)` should return `24`.', 'def factorial(n):\n    if n == 0:\n        return 0\n    return n * factorial(n - 1)\n', 'def factorial(n):\n    if n == 0:\n        return 1\n    return n * factorial(n - 1)\n', 'function', 'factorial', 'A recursive base case\'s return value needs to be the identity for whatever operation is combining the results - `0` for addition (adding nothing changes nothing), but `1` for multiplication (multiplying by 1 changes nothing). Using addition\'s identity in a multiplication chain wipes out the whole result.', 'When a recursive function\'s result builds up through multiplication, check its base case returns `1`, not `0`.', 'What do you think `factorial(4)` returns? Write it down before you run anything.', 'published', 'd94c1b43b52f3c479b6b722330fc88bfb033be6a7f7848a57296f40daf096142', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (273, 'shallow-copy-of-dict-with-list-values', 14, 'A Dictionary Copy That Still Shares Its Lists', 41, 4, NULL, 'logic', '`add_to_backup(records)` should make a backup copy of `records` (a dict mapping names to lists), add an entry to the backup only, and return whether the original stayed unchanged.\n\nExample: `add_to_backup({\"Ada\": [1, 2]})` should return `True`.', 'def add_to_backup(records):\n    before = {k: list(v) for k, v in records.items()}\n    backup = records.copy()\n    backup[\"Ada\"].append(99)\n    return records == before\n', 'import copy\n\ndef add_to_backup(records):\n    before = {k: list(v) for k, v in records.items()}\n    backup = copy.deepcopy(records)\n    backup[\"Ada\"].append(99)\n    return records == before\n', 'function', 'add_to_backup', 'Shallow copying applies at every level that holds mutable values, not just lists of lists - a dictionary whose values are lists has exactly the same shared-reference trap as a list of lists.', 'If a dictionary (or list) contains mutable values like lists, a shallow `.copy()` is not enough to make it fully independent - use `copy.deepcopy()`.', 'What do you think `add_to_backup({\"Ada\": [1, 2]})` returns? Write it down before you run anything.', 'published', '240acbc42397b8a0429ece7c781b805c10a91ed63ae558fbe0a984c3da6a2552', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (274, 'truthiness-none-vs-falsy', 14, 'Confusing \"No Value\" With \"Zero\"', 42, 3, NULL, 'logic', '`describe_score(score)` should return `\"no score recorded\"` if `score` is `None`, and otherwise describe the actual number (e.g. `\"scored 0\"`).\n\nExample: `describe_score(0)` should return `\"scored 0\"`. `describe_score(None)` should return `\"no score recorded\"`.', 'def describe_score(score):\n    if not score:\n        return \"no score recorded\"\n    return f\"scored {score}\"\n', 'def describe_score(score):\n    if score is None:\n        return \"no score recorded\"\n    return f\"scored {score}\"\n', 'function', 'describe_score', '`None`, `0`, `0.0`, `\"\"` and `[]` are all \"falsy\" in a boolean context, but they do not all mean the same thing - `0` is a perfectly valid, meaningful value, while `None` specifically means \"nothing here at all\". When that distinction matters, check `is None` explicitly rather than relying on general truthiness.', 'If a legitimate value of `0`, `\"\"` or `[]` needs to be treated differently from a genuinely missing value, use `is None` rather than `if not x:`.', 'What do you think `describe_score(0)` returns? Write it down before you run anything.', 'published', 'ab532bab9495a6cc6bdda20d8a398c2dd0a382f3370d07874a628b1f2a7de5f6', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (275, 'min-by-length-missing-key', 14, 'The \"Shortest\" Name, Alphabetically', 43, 3, NULL, 'logic', '`shortest_name(names)` should return the shortest name in the list (by number of characters).\n\nExample: `shortest_name([\"Alexandra\", \"Bo\", \"Christopher\"])` should return `\"Bo\"`.', 'def shortest_name(names):\n    return min(names)\n', 'def shortest_name(names):\n    return min(names, key=len)\n', 'function', 'shortest_name', '`min()` and `max()` default to comparing items directly (alphabetically, for strings) - to compare by some other property, like length, you need an explicit `key` function that extracts that property.', 'If `min()`/`max()`/`sorted()` is meant to compare by something other than the raw value itself (length, a specific field, case-insensitively), check for a `key=` argument.', 'What do you think `shortest_name([\"Alexandra\", \"Bo\", \"Christopher\"])` returns? Write it down before you run anything.', 'published', 'de12ffa6e4602c186bbfe8d3bff5ae3a96b61cb528860eed56122fedaceae707', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (276, 'grade-calculator', 15, 'Grade Calculator', 1, 4, NULL, 'mixed', '`calculate_grade(scores)` takes a list of test scores (0-100) and returns a grade:\n\n- `\"Distinction\"` if the average is 70 or above\n- `\"Pass\"` if the average is 50 or above (but below 70)\n- `\"Fail\"` otherwise\n- `\"No scores\"` if the list is empty\n\nExample: `calculate_grade([85, 90, 95])` should return `\"Distinction\"`.', 'def calculate_grade(scores):\n    total = 0\n    for score in scores:\n        total = total + score\n    average = total / len(scores)\n    if average > 70:\n        return \"Distinction\"\n    elif average > 50:\n        return \"Pass\"\n    else:\n        return \"Fail\"\n', 'def calculate_grade(scores):\n    if len(scores) == 0:\n        return \"No scores\"\n    total = 0\n    for score in scores:\n        total = total + score\n    average = total / len(scores)\n    if average >= 70:\n        return \"Distinction\"\n    elif average >= 50:\n        return \"Pass\"\n    else:\n        return \"Fail\"\n', 'function', 'calculate_grade', 'Two separate bugs here. First, dividing by `len(scores)` crashes on an empty list because there\'s no guard for that case. Second, `>` silently excludes the boundary value itself - the brief says \"70 or above\", which means `>=`, not `>`. Neither bug stops the other from being tested, so fixing one doesn\'t reveal the other automatically - you need to check both the empty case and the exact boundaries.', 'For any function with thresholds, test the exact boundary values by hand, and always ask what happens with an empty or missing input.', NULL, 'published', 'ceac46023d6e00ddb53fa86ed73cf3eaeae69912fbeaaa1e526640fc5f156c9b', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (277, 'caesar-cipher', 15, 'Caesar Cipher', 2, 4, NULL, 'mixed', '`encode(text, shift)` should shift every letter in `text` forward by `shift` places in the alphabet, wrapping around from Z back to A (and z back to a). Non-letter characters (spaces, punctuation) should be left unchanged, and case should be preserved.\n\nExample: `encode(\"abc\", 1)` should return `\"bcd\"`. `encode(\"xyz\", 3)` should return `\"abc\"` (wrapping around).', 'def encode(text, shift):\n    result = \"\"\n    for ch in text:\n        code = ord(ch) + shift\n        result += chr(code)\n    return result\n', 'def encode(text, shift):\n    result = \'\'\n    for ch in text:\n        if ch.isupper():\n            result += chr((ord(ch) - ord(\'A\') + shift) % 26 + ord(\'A\'))\n        elif ch.islower():\n            result += chr((ord(ch) - ord(\'a\') + shift) % 26 + ord(\'a\'))\n        else:\n            result += ch\n    return result\n', 'function', 'encode', 'Two bugs stack up here. Shifting by adding directly to the character code never wraps back around the alphabet - working in 0-25 alphabet positions with `% 26` fixes that. Separately, the code shifts *every* character, including spaces and punctuation, when only letters should move - those need an explicit check and a pass-through branch.', 'For cipher-style problems, test wraparound (shifting past \'z\') and non-letter characters (spaces, punctuation) as two separate boundary cases.', NULL, 'published', 'f30096f3a735a9e7be3bb8ac818429c8cddc3be37f6c7c39ebd177d055124450', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (278, 'tic-tac-toe-winner', 15, 'Tic-Tac-Toe Winner', 3, 4, NULL, 'logic', '`winner(board)` takes a 3x3 list of lists, where each cell is `\"X\"`, `\"O\"`, or `\"\"`. It should return `\"X\"` or `\"O\"` if that player has three in a row (row, column, or diagonal), `\"Draw\"` if the board is full with no winner, or `None` if the game is still in progress.\n\nExample: a board with `\"X\"` down the main diagonal and nothing else should return `\"X\"`.', 'def winner(board):\n    for row in board:\n        if row[0] == row[1] == row[2] != \'\':\n            return row[0]\n    for col in range(3):\n        if board[0][col] == board[1][col] == board[2][col] != \'\':\n            return board[0][col]\n    return None\n', 'def winner(board):\n    lines = []\n    for row in board:\n        lines.append(row)\n    for col in range(3):\n        lines.append([board[0][col], board[1][col], board[2][col]])\n    lines.append([board[0][0], board[1][1], board[2][2]])\n    lines.append([board[0][2], board[1][1], board[2][0]])\n    for line in lines:\n        if line[0] == line[1] == line[2] != \'\':\n            return line[0]\n    if all(cell != \'\' for row in board for cell in row):\n        return \'Draw\'\n    return None\n', 'function', 'winner', 'Tic-tac-toe has 8 possible winning lines - 3 rows, 3 columns, and 2 diagonals - and missing any category means some genuine wins go undetected. Separately, \"no winner found\" isn\'t the same as \"game over\" - a full board with no three-in-a-row is a draw, which needs its own explicit check.', 'For a grid-based game, list every possible winning line on paper first, then check your code actually covers each one.', NULL, 'published', 'd2f4d3c0128491508f57568cc6cbae78abad574d9e0dc3b84d0aede13e611730', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (279, 'bank-account', 15, 'Bank Account', 4, 5, NULL, 'mixed', 'An `Account` class should track its own balance and its own list of transactions independently from every other account, and should refuse to withdraw more than the current balance.\n\n`run_bank_demo(initial_a, initial_b, withdraw_amount)` creates two accounts, withdraws `withdraw_amount` from the first, and returns `(account_a.balance, account_b.balance, len(account_b.transactions))`.', 'class Account:\n    transactions = []\n\n    def __init__(self, balance=0):\n        self.balance = balance\n\n    def withdraw(self, amount):\n        self.balance -= amount\n        self.transactions.append(amount)\n        return self.balance\n\n\ndef run_bank_demo(initial_a, initial_b, withdraw_amount):\n    a = Account(initial_a)\n    b = Account(initial_b)\n    a.withdraw(withdraw_amount)\n    return [a.balance, b.balance, len(b.transactions)]\n', 'class Account:\n    def __init__(self, balance=0):\n        self.balance = balance\n        self.transactions = []\n\n    def withdraw(self, amount):\n        if amount > self.balance:\n            raise ValueError(\"Insufficient funds\")\n        self.balance -= amount\n        self.transactions.append(amount)\n        return self.balance\n\n\ndef run_bank_demo(initial_a, initial_b, withdraw_amount):\n    a = Account(initial_a)\n    b = Account(initial_b)\n    a.withdraw(withdraw_amount)\n    return [a.balance, b.balance, len(b.transactions)]\n', 'function', 'run_bank_demo', 'A mutable value defined directly under `class Account:` (rather than inside `__init__` with `self.`) is a class attribute, shared by every single instance - exactly the same trap as a mutable default argument, just in a different place. Separately, a withdrawal method that never checks the balance first will happily go negative, which real bank accounts should never allow.', 'Any mutable value (a list, dict, or another object) defined directly under a class line, not inside `__init__` with `self.`, is shared across every instance - give each instance its own copy in `__init__` instead.', NULL, 'published', 'c1760400678fdbc4ad310121c279866e89d47bb3b8edf051772eeb289770a6f9', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (280, 'inventory-manager', 15, 'Inventory Manager', 5, 4, NULL, 'mixed', '`process_orders(stock, orders)` takes a stock dictionary (item name to quantity) and a list of `(item, quantity)` orders. It should reduce stock for each order, ignore orders for items not in stock, and return `(updated_stock, total_sold)`.\n\nExample: `process_orders({\"apples\": 10, \"pears\": 5}, [(\"apples\", 3)])` should return `({\"apples\": 7, \"pears\": 5}, 3)`.', 'def process_orders(stock, orders):\n    total_sold = 0\n    for item, qty in orders:\n        stock[item] -= qty\n        stock[item] -= qty\n        total_sold += qty\n    return [stock, total_sold]\n', 'def process_orders(stock, orders):\n    total_sold = 0\n    for item, qty in orders:\n        if item not in stock:\n            continue\n        stock[item] -= qty\n        total_sold += qty\n    return [stock, total_sold]\n', 'function', 'process_orders', 'Two independent bugs here: a straightforwardly duplicated line that silently double-counts every sale, and a missing guard for orders that reference stock that doesn\'t exist. Neither bug masks the other - fixing the duplicate still leaves the `KeyError` waiting for the next test that orders something unstocked.', 'Read every line as if it might be an accidental duplicate, especially inside a loop - and always test with an input that references something that doesn\'t exist yet.', NULL, 'published', '8a3a193554648f15a4008b6aed48cd4cf2263ee66ae368747260161333269e44', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (281, 'prime-sieve', 15, 'Prime Sieve', 6, 5, NULL, 'logic', '`primes_up_to(n)` should return a list of every prime number from 2 up to and including `n`.\n\nExample: `primes_up_to(10)` should return `[2, 3, 5, 7]`.', 'def primes_up_to(n):\n    is_prime = [True] * n\n    is_prime[0] = False\n    for i in range(2, n):\n        if is_prime[i]:\n            for multiple in range(i * 2, n, i):\n                is_prime[multiple] = False\n    return [i for i in range(n) if is_prime[i]]\n', 'def primes_up_to(n):\n    is_prime = [True] * (n + 1)\n    is_prime[0] = is_prime[1] = False\n    for i in range(2, n + 1):\n        if is_prime[i]:\n            for multiple in range(i * i, n + 1, i):\n                is_prime[multiple] = False\n    return [i for i in range(n + 1) if is_prime[i]]\n', 'function', 'primes_up_to', 'This classic algorithm has two boundary mistakes stacked together: the list size and loop bounds don\'t reach the upper limit `n` itself (an inclusive-range off-by-one), and `1` - which is not prime by definition - is never explicitly excluded the way `0` is.', 'For range-based algorithms, always test the smallest and largest values your range is supposed to include, by hand.', NULL, 'published', '67edda7487e3fbd25e8f33a75b9e7a58c5c1486c5b828565836a6a3df6b65d30', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (282, 'merge-sort', 15, 'Merge Sort', 7, 5, NULL, 'logic', '`merge_sort(items)` should return a new list containing every item from `items`, sorted in ascending order.\n\nExample: `merge_sort([5, 2, 4, 1, 3])` should return `[1, 2, 3, 4, 5]`.', 'def merge_sort(items):\n    if len(items) <= 1:\n        return items\n    mid = len(items) // 2\n    left = merge_sort(items[:mid])\n    right = merge_sort(items[mid:])\n    merged = []\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i])\n            i += 1\n        else:\n            merged.append(right[j])\n            j += 1\n    return merged\n', 'def merge_sort(items):\n    if len(items) <= 1:\n        return items\n    mid = len(items) // 2\n    left = merge_sort(items[:mid])\n    right = merge_sort(items[mid:])\n    merged = []\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i])\n            i += 1\n        else:\n            merged.append(right[j])\n            j += 1\n    merged.extend(left[i:])\n    merged.extend(right[j:])\n    return merged\n', 'function', 'merge_sort', 'The classic merge step compares the fronts of two already-sorted halves one at a time - but it only keeps comparing while *both* halves still have items left. The moment one half runs dry, the loop exits, and anything still waiting in the other half needs to be tacked on afterwards - a step that\'s easy to forget since the function \"looks finished\" without it.', 'After any loop that processes two lists in lockstep, check: could one list still have leftover items when the loop ends? If so, they need handling separately.', NULL, 'published', '30e5277c11f847b0913126692287dcffd6ba67d285066427f3d4e4940c274173', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (283, 'linked-list', 15, 'Linked List', 8, 5, NULL, 'logic', 'Reversing a linked list should produce the same values in reverse order.\n\n`reverse_to_list(values)` builds a linked list from `values`, reverses it, and returns the result as a plain Python list.\n\nExample: `reverse_to_list([1, 2, 3, 4])` should return `[4, 3, 2, 1]`.', 'class Node:\n    def __init__(self, value, next=None):\n        self.value = value\n        self.next = next\n\n\ndef reverse(head):\n    prev = None\n    current = head\n    while current:\n        current.next = prev\n        prev = current\n        current = current.next\n    return prev\n\n\ndef reverse_to_list(values):\n    head = None\n    for v in reversed(values):\n        head = Node(v, head)\n    reversed_head = reverse(head)\n    result = []\n    node = reversed_head\n    while node:\n        result.append(node.value)\n        node = node.next\n    return result\n', 'class Node:\n    def __init__(self, value, next=None):\n        self.value = value\n        self.next = next\n\n\ndef reverse(head):\n    prev = None\n    current = head\n    while current:\n        next_node = current.next\n        current.next = prev\n        prev = current\n        current = next_node\n    return prev\n\n\ndef reverse_to_list(values):\n    head = None\n    for v in reversed(values):\n        head = Node(v, head)\n    reversed_head = reverse(head)\n    result = []\n    node = reversed_head\n    while node:\n        result.append(node.value)\n        node = node.next\n    return result\n', 'function', 'reverse_to_list', 'Reversing a linked list in place needs to remember where to go next *before* changing the pointer that normally tells you that. Overwrite `current.next` first, and the very next line that tries to follow it is actually following the just-changed pointer, not the original list - losing everything after the first node.', 'When reassigning a pointer/reference you still need to read from, save the original value in a temporary variable first.', NULL, 'published', '671f58841a4d425f4f195eff0ea5c50ccbfc70f1f2d14c8a33f469f638df2ca9', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (284, 'text-statistics', 15, 'Text Statistics', 9, 4, NULL, 'mixed', '`text_stats(text)` should return a dictionary `{\"word_count\": ..., \"avg_word_length\": ...}` describing the words in `text`, ignoring surrounding punctuation. An empty (or whitespace-only) `text` should return `{\"word_count\": 0, \"avg_word_length\": 0}`.\n\nExample: `text_stats(\"Hello, world!\")` should return `{\"word_count\": 2, \"avg_word_length\": 5.0}` (ignoring the comma and exclamation mark).', 'def text_stats(text):\n    words = text.split()\n    return {\"word_count\": len(words), \"avg_word_length\": sum(len(w) for w in words) / len(words)}\n', 'def text_stats(text):\n    words = text.split()\n    if not words:\n        return {\"word_count\": 0, \"avg_word_length\": 0}\n    cleaned = [w.strip(\'.,!?;:\"\\\'\') for w in words]\n    return {\"word_count\": len(cleaned), \"avg_word_length\": sum(len(w) for w in cleaned) / len(cleaned)}\n', 'function', 'text_stats', 'Splitting text into words is the easy part - the real care is in what counts as a \"word\" (should trailing punctuation count towards its length?) and what happens for degenerate input like an empty string, which needs its own explicit, non-crashing answer.', 'For any text-processing function, test with punctuation attached to words, and with empty or whitespace-only input.', NULL, 'published', 'c224887fc57f3fc4e45c364b3f2a048de25298f137d37916230082cbdb666278', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (285, 'shopping-cart', 15, 'Shopping Cart', 10, 4, NULL, 'logic', '`total_cost(prices, discount_percent)` should add up `prices`, then apply a percentage discount to the total, rounded to 2 decimal places.\n\nExample: `total_cost([10, 20], 10)` should return `27.0` (30 total, minus 10%).', 'def total_cost(prices, discount_percent):\n    total = sum(prices)\n    discount = total - discount_percent / 100\n    return round(total - discount, 2)\n', 'def total_cost(prices, discount_percent):\n    total = sum(prices)\n    discount = total * (discount_percent / 100)\n    return round(total - discount, 2)\n', 'function', 'total_cost', 'A percentage discount needs to scale *with* the total - doubling the total should double the discount amount too. A formula built from subtraction instead of multiplication breaks that relationship entirely, and the wrongness is easy to miss unless you check a concrete example by hand.', 'For any calculation involving a percentage, sanity-check it on a round, easy number by hand (like 10% of 30) before trusting the formula.', NULL, 'published', 'c0b51f24513338eb363ddac9f3020286f7cd5d3025ea3719c164b357fa956fbc', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (286, 'hangman-progress', 15, 'Hangman Progress Tracker', 11, 4, NULL, 'mixed', '`play_round(word, guessed_letters, new_guess)` should add `new_guess` to `guessed_letters`, then return `[masked_word, solved]` - the word with unguessed letters replaced by `_`, and whether every letter has now been guessed.\n\nExample: `play_round(\"cat\", [\"c\"], \"a\")` should return `[\"ca_\", False]`.', 'def masked_word(word, guessed_letters):\n    result = \"\"\n    for letter in word:\n        if letter in guessed_letters:\n            result += letter\n        else:\n            result += \"_\"\n    return result\n\ndef is_solved(word, guessed_letters):\n    for letter in word:\n        if letter not in guessed_letters:\n            return True\n    return False\n\ndef play_round(word, guessed_letters, new_guess):\n    masked = masked_word(word, guessed_letters)\n    solved = is_solved(word, guessed_letters)\n    guessed_letters.append(new_guess)\n    return [masked, solved]\n', 'def masked_word(word, guessed_letters):\n    result = \"\"\n    for letter in word:\n        if letter in guessed_letters:\n            result += letter\n        else:\n            result += \"_\"\n    return result\n\ndef is_solved(word, guessed_letters):\n    for letter in word:\n        if letter not in guessed_letters:\n            return False\n    return True\n\ndef play_round(word, guessed_letters, new_guess):\n    guessed_letters.append(new_guess)\n    masked = masked_word(word, guessed_letters)\n    solved = is_solved(word, guessed_letters)\n    return [masked, solved]\n', 'function', 'play_round', 'Two independent mistakes combine here: a genuinely inverted boolean condition in `is_solved`, and an ordering mistake in `play_round` that uses stale data from before the latest guess was recorded.', 'When a function combines several steps, check both the correctness of each step on its own, and the order they run in.', 'What do you think `play_round(\"cat\", [\"c\"], \"a\")` returns? Write it down before you run anything.', 'published', 'dad43c28e7e5b2293ddf3ba816391c39ca1ecd244d6865e67447bd8448a37c59', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (287, 'rock-paper-scissors-judge', 15, 'Rock, Paper, Scissors Judge', 12, 4, NULL, 'mixed', '`judge(player1, player2)` should return `\"Player 1\"`, `\"Player 2\"`, or `\"Draw\"` for a round of rock-paper-scissors, where rock beats scissors, scissors beats paper, and paper beats rock.\n\nExample: `judge(\"rock\", \"scissors\")` should return `\"Player 1\"`.', 'def beats(a, b):\n    winning_pairs = [(\"rock\", \"scissors\"), (\"paper\", \"scissors\"), (\"scissors\", \"paper\")]\n    return (a, b) in winning_pairs\n\ndef judge(player1, player2):\n    p1 = player1.lower()\n    p2 = player2.lower()\n    if p1 = p2:\n        return \"Draw\"\n    if beats(p1, p2):\n        return \"Player 1\"\n    return \"Player 2\"\n', 'def beats(a, b):\n    winning_pairs = [(\"rock\", \"scissors\"), (\"paper\", \"rock\"), (\"scissors\", \"paper\")]\n    return (a, b) in winning_pairs\n\ndef judge(player1, player2):\n    p1 = player1.lower()\n    p2 = player2.lower()\n    if p1 == p2:\n        return \"Draw\"\n    if beats(p1, p2):\n        return \"Player 1\"\n    return \"Player 2\"\n', 'function', 'judge', 'A syntax error hides behind a logic error here - until the `=`/`==` typo is fixed, the code never even runs far enough to reveal that one of the winning pairs is simply wrong.', 'Fix crashes first so the code can actually run, then double-check the underlying rules/logic separately - do not assume fixing the crash fixes everything.', NULL, 'published', '1e151ea722d3ff3ce811387f00e6b8f947e44383b5b59dcf52eb626c6a255f59', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (288, 'dice-roll-tally', 15, 'Dice Roll Tally', 13, 4, NULL, 'mixed', '`tally_rolls(rolls)` should return a dictionary counting how many times each number 1-6 appears in `rolls`, including numbers that never appeared (with a count of 0).\n\nExample: `tally_rolls([1, 1, 3])` should return `{1: 2, 2: 0, 3: 1, 4: 0, 5: 0, 6: 0}`.', 'def tally_rolls(rolls):\n    counts = {}\n    for n in range(1, 6):\n        counts[n] = 0\n    for roll in rolls:\n        counts[roll] += 1\n    return counts\n', 'def tally_rolls(rolls):\n    counts = {}\n    for n in range(1, 7):\n        counts[n] = 0\n    for roll in rolls:\n        counts[roll] = counts[roll] + 1\n    return counts\n', 'function', 'tally_rolls', 'A six-sided die needs faces 1 through 6 inclusive - `range(1, 7)`, not `range(1, 6)`. Missing the last value here causes a crash rather than a silently wrong answer, since the dictionary genuinely has no entry to look up.', 'When setting up a dictionary (or list) to cover a fixed range of values, count the endpoints by hand and check against `range()`\'s \"stop before\" behaviour.', 'What do you think `tally_rolls([6, 6])` returns? Write it down before you run anything.', 'published', 'c05d35084ae6471cafb8b4e1fe0efac62e2b6991f9f83b1ab40efffb618e67b6', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (289, 'quiz-scorer', 15, 'Quiz Scorer', 14, 4, NULL, 'mixed', '`score_quiz(answers, correct_answers)` should return how many answers match the correct answers (case-insensitively), out of the total number of questions.\n\nExample: `score_quiz([\"A\", \"b\", \"C\"], [\"a\", \"B\", \"D\"])` should return `[2, 3]`.', 'def score_quiz(answers, correct_answers):\n    score = 0\n    for i in range(len(answers)):\n        if answers[i] == correct_answers[i]:\n            score += 1\n    return [score, len(answers)]\n', 'def score_quiz(answers, correct_answers):\n    score = 0\n    for i in range(len(answers)):\n        if answers[i].lower() == correct_answers[i].lower():\n            score += 1\n    return [score, len(answers)]\n', 'function', 'score_quiz', 'Case-insensitive comparison is never automatic in Python - it always needs an explicit `.lower()` (or `.upper()`) applied to both sides being compared.', 'When a brief says a comparison should ignore something (case, whitespace), check the code actually normalises both sides before comparing - `==` alone never does that for you.', 'What do you think `score_quiz([\"A\", \"b\", \"C\"], [\"a\", \"B\", \"D\"])` returns? Write it down before you run anything.', 'published', '8e15267690c1f0905e1119d8d2cbf906dd0983816d36389f4b7537e27c9ee740', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (290, 'word-frequency-counter', 15, 'Word Frequency Counter', 15, 4, NULL, 'mixed', '`word_frequencies(text)` should return a dictionary mapping each word (lowercased) to how many times it appears.\n\nExample: `word_frequencies(\"The cat sat. The cat ran.\")` should return `{\"the\": 2, \"cat\": 2, \"sat.\": 1, \"ran.\": 1}`.', 'def word_frequencies(text):\n    counts = {}\n    words = text.split(\" \")\n    for word in words:\n        word = word.lower()\n        if word in counts:\n            counts[word] = counts[word] + 1\n    return counts\n', 'def word_frequencies(text):\n    counts = {}\n    words = text.split(\" \")\n    for word in words:\n        word = word.lower()\n        if word in counts:\n            counts[word] = counts[word] + 1\n        else:\n            counts[word] = 1\n    return counts\n', 'function', 'word_frequencies', 'A frequency counter needs both cases handled: \"I have seen this before, add one\" and \"this is the first time, start at one\". Handling only the first case silently drops every word that only appears once.', 'When building up counts in a dictionary, check both the \"already seen\" and \"first time seen\" paths are handled.', 'What do you think `word_frequencies(\"a a b\")` returns? Write it down before you run anything.', 'published', 'cb61a0ae1407e063a9692df0f92f76db24a7180c467cb7b9fce9dd9669454702', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (291, 'student-report-generator', 15, 'Student Report Generator', 16, 5, NULL, 'mixed', '`build_report(students)` takes a list of `[name, scores]` pairs and returns a list of `[name, average, pass_fail]`, where `pass_fail` is `\"Pass\"` if the average is 50 or above, else `\"Fail\"`.\n\nExample: `build_report([[\"Ada\", [80, 90]], [\"Sam\", [30, 40]]])` should return `[[\"Ada\", 85.0, \"Pass\"], [\"Sam\", 35.0, \"Fail\"]]`.', 'def average(scores):\n    total = 0\n    for s in scores:\n        total = s\n    return total / len(scores)\n\ndef pass_or_fail(avg):\n    if avg > 50:\n        return \"Pass\"\n    return \"Fail\"\n\ndef build_report(students):\n    report = []\n    for name, scores in students:\n        avg = average(scores)\n        result = pass_or_fail(avg)\n        report.append([name, avg, result])\n    return report\n', 'def average(scores):\n    total = 0\n    for s in scores:\n        total += s\n    return total / len(scores)\n\ndef pass_or_fail(avg):\n    if avg >= 50:\n        return \"Pass\"\n    return \"Fail\"\n\ndef build_report(students):\n    report = []\n    for name, scores in students:\n        avg = average(scores)\n        result = pass_or_fail(avg)\n        report.append([name, avg, result])\n    return report\n', 'function', 'build_report', 'This combines a broken accumulator (the running total is never actually accumulated) with a boundary mistake in a completely separate function - fixing one does not fix the other, and the broken average has to be fixed first before the pass/fail boundary can even be meaningfully tested.', 'In a multi-step pipeline, verify each stage independently (does the average alone look right?) before judging the stages built on top of it.', 'What do you think `build_report([[\"Sam\", [50, 50]]])` returns? Write it down before you run anything.', 'published', 'f92c9eb1aed74ef8c6a08e7e216ff99fb2c180b773d0358142b76e2964745644', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (292, 'temperature-batch-convert', 15, 'Temperature Batch Converter', 17, 4, NULL, 'mixed', '`celsius_list_to_fahrenheit(temps)` should convert a list of Celsius temperatures to Fahrenheit, using `F = C * 9/5 + 32`.\n\nExample: `celsius_list_to_fahrenheit([0, 100])` should return `[32.0, 212.0]`.', 'def to_fahrenheit(celsius):\n    return celsius * 9 / 5 + 32\n\ndef celsius_list_to_fahrenheit(temps):\n    result = []\n    for t in temps\n        result.append(to_fahrenheit(t))\n    return result\n', 'def to_fahrenheit(celsius):\n    return celsius * 9 / 5 + 32\n\ndef celsius_list_to_fahrenheit(temps):\n    result = []\n    for t in temps:\n        result.append(to_fahrenheit(t))\n    return result\n', 'function', 'celsius_list_to_fahrenheit', 'Even a program whose logic is entirely correct (the conversion formula here is right) still won\'t run at all if a block header is missing its colon - syntax errors block everything else from being checked.', 'Always get the code running at all before worrying about whether the formula itself is correct.', NULL, 'published', 'eae51e8327f583a220bd80d8261c32bc6d9bc25323a1f25ef1e1a8677c30aa06', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (293, 'library-catalog-search', 15, 'Library Catalog Search', 18, 4, NULL, 'mixed', '`find_books_by_author(catalog, author)` should return the titles of every book in `catalog` (a list of `[title, author]` pairs) written by `author`, matching case-insensitively.\n\nExample: `find_books_by_author([[\"Dune\", \"Herbert\"], [\"Emma\", \"Austen\"]], \"herbert\")` should return `[\"Dune\"]`.', 'def find_books_by_author(catalog, author):\n    titles = []\n    for title, book_author in catalog:\n        if book_author == author:\n            titles.append(title)\n    return title\n', 'def find_books_by_author(catalog, author):\n    titles = []\n    for title, book_author in catalog:\n        if book_author.lower() == author.lower():\n            titles.append(title)\n    return titles\n', 'function', 'find_books_by_author', 'A singular/plural naming mixup and a missing case-normalisation are independent mistakes here - fixing the return value alone would still leave author matching broken for any differently-cased input.', 'When a function builds a list in a loop, double check it actually returns that list - not a leftover loop variable with a similar name.', 'What do you think `find_books_by_author([[\"Dune\", \"Herbert\"], [\"Emma\", \"Austen\"]], \"herbert\")` returns? Write it down before you run anything.', 'published', '8fc563af6f91394567cfefd3f51ca53962a562fd50ba1665d1bc664e26b185b5', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (294, 'playlist-shuffle-manager', 15, 'Playlist Manager', 19, 4, NULL, 'mixed', '`move_to_front(playlist, song)` should move `song` to the front of the playlist (leaving the rest in order) and return the new playlist, without changing the list it was given.\n\nExpected output:\n```\n[\'a\', \'b\', \'c\']\n[\'c\', \'a\', \'b\']\n```', 'def move_to_front(playlist, song):\n    playlist.remove(song)\n    playlist.insert(0, song)\n    return playlist\n\noriginal = [\"a\", \"b\", \"c\"]\nmoved = move_to_front(original, \"c\")\nprint(original)\nprint(moved)\n', 'def move_to_front(playlist, song):\n    new_playlist = playlist.copy()\n    new_playlist.remove(song)\n    new_playlist.insert(0, song)\n    return new_playlist\n\noriginal = [\"a\", \"b\", \"c\"]\nmoved = move_to_front(original, \"c\")\nprint(original)\nprint(moved)\n', 'script', NULL, 'This function\'s return value is actually correct - the bug is a side effect the brief explicitly rules out (\"without changing the list it was given\"). In-place list methods always mutate whatever object you call them on, which is the caller\'s own list unless you copy it first.', 'If a function must not change its argument, check every mutating method call (`.remove()`, `.insert()`, `.append()`, `.sort()`, ...) is operating on a copy, not the original.', 'After calling `move_to_front(original, \"c\")`, do you think `original` itself is unchanged? Write down yes or no before you run anything.', 'published', '86e5e43b931e7cd963200858c4be169a2ee3a62ed57d49ab3f6532bbcf924123', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (295, 'contact-dedup', 15, 'Contact List Deduplication', 20, 5, NULL, 'mixed', '`deduplicate_contacts(contacts)` should return the contacts list with duplicate emails removed (keeping the first occurrence), comparing emails case-insensitively.\n\nExample: `deduplicate_contacts([[\"Ada\", \"a@x.com\"], [\"Sam\", \"A@X.com\"]])` should return `[[\"Ada\", \"a@x.com\"]]`.', 'def deduplicate_contacts(contacts):\n    seen_emails = []\n    result = []\n    for name, email in contacts:\n        if email not in seen_emails:\n            result.append([name, email])\n        seen_emails.append(email)\n    return result\n', 'def deduplicate_contacts(contacts):\n    seen_emails = []\n    result = []\n    for name, email in contacts:\n        if email.lower() not in seen_emails:\n            result.append([name, email])\n            seen_emails.append(email.lower())\n    return result\n', 'function', 'deduplicate_contacts', 'Both the check and the thing being checked against need to agree on case-sensitivity - normalising one side but not the other is just as broken as normalising neither.', 'When de-duplicating case-insensitively, check that every place an item is compared *and* every place it is recorded both apply the same normalisation.', 'What do you think `deduplicate_contacts([[\"Ada\", \"a@x.com\"], [\"Sam\", \"A@X.com\"]])` returns? Write it down before you run anything.', 'published', '97b756c62de8f2df3c5199c051a20065cf4eb7696c64c1e773c67f0b7cbdead9', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (296, 'palindrome-checker-detailed', 15, 'Palindrome Checker', 21, 4, NULL, 'mixed', '`is_palindrome(text)` should return whether `text` reads the same forwards and backwards, ignoring case and spaces.\n\nExample: `is_palindrome(\"Was it a car or a cat I saw\")` should return `True`.', 'def clean(text):\n    result = \"\"\n    for ch in text:\n        if ch != \" \":\n            result = result + ch\n    return result\n\ndef is_palindrome(text):\n    cleaned = clean(text)\n    return cleaned == cleaned[::-1]\n', 'def clean(text):\n    result = \"\"\n    for ch in text:\n        if ch != \" \":\n            result = result + ch.lower()\n    return result\n\ndef is_palindrome(text):\n    cleaned = clean(text)\n    return cleaned == cleaned[::-1]\n', 'function', 'is_palindrome', 'The slicing trick `text[::-1]` to reverse a string is correct here - the bug is entirely in the cleaning step, which handles one normalisation (spaces) but forgets the other the brief explicitly asked for (case).', 'When a brief lists several things to normalise (\"ignoring case and spaces\"), check the code actually handles every one of them, not just the first.', 'What do you think `is_palindrome(\"Was it a car or a cat I saw\")` returns? Write it down before you run anything.', 'published', '9661a7702c33eb2ced433e04ef4d6878da1dd020ed13ab807e5fab4e2989632d', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (297, 'word-counter-detailed', 15, 'Detailed Word Counter', 22, 4, NULL, 'mixed', '`text_stats(text)` should return `[word_count, longest_word]` for the given text.\n\nExample: `text_stats(\"the quick brown fox\")` should return `[4, \"quick\"]`.', 'def text_stats(text):\n    words = text.split(\" \")\n    longest = \"\"\n    for word in words:\n        if len(word) > len(longest):\n            longest = word\n    return [len(words - 1), longest]\n', 'def text_stats(text):\n    words = text.split(\" \")\n    longest = \"\"\n    for word in words:\n        if len(word) > len(longest):\n            longest = word\n    return [len(words), longest]\n', 'function', 'text_stats', 'The word-count logic itself didn\'t need any adjustment at all - `len(words)` already gives the right count. The `- 1` looks like a leftover attempt at an off-by-one fix that was never actually needed, and it does not even apply to a list in the first place.', 'Before \"fixing\" an off-by-one with a quick `-1` or `+1`, check the original value was actually off by one in the first place - and that the operation is even valid for the type involved.', NULL, 'published', 'd904a2562c2e3fcb8b3796d747b9b7bef0d09de2048923370d6226de8a8891a4', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (298, 'shift-cipher-wraparound', 15, 'Shift Cipher With Wraparound', 23, 5, NULL, 'mixed', '`shift_encode(text, shift)` should shift every lowercase letter forward by `shift` places in the alphabet, wrapping around from `z` back to `a`. Non-letters pass through unchanged.\n\nExample: `shift_encode(\"xyz\", 3)` should return `\"abc\"`.', 'def shift_encode(text, shift):\n    result = \"\"\n    for ch in text:\n        if ch.isalpha():\n            code = ord(ch) - ord(\"a\") + shift\n            new_code = code % 26 + ord(\"a\")\n            result += chr(new_code)\n        else:\n            result = ch\n    return result\n', 'def shift_encode(text, shift):\n    result = \"\"\n    for ch in text:\n        if ch.isalpha():\n            code = ord(ch) - ord(\"a\") + shift\n            new_code = code % 26 + ord(\"a\")\n            result += chr(new_code)\n        else:\n            result += ch\n    return result\n', 'function', 'shift_encode', 'The wraparound shift arithmetic itself (`% 26`) is correct here - the bug is a classic accumulator mistake in the *other* branch, which silently discards everything built up so far whenever a non-letter is encountered.', 'In a loop building up a string or list, check every branch uses `+=`/`.append()` consistently - a single stray `=` resets everything accumulated before it.', 'What do you think `shift_encode(\"ab 1\", 1)` returns? Write it down before you run anything.', 'published', '7e7959ea3100a621eb8007f1d3dabc7189cddc4b321ef9dcd4ef828c39c19cfa', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (299, 'template-filler', 15, 'Letter Template Filler', 24, 4, NULL, 'mixed', '`fill_template(template, values)` should replace every `{key}` placeholder in `template` with the matching value from the `values` dictionary.\n\nExample: `fill_template(\"Hi {name}, you are {age}\", {\"name\": \"Ada\", \"age\": 12})` should return `\"Hi Ada, you are 12\"`.', 'def fill_template(template, values):\n    result = template\n    for key in values:\n        placeholder = \"{\" + key + \"}\"\n        result = result.replace(placeholder, values[key])\n    return result\n', 'def fill_template(template, values):\n    result = template\n    for key in values:\n        placeholder = \"{\" + key + \"}\"\n        result = result.replace(placeholder, str(values[key]))\n    return result\n', 'function', 'fill_template', 'String methods like `.replace()` are strict about their argument types - they don\'t automatically convert a number into its text representation for you, even though that conversion is usually exactly what you want.', 'Before handing a dictionary value to a string method, consider whether it could ever be something other than a string - and convert it explicitly if so.', 'What do you think `fill_template(\"Hi {name}, you are {age}\", {\"name\": \"Ada\", \"age\": 12})` does - does it run cleanly? Write your guess down before you run anything.', 'published', '17df1c492c631de93294a9cfebc09380963c7974639f87c6d14bc8be269d2e86', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (300, 'bubble-sort-implementation', 15, 'Bubble Sort', 25, 5, NULL, 'mixed', '`bubble_sort(numbers)` should return a new list with the numbers sorted in ascending order, without changing the original list.\n\nExpected output:\n```\n[5, 2, 4, 1]\n[1, 2, 4, 5]\n```', 'def bubble_sort(numbers):\n    result = numbers\n    n = len(result)\n    for i in range(n):\n        for j in range(n - i - 1):\n            if result[j] > result[j + 1]:\n                result[j], result[j + 1] = result[j + 1], result[j]\n    return result\n\noriginal = [5, 2, 4, 1]\nsorted_list = bubble_sort(original)\nprint(original)\nprint(sorted_list)\n', 'def bubble_sort(numbers):\n    result = numbers.copy()\n    n = len(result)\n    for i in range(n):\n        for j in range(n - i - 1):\n            if result[j] > result[j + 1]:\n                result[j], result[j + 1] = result[j + 1], result[j]\n    return result\n\noriginal = [5, 2, 4, 1]\nsorted_list = bubble_sort(original)\nprint(original)\nprint(sorted_list)\n', 'script', NULL, 'The bubble sort algorithm itself is implemented correctly here - swapping adjacent out-of-order pairs, repeatedly, is exactly right. The bug is entirely about aliasing: forgetting to copy before sorting in place.', 'When a sorting function is meant to return a new, sorted list without touching the original, check it copies the input before any in-place swaps.', 'After calling `bubble_sort(original)`, do you think `original` itself changed too? Write down yes or no before you run anything.', 'published', 'c5ad2f64aef7f804cfd316d5f70627dba8c164a5048ed257e1ffa1268ff46801', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (301, 'linear-search-with-count', 15, 'Linear Search With a Comparison Count', 26, 4, NULL, 'mixed', '`search_with_count(items, target)` should return `[index, comparisons]` - the index of `target` in `items` (or `-1` if not found), and how many comparisons were made.\n\nExample: `search_with_count([5, 3, 8, 1], 8)` should return `[2, 3]`.', 'def search_with_count(items, target):\n    comparisons = 0\n    for i in range(len(items)):\n        if items[i] == target:\n            comparisons = comparisons + 1\n            return [i, comparisons]\n    return [-1, comparisons]\n', 'def search_with_count(items, target):\n    comparisons = 0\n    for i in range(len(items)):\n        comparisons = comparisons + 1\n        if items[i] == target:\n            return [i, comparisons]\n    return [-1, comparisons]\n', 'function', 'search_with_count', 'Counting \"how many comparisons were made\" needs the counter to increase on every attempt, not just the one that happened to succeed - moving the increment inside the `if` silently undercounts every search that does not match on the first try.', 'When counting attempts rather than successes, check the increment runs for every attempt, not only the ones that match a condition.', 'What do you think `search_with_count([5, 3, 8, 1], 8)` returns for the comparison count? Write it down before you run anything.', 'published', '89330e4da3788822d8bb65bc96ac66bf9f61db1837aafc3255b080e6846396f7', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (302, 'stack-simulation', 15, 'Stack Simulation', 27, 5, NULL, 'mixed', '`run_operations(operations)` simulates a stack: each operation is `[\"push\", value]` or `[\"pop\"]`. It should return the final stack contents as a list, bottom to top. Popping an empty stack should be ignored (not crash).\n\nExample: `run_operations([[\"push\", 1], [\"push\", 2], [\"pop\"]])` should return `[1]`.', 'def run_operations(operations):\n    stack = []\n    for op in operations:\n        if op[0] == \"push\":\n            stack.append(op[1])\n        elif op[0] == \"pop\":\n            stack.pop(0)\n    return stack\n', 'def run_operations(operations):\n    stack = []\n    for op in operations:\n        if op[0] == \"push\":\n            stack.append(op[1])\n        elif op[0] == \"pop\":\n            if stack:\n                stack.pop()\n    return stack\n', 'function', 'run_operations', 'A stack and a queue are both built on a list, but they pop from opposite ends - mixing them up gives genuinely different (but not obviously \"wrong looking\") behaviour. Separately, any operation on a list needs a guard for the empty case if it should not crash.', 'For stack/queue code, double-check which end `.pop()` is actually removing from, and whether empty-collection edge cases are guarded against.', 'What do you think `run_operations([[\"push\", 1], [\"push\", 2], [\"pop\"]])` returns? Write it down before you run anything.', 'published', '00908c5a6800fee021b56f74908ddbe6aeeaeb9a3dd73fc745b60c26febfaaa0', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (303, 'queue-simulation', 15, 'Queue Simulation', 28, 4, NULL, 'mixed', '`serve_next(queue)` should remove and return the person at the front of the queue, or `None` if the queue is empty - without crashing either way.\n\nExample: for `queue = [\"Ada\", \"Sam\"]`, `serve_next(queue)` should return `\"Ada\"`.', 'def serve_next(queue):\n    return queue.pop(0)\n', 'def serve_next(queue):\n    if not queue:\n        return None\n    return queue.pop(0)\n', 'function', 'serve_next', 'This one is a single, clean missing-guard bug: the queue logic itself (`.pop(0)` for front-removal) is correct, it just needed an empty check added.', 'Any function working on a collection that might be empty needs an explicit empty-check if it should not crash.', NULL, 'published', 'd0248b2b6dddaefd97f14dfdbaafa10afd95619b7ecf6a422afe808aad658545', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (304, 'gcd-lcm-calculator', 15, 'GCD and LCM Calculator', 29, 5, NULL, 'mixed', '`gcd_and_lcm(a, b)` should return `[gcd, lcm]` for two positive integers.\n\nExample: `gcd_and_lcm(12, 18)` should return `[6, 36]`.', 'def gcd(a, b):\n    while b != 0:\n        a, b = b, a % b\n    return a\n\ndef gcd_and_lcm(a, b):\n    g = gcd(a, b)\n    l = (a + b) // g\n    return [g, l]\n', 'def gcd(a, b):\n    while b != 0:\n        a, b = b, a % b\n    return a\n\ndef gcd_and_lcm(a, b):\n    g = gcd(a, b)\n    l = a * b // g\n    return [g, l]\n', 'function', 'gcd_and_lcm', 'The Euclidean algorithm for GCD here is correctly implemented. The LCM formula itself uses the wrong operator - addition instead of multiplication - giving a completely different (and wrong) number even though the code runs without error.', 'When a formula combines several values, check each operator against the actual mathematical definition - a wrong operator often still produces a plausible-looking number.', 'What do you think `gcd_and_lcm(12, 18)` returns? Write it down before you run anything.', 'published', '5ca56296f207c95987deb0e81931a88ffaf86baa6341da0749d9b17a3acd8dfc', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (305, 'fibonacci-sequence-generator', 15, 'Fibonacci Sequence Generator', 30, 4, NULL, 'mixed', '`fibonacci_sequence(n)` should return the first `n` numbers of the Fibonacci sequence (starting `0, 1, 1, 2, 3, ...`).\n\nExample: `fibonacci_sequence(5)` should return `[0, 1, 1, 2, 3]`.', 'def fibonacci_sequence(n):\n    if n == 0:\n        return []\n    sequence = [1, 1]\n    for i in range(n - 2):\n        sequence.append(sequence[-1] + sequence[-2])\n    return sequence[:n]\n', 'def fibonacci_sequence(n):\n    if n == 0:\n        return []\n    sequence = [0, 1]\n    for i in range(n - 2):\n        sequence.append(sequence[-1] + sequence[-2])\n    return sequence[:n]\n', 'function', 'fibonacci_sequence', 'The loop and the final slice are both correct here - the bug is entirely in the two starting values the sequence is seeded with, which quietly shifts every single output by one position along the real sequence.', 'For any sequence built from fixed starting values, check those seed values against the very first few terms the brief describes.', 'What do you think `fibonacci_sequence(5)` returns? Write it down before you run anything.', 'published', 'acec83935368ae7f8faebd9a8c85ab673a7b4af61f191953f775b978fccb7d4a', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (306, 'number-guessing-game-logic', 15, 'Number Guessing Game Logic', 31, 4, NULL, 'mixed', '`check_guess(secret, guess)` should return `\"Too high\"`, `\"Too low\"`, or `\"Correct\"`.\n\nExample: `check_guess(50, 70)` should return `\"Too high\"`.', 'def check_guess(secret, guess):\n    if guess > secret:\n        return \"Too low\"\n    elif guess < secret:\n        return \"Too high\"\n    else:\n        return \"Correct\"\n', 'def check_guess(secret, guess):\n    if guess > secret:\n        return \"Too high\"\n    elif guess < secret:\n        return \"Too low\"\n    else:\n        return \"Correct\"\n', 'function', 'check_guess', 'The comparisons themselves are exactly right - it\'s purely the labels attached to each outcome that got swapped, which is easy to do and easy to miss since the code still runs with no error.', 'For any \"too high/too low\" style feedback, test with a guess that is obviously on one side and check the message matches, not just that a message comes back.', NULL, 'published', '61647e38a9c1031f86557a91ae8e88916b50921289b5ba28788e86d87605d721', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (307, 'matrix-transpose', 15, 'Matrix Transpose', 32, 5, NULL, 'mixed', '`transpose(matrix)` should return the transpose of a rectangular matrix (rows become columns).\n\nExample: `transpose([[1, 2, 3], [4, 5, 6]])` should return `[[1, 4], [2, 5], [3, 6]]`.', 'def transpose(matrix):\n    rows = len(matrix)\n    cols = len(matrix[0])\n    result = [[0] * rows] * cols\n    for r in range(rows):\n        for c in range(cols):\n            result[c][r] = matrix[r][c]\n    return result\n', 'def transpose(matrix):\n    rows = len(matrix)\n    cols = len(matrix[0])\n    result = [[0] * rows for _ in range(cols)]\n    for r in range(rows):\n        for c in range(cols):\n            result[c][r] = matrix[r][c]\n    return result\n', 'function', 'transpose', 'The transpose algorithm (swapping row and column indexes) is correct - the bug is entirely in how the empty result grid gets built, the same nested-list-multiplication trap as building any 2D grid.', 'Whenever you build an empty 2D grid with `[[...]] * n`, check it actually creates independent rows, not `n` names for the same one.', 'What do you think `transpose([[1, 2], [3, 4]])` returns? Write it down before you run anything.', 'published', '3cd95070f76a20a96c1b7b2b698194782dd862d955c4e0814c24abc868264a41', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (308, 'run-length-encoding', 15, 'Run-Length Encoding', 33, 5, NULL, 'mixed', '`encode(text)` should compress runs of repeated characters, returning a list of `[character, count]` pairs.\n\nExample: `encode(\"aaabbc\")` should return `[[\"a\", 3], [\"b\", 2], [\"c\", 1]]`.', 'def encode(text):\n    if not text:\n        return []\n    result = []\n    current = text[0]\n    count = 1\n    for ch in text[1:]:\n        if ch == current:\n            count += 1\n        else:\n            result.append([current, count])\n            current = ch\n            count = 1\n    return result\n', 'def encode(text):\n    if not text:\n        return []\n    result = []\n    current = text[0]\n    count = 1\n    for ch in text[1:]:\n        if ch == current:\n            count += 1\n        else:\n            result.append([current, count])\n            current = ch\n            count = 1\n    result.append([current, count])\n    return result\n', 'function', 'encode', 'This is a common \"off the end\" loop bug: logic that only reacts to a *change* will always miss whatever was still accumulating when the loop runs out of input - the last group needs to be flushed out manually once the loop is done.', 'In a loop that only records a result when something *changes*, check whether the final, still-accumulating state ever gets recorded after the loop ends.', 'What do you think `encode(\"aaabbc\")` returns - specifically, does the last letter make it into the result? Write it down before you run anything.', 'published', '96a9b7fcaf1ac6083f467c745202bb3ce5cff2a82815ec9c3ddad57d1d90ff68', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (309, 'unit-converter-multi', 15, 'Multi-Unit Length Converter', 34, 4, NULL, 'mixed', '`convert_length(value, from_unit, to_unit)` should convert a length between `\"cm\"`, `\"m\"` and `\"km\"`.\n\nExample: `convert_length(150, \"cm\", \"m\")` should return `1.5`.', 'def to_cm(value, unit):\n    if unit == \"cm\":\n        return value\n    elif unit == \"m\":\n        return value * 100\n    elif unit == \"km\":\n        return value * 100000\n\ndef from_cm(value, unit):\n    if unit == \"cm\":\n        return value\n    elif unit == \"m\":\n        return value / 100\n    elif unit == \"km\":\n        return value * 100000\n\ndef convert_length(value, from_unit, to_unit):\n    cm = to_cm(value, from_unit)\n    return from_cm(cm, to_unit)\n', 'def to_cm(value, unit):\n    if unit == \"cm\":\n        return value\n    elif unit == \"m\":\n        return value * 100\n    elif unit == \"km\":\n        return value * 100000\n\ndef from_cm(value, unit):\n    if unit == \"cm\":\n        return value\n    elif unit == \"m\":\n        return value / 100\n    elif unit == \"km\":\n        return value / 100000\n\ndef convert_length(value, from_unit, to_unit):\n    cm = to_cm(value, from_unit)\n    return from_cm(cm, to_unit)\n', 'function', 'convert_length', 'Converting to a bigger unit always means dividing (the same real-world length becomes a smaller number), and converting to a smaller unit always means multiplying - this bug applied the multiply from the \"to cm\" direction without flipping it for the \"from cm\" direction.', 'For unit conversions, check which direction you are converting - \"to a bigger unit\" should always shrink the number, never grow it.', 'What do you think `convert_length(100000, \"cm\", \"km\")` returns? Write it down before you run anything.', 'published', '250d436affcae46c9e8ef3358099e84e7068345c9200d3b99d48e8bce9edd257', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (310, 'calculator-with-history', 15, 'Calculator With History', 35, 5, NULL, 'mixed', '`calculate(expression_list, history=None)` takes a list of `[a, operator, b]` expressions, evaluates each one, appends the result to a history list, and returns the history. Calling it again without passing a history should start a fresh one, not continue the old one.\n\nExpected output:\n```\n[5]\n[9]\n```', 'def apply_op(a, operator, b):\n    if operator == \"+\":\n        return a + b\n    elif operator == \"-\":\n        return a - b\n    elif operator == \"*\":\n        return a * b\n    elif operator == \"/\":\n        return a / b\n\ndef calculate(expression_list, history=[]):\n    for a, operator, b in expression_list:\n        result = apply_op(a, operator, b)\n        history.append(result)\n    return history\n\nfirst = calculate([[2, \"+\", 3]])\nsecond = calculate([[10, \"-\", 1]])\nprint(first)\nprint(second)\n', 'def apply_op(a, operator, b):\n    if operator == \"+\":\n        return a + b\n    elif operator == \"-\":\n        return a - b\n    elif operator == \"*\":\n        return a * b\n    elif operator == \"/\":\n        return a / b\n\ndef calculate(expression_list, history=None):\n    if history is None:\n        history = []\n    for a, operator, b in expression_list:\n        result = apply_op(a, operator, b)\n        history.append(result)\n    return history\n\nfirst = calculate([[2, \"+\", 3]])\nsecond = calculate([[10, \"-\", 1]])\nprint(first)\nprint(second)\n', 'script', NULL, 'The arithmetic dispatch in `apply_op` is entirely correct - the bug is the classic mutable default argument trap, applied to a \"history\" list that is supposed to start fresh each time it is not explicitly continued.', 'Any function that builds up a list/dict across calls using a default argument needs the `None`-then-build-inside pattern if each call should be independent by default.', 'If you call `calculate([[2, \"+\", 3]])` and then `calculate([[10, \"-\", 1]])` separately, do you think the second call\'s history includes anything from the first? Write yes or no before you run anything.', 'published', '8df37a49f30e0579a3e549c09a001cc75ad6903b5334730212df9634ad8c0502', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (311, 'todo-list-manager', 15, 'Todo List Manager', 36, 4, NULL, 'mixed', '`complete_task(tasks, task_name)` should mark the task with the matching name as `\"done\": True` in the list of task dictionaries, and return the updated list. Task names should match exactly.\n\nExample: `complete_task([{\"name\": \"Essay\", \"done\": False}], \"Essay\")` should return `[{\"name\": \"Essay\", \"done\": True}]`.', 'def complete_task(tasks, task_name):\n    for task in tasks:\n        if task[\"name\"] == task_name:\n            task[\"done\"] = True\n            return tasks\n    return tasks\n', 'def complete_task(tasks, task_name):\n    for task in tasks:\n        if task[\"name\"] == task_name:\n            task[\"done\"] = True\n    return tasks\n', 'function', 'complete_task', 'An early `return` the moment a match is found is a very natural thing to write, but it quietly assumes names are always unique - which the brief never actually promised. Letting the loop run to completion marks every match, not just the first.', 'Before returning early the moment a loop finds one match, check whether the brief actually guarantees there is only ever one.', 'If two tasks happen to have the same name, do you think both get marked done, or just one? Write your guess before you run anything.', 'published', '4856b26c7f58c3182f39e216827d1f3fba22403f67ebcc19add7fafadbc9066b', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (312, 'form-validation-checks', 15, 'Signup Form Validation', 37, 5, NULL, 'mixed', '`validate_signup(username, age)` should return a list of error messages: `\"Username too short\"` if under 3 characters, `\"Must be 13 or older\"` if under 13. Return an empty list if everything is valid.\n\nExample: `validate_signup(\"ab\", 10)` should return `[\"Username too short\", \"Must be 13 or older\"]`.', 'def validate_signup(username, age):\n    errors = []\n    if len(username) < 3:\n        errors.append(\"Username too short\")\n    if age < 13:\n        errors = [\"Must be 13 or older\"]\n    return errors\n', 'def validate_signup(username, age):\n    errors = []\n    if len(username) < 3:\n        errors.append(\"Username too short\")\n    if age < 13:\n        errors.append(\"Must be 13 or older\")\n    return errors\n', 'function', 'validate_signup', 'Building up a list of independent error messages needs every check to *add* to the list, not replace it - a single `=` where `.append()` was meant wipes out everything collected by earlier checks.', 'When accumulating multiple independent results (errors, matches, totals) in one list, check every single place that updates it uses `.append()`/`+=`, not plain `=`.', 'What do you think `validate_signup(\"ab\", 10)` returns? Write it down before you run anything.', 'published', '69c730a34626d577c18d1ca513ddc5b15bffb0bb0b2df473fef365aa12eb98a8', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (313, 'leaderboard-top-n', 15, 'Leaderboard Top N', 38, 5, NULL, 'mixed', '`top_n_players(scores, n)` takes a dictionary of `{name: score}` and returns the names of the top `n` players, highest score first.\n\nExample: `top_n_players({\"Ada\": 90, \"Sam\": 70, \"Bo\": 85}, 2)` should return `[\"Ada\", \"Bo\"]`.', 'def top_n_players(scores, n):\n    names = list(scores.keys())\n    names.sort()\n    return names[:n]\n', 'def top_n_players(scores, n):\n    names = list(scores.keys())\n    names.sort(key=lambda name: scores[name], reverse=True)\n    return names[:n]\n', 'function', 'top_n_players', 'Having the scores available in a separate dictionary doesn\'t help unless the sort is explicitly told to look them up - sorting the names list on its own just sorts the names.', 'When ranking one list by values stored in a separate dictionary, check the sort actually has a `key` that looks those values up.', 'What do you think `top_n_players({\"Ada\": 90, \"Sam\": 70, \"Bo\": 85}, 2)` returns? Write it down before you run anything.', 'published', '2553cd2dbc465dd0e609a6e894e761bbf8b0d2648b7ca60fa4f90605adffc8c9', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (314, 'anagram-checker', 15, 'Anagram Checker', 39, 4, NULL, 'mixed', '`are_anagrams(word1, word2)` should return whether the two words are anagrams of each other (contain exactly the same letters, ignoring case and spaces).\n\nExample: `are_anagrams(\"listen\", \"silent\")` should return `True`.', 'def clean(word):\n    result = \"\"\n    for ch in word:\n        if ch != \" \":\n            result += ch.lower()\n    return result\n\ndef are_anagrams(word1, word2):\n    a = clean(word1)\n    b = clean(word2)\n    return a == b\n', 'def clean(word):\n    result = \"\"\n    for ch in word:\n        if ch != \" \":\n            result += ch.lower()\n    return result\n\ndef are_anagrams(word1, word2):\n    a = clean(word1)\n    b = clean(word2)\n    return sorted(a) == sorted(b)\n', 'function', 'are_anagrams', 'Cleaning the text (removing spaces, lower-casing) was done correctly - the actual anagram check was missing. Sorting both words\' letters puts them into a canonical order that makes direct comparison meaningful.', 'To check two collections contain \"the same items in any order\", sort both and compare - plain `==` only matches identical order.', 'What do you think `are_anagrams(\"listen\", \"silent\")` returns? Write it down before you run anything.', 'published', '3307f6f33bd10b74137e19eea1b7c1b60e36b77630823694ae0a6605056c34fe', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_puzzles` VALUES (315, 'simple-budget-tracker', 15, 'Simple Budget Tracker', 40, 5, NULL, 'mixed', '`apply_transactions(balance, transactions)` takes a starting balance and a list of `[type, amount]` transactions (`\"deposit\"` or `\"withdrawal\"`), and returns the final balance. A withdrawal that would make the balance negative should be skipped.\n\nExample: `apply_transactions(100, [[\"deposit\", 50], [\"withdrawal\", 30]])` should return `120`.', 'def apply_transactions(balance, transactions):\n    for kind, amount in transactions:\n        if kind == \"deposit\":\n            balance += amount\n        elif kind == \"withdrawal\":\n            if balance - amount >= 0:\n                balance -= amount\n    return amount\n', 'def apply_transactions(balance, transactions):\n    for kind, amount in transactions:\n        if kind == \"deposit\":\n            balance += amount\n        elif kind == \"withdrawal\":\n            if balance - amount >= 0:\n                balance -= amount\n    return balance\n', 'function', 'apply_transactions', 'The deposit/withdrawal logic (including the guard against a negative balance) is entirely correct here - the bug is purely in which variable gets returned at the end, easy to mistype when both `balance` and `amount` are in scope and get updated throughout the loop.', 'When a function tracks more than one running value, double check the final `return` names the one that actually matters, not just any variable that happens to be in scope.', 'What do you think `apply_transactions(100, [[\"deposit\", 50], [\"withdrawal\", 30]])` returns? Write it down before you run anything.', 'published', '4ecf76e8c2a8fc29f1021adb1dab8b7f78e581dc77a9e7010db4b23744057356', '2026-11-22 20:26:15', NULL, '2026-11-22 20:26:15', '2026-11-22 20:26:15');
INSERT INTO `bh_tracks` VALUES (11, 'spot-the-typo', 'Spot the Typo', 'Syntax errors: the code won\'t even run yet.', 'Every puzzle here fails before it even starts. You\'ll learn to read `SyntaxError` and `IndentationError` messages and fix the shape of the code, not its logic.', 'syntax', 'none', 1, 'published');
INSERT INTO `bh_tracks` VALUES (12, 'crash-course', 'Crash Course', 'Runtime errors: the code runs, then crashes partway through.', 'These puzzles run until something goes wrong. You\'ll learn to read a traceback from the bottom up and recognise what each exception type is telling you.', 'runtime', 'basic', 2, 'published');
INSERT INTO `bh_tracks` VALUES (13, 'wrong-answer', 'Wrong Answer', 'The code runs fine and gives you a confidently wrong answer.', 'No errors here - just the wrong result. You\'ll compare expected vs actual output and get used to checking boundary values by hand.', 'logic', 'full', 3, 'published');
INSERT INTO `bh_tracks` VALUES (14, 'deep-bugs', 'Deep Bugs', 'Subtler logic bugs that need a trace table to really see.', 'These bugs hide in state, scope and recursion. You\'ll use trace tables and variable watch to see what\'s really happening, step by step.', 'logic', 'full', 4, 'published');
INSERT INTO `bh_tracks` VALUES (15, 'boss-fights', 'Boss Fights', 'Bigger programs with more than one bug hiding in them.', 'Multiple bugs, longer code. You\'ll divide and conquer, build minimal examples, and work the full debugging loop end to end.', 'mixed', 'full', 5, 'published');
